window.ETSDATA=window.ETSDATA||{};window.ETSDATA[18]={"lc":{"p1":[{"n":1,"opts":["She's taking off her badge.","She's leaning over a desk.","She's locking a door.","She's lifting a bin."],"vi":["Cô ấy đang tháo thẻ tên ra.","Cô ấy đang cúi người qua một cái bàn làm việc.","Cô ấy đang khóa cửa.","Cô ấy đang nhấc một cái thùng (rác) lên."],"ans":"D","xp":"Trong ảnh người phụ nữ đang nhấc thùng rác lên → (D) đúng. (A) không có hành động tháo thẻ tên; (B) không có cái bàn nào; (C) cô ấy không khóa cửa.","a":"E24-T08-01.mp3","img":"q1.jpg"},{"n":2,"opts":["A man is repairing a railing.","A man is climbing some stairs.","A man is carrying a ladder.","A man is looking up at a roof."],"vi":["Một người đàn ông đang sửa lan can.","Một người đàn ông đang leo cầu thang.","Một người đàn ông đang mang một cái thang.","Một người đàn ông đang ngước nhìn lên mái nhà."],"ans":"B","xp":"Người đàn ông đang bước lên các bậc cầu thang → (B) đúng. (A) anh ấy không sửa lan can; (C) không có cái thang (ladder) nào; (D) anh ấy không ngước nhìn mái nhà.","a":"E24-T08-02.mp3","img":"q2.jpg"},{"n":3,"opts":["A person is swimming in a lake.","A sign is posted on a building.","A bird is resting on a pole.","A person is rowing a boat."],"vi":["Một người đang bơi trong hồ.","Một tấm biển được gắn trên tòa nhà.","Một con chim đang đậu nghỉ trên cột.","Một người đang chèo thuyền."],"ans":"D","xp":"Trên mặt nước có một người đang chèo thuyền → (D) đúng. (A) không ai đang bơi; (B) không thấy tấm biển nào; (C) không có con chim nào.","a":"E24-T08-03.mp3","img":"q3.jpg"},{"n":4,"opts":["One of the workers is opening a display case.","One of the workers is tying a necktie.","The workers are behind a counter.","The workers are greeting some customers."],"vi":["Một trong những nhân viên đang mở tủ trưng bày.","Một trong những nhân viên đang thắt cà vạt.","Các nhân viên đang đứng sau quầy.","Các nhân viên đang chào đón khách hàng."],"ans":"C","xp":"Các nhân viên đang đứng phía sau quầy hàng → (C) đúng (mô tả vị trí). (A) không ai mở tủ trưng bày; (B) không ai thắt cà vạt; (D) họ không chào khách.","a":"E24-T08-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some rocks are piled in a wheelbarrow.","Some telephone wires are suspended over a road.","Some benches are occupied.","Some trees are shading a picnic table."],"vi":["Một ít đá được chất trong xe cút kít.","Những sợi dây điện thoại được treo phía trên con đường.","Những chiếc ghế dài đang có người ngồi.","Cây cối đang che bóng mát cho một bàn picnic."],"ans":"B","xp":"Trong ảnh có dây điện thoại treo ngang phía trên đường → (B) đúng. (A) không có xe cút kít (wheelbarrow); (C) ghế không có ai ngồi (occupied = có người ngồi); (D) cây không che bóng cho bàn picnic.","a":"E24-T08-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some papers have been pinned to a bulletin board.","A clock has been set on a bedside table.","A painting has been propped against a chair.","Some medical equipment has been placed on a shelf."],"vi":["Một số giấy tờ đã được ghim lên bảng thông báo.","Một chiếc đồng hồ đã được đặt trên bàn cạnh giường.","Một bức tranh đã được dựng tựa vào ghế.","Một số thiết bị y tế đã được đặt trên kệ."],"ans":"A","xp":"Trên tường có bảng thông báo với giấy tờ được ghim lên → (A) đúng. (B) không có bàn cạnh giường; (C) không có bức tranh tựa vào ghế; (D) không có cái kệ (shelf) nào.","a":"E24-T08-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Who's picking up the newspaper?","qvi":"Ai sẽ đi lấy tờ báo?","opts":["Some paper napkins.","Camille said she will.","He took out the trash."],"vi":["Vài cái khăn giấy.","Camille nói cô ấy sẽ đi lấy.","Anh ấy đã đổ rác."],"ans":"B","xp":"Câu hỏi Who (ai) → (B) nêu đúng người: Camille sẽ đi lấy. (A) bẫy âm: 'paper' giống 'newspaper'; (C) 'He' không biết là ai, nội dung không liên quan.","a":"E24-T08-07.mp3"},{"n":8,"q":"When is your doctor's appointment?","qvi":"Lịch hẹn khám bác sĩ của bạn là khi nào?","opts":["This afternoon.","That's a good point.","At a medical clinic."],"vi":["Chiều nay.","Ý đó hay đấy.","Ở một phòng khám."],"ans":"A","xp":"Câu hỏi When (khi nào) → (A) trả lời thời gian 'chiều nay'. (B) bẫy âm: 'point' giống 'appointment'; (C) trả lời nơi chốn (Where), bẫy liên tưởng từ 'doctor'.","a":"E24-T08-08.mp3"},{"n":9,"q":"Why don't we have a company picnic?","qvi":"Sao công ty mình không tổ chức một buổi dã ngoại nhỉ?","opts":["Potato salad and green beans.","Because it costs a lot of money.","I already have that one."],"vi":["Salad khoai tây và đậu que.","Vì nó tốn rất nhiều tiền.","Tôi đã có cái đó rồi."],"ans":"B","xp":"Ở đây câu hỏi được hiểu là hỏi lý do vì sao công ty không tổ chức dã ngoại → (B) đưa ra lý do: vì tốn nhiều tiền. (A) bẫy liên tưởng: món ăn dã ngoại; (C) lặp từ 'have', không liên quan.","a":"E24-T08-09.mp3"},{"n":10,"q":"What do you think I should take to the conference?","qvi":"Bạn nghĩ tôi nên mang gì đến hội nghị?","opts":["In the lobby.","Just your laptop.","A three o'clock shift."],"vi":["Ở sảnh.","Chỉ cần máy tính xách tay của bạn thôi.","Một ca làm lúc ba giờ."],"ans":"B","xp":"Hỏi nên mang gì → (B) trả lời cụ thể: chỉ cần laptop. (A) trả lời nơi chốn (Where); (C) không liên quan.","a":"E24-T08-10.mp3"},{"n":11,"q":"Where's the festival being held?","qvi":"Lễ hội được tổ chức ở đâu?","opts":["A music concert.","Probably sometime in December.","In the town center."],"vi":["Một buổi hòa nhạc.","Có lẽ vào khoảng tháng Mười Hai.","Ở trung tâm thị trấn."],"ans":"C","xp":"Câu hỏi Where (ở đâu) → (C) nêu địa điểm 'trung tâm thị trấn'. (A) bẫy liên tưởng với 'festival'; (B) trả lời thời gian (When).","a":"E24-T08-11.mp3"},{"n":12,"q":"Who do I present my proposal to?","qvi":"Tôi trình bày bản đề xuất của mình cho ai?","opts":["A hotel reservation.","The acquisitions committee.","At noon today."],"vi":["Một đặt phòng khách sạn.","Ủy ban thu mua (sáp nhập).","Vào trưa nay."],"ans":"B","xp":"Câu hỏi Who → (B) nêu đối tượng: ủy ban thu mua. (A) không liên quan; (C) trả lời thời gian (When).","a":"E24-T08-12.mp3"},{"n":13,"q":"Could you please look up the location on your phone?","qvi":"Bạn có thể tra địa điểm đó trên điện thoại giúp tôi được không?","opts":["Here's my phone number.","OK, one moment.","The weather is nice right now."],"vi":["Đây là số điện thoại của tôi.","Được, đợi chút nhé.","Lúc này thời tiết đẹp."],"ans":"B","xp":"Câu nhờ vả (Could you...?) → (B) đồng ý 'OK' và xin chờ một chút. (A) lặp từ 'phone'; (C) không liên quan.","a":"E24-T08-13.mp3"},{"n":14,"q":"Isn't the accounting seminar tomorrow?","qvi":"Hội thảo kế toán là ngày mai phải không?","opts":["I'd like to open an account, please.","Actually, it's on Friday.","Time management."],"vi":["Tôi muốn mở một tài khoản.","Thật ra là vào thứ Sáu.","Quản lý thời gian."],"ans":"B","xp":"Câu hỏi phủ định xác nhận lịch → (B) đính chính: thật ra là thứ Sáu (không phải ngày mai). (A) bẫy từ gần giống 'account' – 'accounting'; (C) liên tưởng tới chủ đề hội thảo.","a":"E24-T08-14.mp3"},{"n":15,"q":"When's the dishwasher being repaired?","qvi":"Khi nào máy rửa bát được sửa?","opts":["The technician came this morning.","I store the knives in a separate drawer.","The bread is in the pantry."],"vi":["Thợ kỹ thuật đã đến sáng nay rồi.","Tôi cất dao trong một ngăn kéo riêng.","Bánh mì ở trong tủ đựng thức ăn."],"ans":"A","xp":"Hỏi khi nào sửa máy rửa bát → (A) trả lời gián tiếp: thợ đã đến sáng nay (tức là đã sửa xong rồi). (B) liên tưởng 'knives' với nhà bếp; (C) không liên quan.","a":"E24-T08-15.mp3"},{"n":16,"q":"Should we move the employee lounge to the basement?","qvi":"Chúng ta có nên chuyển phòng nghỉ nhân viên xuống tầng hầm không?","opts":["He attended the talk.","The reservation is for two people.","No, it's too dark down there."],"vi":["Anh ấy đã tham dự buổi nói chuyện.","Đặt chỗ cho hai người.","Không, dưới đó tối quá."],"ans":"C","xp":"Câu hỏi đề xuất (Should we...?) → (C) từ chối 'No' và nêu lý do: dưới đó quá tối. (A) 'He' không rõ là ai; (B) liên tưởng 'employee' → 'people'.","a":"E24-T08-16.mp3"},{"n":17,"q":"You changed the color printer cartridge recently, didn't you?","qvi":"Gần đây bạn đã thay hộp mực máy in màu, đúng không?","opts":["Right, just a few days ago.","They're painting the walls blue.","A different password."],"vi":["Đúng vậy, mới vài ngày trước.","Họ đang sơn tường màu xanh dương.","Một mật khẩu khác."],"ans":"A","xp":"Câu hỏi đuôi xác nhận → (A) xác nhận 'Right' và bổ sung: vài ngày trước. (B) liên tưởng 'color' → 'blue'; (C) liên tưởng 'changed' → 'different'.","a":"E24-T08-17.mp3"},{"n":18,"q":"We're not going to be able to fit everyone in this space.","qvi":"Chúng ta sẽ không thể xếp đủ chỗ cho mọi người trong không gian này.","opts":["A professional-development workshop.","There's a larger room down the hallway.","These shoes are exactly the right size."],"vi":["Một buổi hội thảo phát triển chuyên môn.","Có một phòng lớn hơn ở cuối hành lang.","Đôi giày này vừa đúng cỡ."],"ans":"B","xp":"Câu trần thuật nêu vấn đề (phòng không đủ chỗ) → (B) đưa giải pháp: có phòng lớn hơn ở cuối hành lang. (A) không liên quan; (C) bẫy liên tưởng 'fit' → 'right size'.","a":"E24-T08-18.mp3"},{"n":19,"q":"Is it easiest for me to take a bus to the city center?","qvi":"Đi xe buýt vào trung tâm thành phố có phải là tiện nhất với tôi không?","opts":["A new department store.","When did you buy it?","I usually do."],"vi":["Một trung tâm thương mại mới.","Bạn đã mua nó khi nào?","Tôi thường đi như vậy."],"ans":"C","xp":"Câu hỏi Yes/No → (C) trả lời gián tiếp: tôi thường đi xe buýt (ngụ ý là 'đúng, tiện nhất'). (A) liên tưởng 'city center' → 'department store'; (B) không liên quan.","a":"E24-T08-19.mp3"},{"n":20,"q":"Are you able to make a prototype soon?","qvi":"Bạn có thể sớm làm ra một mẫu thử không?","opts":["Yes, my team is working on it.","I thought it was very innovative.","He's a good typist."],"vi":["Có, nhóm tôi đang làm rồi.","Tôi nghĩ nó rất sáng tạo.","Anh ấy đánh máy giỏi."],"ans":"A","xp":"Câu hỏi Yes/No → (A) trả lời 'Yes' và nói nhóm đang làm. (B) liên tưởng 'prototype' → 'innovative'; (C) 'He' không rõ là ai.","a":"E24-T08-20.mp3"},{"n":21,"q":"Where can I buy a lamp like that?","qvi":"Tôi có thể mua một cái đèn như thế ở đâu?","opts":["On my desk.","I got this one as a gift.","After my client meeting."],"vi":["Trên bàn làm việc của tôi.","Tôi được tặng cái này.","Sau cuộc họp với khách hàng của tôi."],"ans":"B","xp":"Hỏi mua ở đâu → (B) trả lời gián tiếp: tôi được tặng, không tự mua nên không biết. (A) bẫy: chỉ vị trí của cái đèn, không phải nơi mua; (C) trả lời thời gian (When).","a":"E24-T08-21.mp3"},{"n":22,"q":"How often do you have to install updates?","qvi":"Bạn phải cài đặt cập nhật bao lâu một lần?","opts":["This letter needs more postage.","An incorrect serial code.","Waseem is the software administrator."],"vi":["Lá thư này cần thêm tem (cước bưu chính).","Một mã số sê-ri không đúng.","Waseem là người quản trị phần mềm."],"ans":"C","xp":"Hỏi tần suất (How often) → (C) trả lời gián tiếp: Waseem là người quản trị phần mềm (hãy hỏi anh ấy). (A) không liên quan; (B) liên tưởng 'updates' → 'serial code'.","a":"E24-T08-22.mp3"},{"n":23,"q":"Let's talk about your project after lunch.","qvi":"Sau bữa trưa chúng ta hãy bàn về dự án của bạn nhé.","opts":["Because her microphone is broken.","I'm leaving work early today.","I have two pairs of shoes."],"vi":["Vì micro của cô ấy bị hỏng.","Hôm nay tôi về sớm.","Tôi có hai đôi giày."],"ans":"B","xp":"Câu đề nghị (Let's...) → (B) từ chối gián tiếp: hôm nay tôi về sớm nên không thể bàn sau bữa trưa. (A) trả lời cho câu hỏi Why; (C) không liên quan.","a":"E24-T08-23.mp3"},{"n":24,"q":"Is there a list of guests who have been invited?","qvi":"Có danh sách khách đã được mời không?","opts":["Room 305 is being prepared for you.","The caterer has all the necessary information.","A banquet hall on Main Street."],"vi":["Phòng 305 đang được chuẩn bị cho bạn.","Bên cung cấp tiệc có đầy đủ thông tin cần thiết.","Một sảnh tiệc trên phố Main."],"ans":"B","xp":"Hỏi có danh sách khách mời không → (B) trả lời gián tiếp: bên dịch vụ ăn uống (caterer) có đủ thông tin, hãy hỏi họ. (A) liên tưởng 'guests' → phòng; (C) liên tưởng 'invited' → sảnh tiệc.","a":"E24-T08-24.mp3"},{"n":25,"q":"Would it be cheaper to ship by express mail or overnight delivery?","qvi":"Gửi bằng thư chuyển phát nhanh hay giao hàng qua đêm thì rẻ hơn?","opts":["Express mail is less expensive.","I'd like a large.","It's in the next shipment."],"vi":["Thư chuyển phát nhanh ít tốn kém hơn.","Tôi muốn cỡ lớn.","Nó nằm trong lô hàng tiếp theo."],"ans":"A","xp":"Câu hỏi lựa chọn (A or B) → (A) chọn một phương án: chuyển phát nhanh rẻ hơn (less expensive = cheaper). (B) không liên quan; (C) bẫy từ cùng gốc 'ship' – 'shipment'.","a":"E24-T08-25.mp3"},{"n":26,"q":"How do I turn on the air conditioner in this office?","qvi":"Làm sao để bật máy điều hòa trong văn phòng này?","opts":["The temperature is controlled automatically.","Turn left after the post office.","No, I shut off all the lights."],"vi":["Nhiệt độ được điều chỉnh tự động.","Rẽ trái sau bưu điện.","Không, tôi đã tắt hết đèn rồi."],"ans":"A","xp":"Hỏi cách bật điều hòa → (A) trả lời gián tiếp: nhiệt độ được điều chỉnh tự động, không cần tự bật. (B) lặp từ 'turn', 'office'; (C) câu hỏi How không trả lời Yes/No.","a":"E24-T08-26.mp3"},{"n":27,"q":"Have you trained Hikaru to use the new microscope?","qvi":"Bạn đã hướng dẫn Hikaru sử dụng kính hiển vi mới chưa?","opts":["I have my own car.","That's enough, thanks.","I misplaced the instruction manual."],"vi":["Tôi có xe riêng.","Đủ rồi, cảm ơn.","Tôi để lạc mất sách hướng dẫn rồi."],"ans":"C","xp":"Câu hỏi Yes/No → (C) trả lời gián tiếp: tôi làm mất sách hướng dẫn (nên chưa hướng dẫn được). (A) bẫy: nghe nhầm 'trained' thành 'train' (tàu hỏa) → 'car'; (B) không liên quan.","a":"E24-T08-27.mp3"},{"n":28,"q":"We're meeting this week to discuss the upcoming merger.","qvi":"Tuần này chúng ta sẽ họp để bàn về vụ sáp nhập sắp tới.","opts":["I have it on my calendar.","Please merge onto the highway.","A law firm in Glenview."],"vi":["Tôi đã ghi nó vào lịch rồi.","Vui lòng nhập làn vào đường cao tốc.","Một công ty luật ở Glenview."],"ans":"A","xp":"Câu thông báo lịch họp → (A) phản hồi: tôi đã ghi vào lịch (tức là đã biết). (B) bẫy từ cùng gốc 'merger' – 'merge'; (C) không liên quan.","a":"E24-T08-28.mp3"},{"n":29,"q":"How long will we have to wait for a taxi to arrive?","qvi":"Chúng ta sẽ phải đợi taxi đến trong bao lâu?","opts":["About twelve kilometers.","No, I don't think so.","Would you prefer to walk?"],"vi":["Khoảng mười hai ki-lô-mét.","Không, tôi không nghĩ vậy.","Bạn có muốn đi bộ không?"],"ans":"C","xp":"Hỏi phải chờ bao lâu → (C) hỏi ngược lại, gợi ý cách khác: bạn có muốn đi bộ thay vì chờ taxi không? (A) bẫy: trả lời khoảng cách, không phải thời gian; (B) câu hỏi How long không trả lời Yes/No.","a":"E24-T08-29.mp3"},{"n":30,"q":"Did the deal to lease the equipment go through?","qvi":"Thỏa thuận thuê thiết bị đã thành công chưa?","opts":["A one-bedroom apartment.","The supply catalog is in the filing cabinet.","Not yet—but we hope to have it finalized this quarter."],"vi":["Một căn hộ một phòng ngủ.","Danh mục vật tư nằm trong tủ hồ sơ.","Chưa – nhưng chúng tôi hy vọng sẽ hoàn tất trong quý này."],"ans":"C","xp":"Hỏi thỏa thuận đã được chấp thuận chưa (go through = thành công, được thông qua) → (C) 'Chưa' và cho thêm thông tin. (A) liên tưởng 'lease' → căn hộ; (B) liên tưởng 'equipment' → tủ hồ sơ.","a":"E24-T08-30.mp3"},{"n":31,"q":"Would you like to take this vehicle for a test drive?","qvi":"Bạn có muốn lái thử chiếc xe này không?","opts":["Because there's no parking available.","I heard a new model is coming out in March.","Only two doors."],"vi":["Vì không còn chỗ đậu xe.","Tôi nghe nói tháng Ba sẽ có mẫu mới ra mắt.","Chỉ có hai cửa."],"ans":"B","xp":"Lời mời lái thử → (B) từ chối gián tiếp: nghe nói tháng Ba có mẫu mới (nên muốn đợi). (A) liên tưởng 'vehicle/drive' → 'parking'; (C) liên tưởng 'vehicle' → 'two doors'.","a":"E24-T08-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Matteo, do you have time to help me organize the storage room? The construction crew's going to be starting renovations on the lobby next week. We need to make space to store the lobby furniture.","Matteo, anh có thời gian giúp tôi sắp xếp lại phòng kho không? Tuần sau đội thi công sẽ bắt đầu cải tạo sảnh. Chúng ta cần dọn chỗ để cất đồ nội thất ở sảnh."],["M","Actually, I know the plan is to replace those tables and chairs. Maybe we should just donate them now rather than putting them in storage.","Thật ra tôi biết là kế hoạch sẽ thay mới những bộ bàn ghế đó. Có lẽ chúng ta nên quyên góp chúng luôn bây giờ thay vì cất vào kho."],["W","Good idea! I'll do some research to see which organizations accept donations of furniture. I'm sure there are several in the area.","Ý hay đấy! Tôi sẽ tìm hiểu xem tổ chức nào nhận quyên góp đồ nội thất. Tôi chắc là trong khu vực có vài nơi."]],"qs":[{"n":32,"q":"According to the woman, what will happen next week?","qvi":"Theo người phụ nữ, điều gì sẽ diễn ra vào tuần sau?","opts":["A renovation project will begin.","A company will move to a new location.","Some technology will be updated.","Some new employees will be trained."],"vi":["Một dự án cải tạo sẽ bắt đầu.","Một công ty sẽ chuyển đến địa điểm mới.","Một số công nghệ sẽ được cập nhật.","Một số nhân viên mới sẽ được đào tạo."],"ans":"A","xp":"Người phụ nữ nói: \"The construction crew's going to be starting renovations on the lobby next week.\" (Tuần sau đội thi công sẽ bắt đầu cải tạo sảnh) → 'starting renovations' = 'A renovation project will begin' → (A)."},{"n":33,"q":"What does the man recommend?","qvi":"Người đàn ông đề xuất điều gì?","opts":["Ordering some equipment","Printing some instructions","Donating some furniture","Arranging a catered meal"],"vi":["Đặt mua một số thiết bị","In một số hướng dẫn","Quyên góp một số đồ nội thất","Sắp xếp một bữa ăn đặt tiệc"],"ans":"C","xp":"Người đàn ông nói: \"Maybe we should just donate them now rather than putting them in storage.\" ('them' = bàn ghế ở sảnh) → đề xuất quyên góp đồ nội thất → (C)."},{"n":34,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Meet a client","Research some options","Make a presentation","Sign a contract"],"vi":["Gặp khách hàng","Tìm hiểu một số lựa chọn","Thuyết trình","Ký hợp đồng"],"ans":"B","xp":"Người phụ nữ nói: \"I'll do some research to see which organizations accept donations of furniture.\" (Tôi sẽ tìm hiểu xem tổ chức nào nhận quyên góp) → tìm hiểu các lựa chọn → (B)."}],"a":"E24-T08-32-34.mp3"},{"ns":[35,37],"script":[["W","Hi, Liam. We're really glad to have you join our team. The harvest season is our busiest!","Chào Liam. Chúng tôi rất vui khi có bạn gia nhập đội. Mùa thu hoạch là lúc bận rộn nhất của chúng tôi!"],["M1","I'm excited to get started.","Tôi rất háo hức được bắt đầu."],["W","Let me introduce you to Brian. He will take you out to the berry fields for your training.","Để tôi giới thiệu bạn với Brian. Anh ấy sẽ đưa bạn ra cánh đồng dâu để huấn luyện."],["M2","Hi, Liam. Here's a pair of gloves for you to use.","Chào Liam. Đây là đôi găng tay cho bạn dùng."],["M1","Thanks!","Cảm ơn anh!"],["M2","The berry picking is really straightforward. But it's important that you get plenty of water and stay hydrated in this heat.","Việc hái dâu thực sự rất đơn giản. Nhưng điều quan trọng là bạn phải uống nhiều nước và giữ đủ nước cho cơ thể trong thời tiết nóng thế này."],["M1","I brought a big bottle of it with me, so I should be fine.","Tôi có mang theo một chai nước lớn nên chắc sẽ ổn thôi."]],"qs":[{"n":35,"q":"Where do the speakers most likely work?","qvi":"Những người nói nhiều khả năng làm việc ở đâu?","opts":["At a restaurant","At a farm","On a fishing boat","At a public park"],"vi":["Ở nhà hàng","Ở nông trại","Trên thuyền đánh cá","Ở công viên công cộng"],"ans":"B","xp":"Các manh mối: \"The harvest season is our busiest!\" (mùa thu hoạch) và \"He will take you out to the berry fields\" (cánh đồng dâu) → họ làm việc ở nông trại → (B)."},{"n":36,"q":"What does Brian give to Liam?","qvi":"Brian đưa cho Liam cái gì?","opts":["Some gloves","Some bags","A plastic bucket","A clipboard"],"vi":["Găng tay","Túi","Một cái xô nhựa","Một bìa kẹp hồ sơ"],"ans":"A","xp":"Brian (người đàn ông thứ hai) nói: \"Hi, Liam. Here's a pair of gloves for you to use.\" → đưa găng tay → (A)."},{"n":37,"q":"According to Brian, what is important?","qvi":"Theo Brian, điều gì là quan trọng?","opts":["Using sunscreen lotion","Labeling some items","Following a schedule","Drinking water"],"vi":["Dùng kem chống nắng","Dán nhãn một số đồ","Tuân theo lịch trình","Uống nước"],"ans":"D","xp":"Brian nói: \"it's important that you get plenty of water and stay hydrated in this heat.\" → 'get plenty of water' = 'Drinking water' → (D)."}],"a":"E24-T08-35-37.mp3"},{"ns":[38,40],"script":[["M","Welcome to my gardening podcast. I'm Rajesh Varma, and today I'm here with So-Jin Lee, a botanist from Denton University who recently developed a new hybrid flower. Could you tell us more, Professor Lee?","Chào mừng đến với podcast làm vườn của tôi. Tôi là Rajesh Varma, và hôm nay tôi có mặt cùng So-Jin Lee, nhà thực vật học của Đại học Denton, người vừa phát triển một giống hoa lai mới. Giáo sư Lee có thể kể thêm cho chúng tôi không?"],["W","Certainly. I developed a new type of rose—it's special because it blooms longer than any other rose.","Tất nhiên rồi. Tôi đã phát triển một loại hoa hồng mới – nó đặc biệt vì nở lâu hơn bất kỳ loại hoa hồng nào khác."],["M","That's interesting. Is it difficult to grow?","Thú vị thật. Nó có khó trồng không?"],["W","Not if it's planted under the right conditions. Next month, the rose will be featured at the botanical show downtown. I hope your listeners will come to see it.","Không khó nếu được trồng trong điều kiện thích hợp. Tháng sau, giống hồng này sẽ được giới thiệu tại triển lãm thực vật ở trung tâm thành phố. Tôi hy vọng thính giả của anh sẽ đến xem."]],"qs":[{"n":38,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["An event coordinator","A book publisher","A city official","A podcast host"],"vi":["Người điều phối sự kiện","Nhà xuất bản sách","Viên chức thành phố","Người dẫn chương trình podcast"],"ans":"D","xp":"Người đàn ông mở đầu: \"Welcome to my gardening podcast. I'm Rajesh Varma...\" → anh ấy là người dẫn podcast → (D)."},{"n":39,"q":"What does the woman say is special about a flower?","qvi":"Người phụ nữ nói điều gì đặc biệt ở một loài hoa?","opts":["It is resistant to insects.","It has an unusual color.","It can bloom for a long time.","It has a unique smell."],"vi":["Nó kháng được côn trùng.","Nó có màu sắc lạ.","Nó có thể nở hoa trong thời gian dài.","Nó có mùi hương độc đáo."],"ans":"C","xp":"Người phụ nữ nói: \"it's special because it blooms longer than any other rose.\" → 'blooms longer' = 'can bloom for a long time' → (C)."},{"n":40,"q":"What will happen next month?","qvi":"Điều gì sẽ diễn ra vào tháng sau?","opts":["A botanical show will be held.","A public garden will open.","An experiment will be conducted.","A gardening class will be offered."],"vi":["Một triển lãm thực vật sẽ được tổ chức.","Một khu vườn công cộng sẽ mở cửa.","Một thí nghiệm sẽ được tiến hành.","Một lớp học làm vườn sẽ được mở."],"ans":"A","xp":"Người phụ nữ nói: \"Next month, the rose will be featured at the botanical show downtown.\" → tháng sau có triển lãm thực vật → (A)."}],"a":"E24-T08-38-40.mp3"},{"ns":[41,43],"script":[["W","So, Vivek, I think our employees could benefit from some more training. How about using this software application that I found? The app provides a platform for uploading our own training videos. And employees could view them on their phones at any time.","Vivek này, tôi nghĩ nhân viên của chúng ta sẽ được lợi nếu được đào tạo thêm. Hay là dùng ứng dụng phần mềm mà tôi tìm được này nhé? Ứng dụng cung cấp nền tảng để tải lên video đào tạo của riêng mình. Và nhân viên có thể xem trên điện thoại bất cứ lúc nào."],["M","You know, I've heard that those online programs help employees retain knowledge. But aren't those apps expensive?","Tôi có nghe nói các chương trình trực tuyến như vậy giúp nhân viên ghi nhớ kiến thức. Nhưng mấy ứng dụng đó không đắt sao?"],["W","Actually, the cost is reasonable. And the Web site has some interesting reviews from other businesses that have used the app and found it helpful.","Thật ra chi phí khá hợp lý. Và trang web có một số đánh giá thú vị từ các doanh nghiệp khác đã dùng ứng dụng và thấy nó hữu ích."]],"qs":[{"n":41,"q":"What does the woman propose doing?","qvi":"Người phụ nữ đề xuất làm gì?","opts":["Hiring a computer technician","Using a training application","Replacing some printers","Changing business hours"],"vi":["Thuê một kỹ thuật viên máy tính","Sử dụng một ứng dụng đào tạo","Thay một số máy in","Thay đổi giờ làm việc"],"ans":"B","xp":"Người phụ nữ nói: \"How about using this software application that I found? The app provides a platform for uploading our own training videos.\" → đề xuất dùng ứng dụng đào tạo → (B)."},{"n":42,"q":"What is the man concerned about?","qvi":"Người đàn ông lo lắng về điều gì?","opts":["Scheduling delays","Employee satisfaction","The cost of a product","The quality of a product"],"vi":["Sự chậm trễ lịch trình","Sự hài lòng của nhân viên","Chi phí của một sản phẩm","Chất lượng của một sản phẩm"],"ans":"C","xp":"Người đàn ông hỏi: \"But aren't those apps expensive?\" (Mấy ứng dụng đó không đắt sao?) → lo về giá → (C)."},{"n":43,"q":"According to the woman, what can be found on a Web site?","qvi":"Theo người phụ nữ, có thể tìm thấy gì trên một trang web?","opts":["A company address","Customer reviews","A chat feature","Discount coupons"],"vi":["Địa chỉ công ty","Đánh giá của khách hàng","Tính năng trò chuyện","Phiếu giảm giá"],"ans":"B","xp":"Người phụ nữ nói: \"the Web site has some interesting reviews from other businesses that have used the app\" → đánh giá của các doanh nghiệp đã dùng (khách hàng) → (B)."}],"a":"E24-T08-41-43.mp3"},{"ns":[44,46],"script":[["M","Hi, Christina. Did you have a chance to look over the applications from our sales representatives who are interested in the new team leader role? We'll need to decide on a team leader soon.","Chào Christina. Chị đã có dịp xem qua đơn ứng tuyển của các nhân viên kinh doanh quan tâm đến vị trí trưởng nhóm mới chưa? Chúng ta cần sớm quyết định chọn trưởng nhóm."],["W","I did. I really liked Amanda Diop's application. She's the one who signed that deal with Wallerston Corporation.","Tôi xem rồi. Tôi rất thích đơn của Amanda Diop. Cô ấy chính là người đã ký được hợp đồng với Tập đoàn Wallerston."],["M","I agree. That was an impressive deal. Wallerston is one of our biggest clients now. I think Amanda would be a great choice.","Tôi đồng ý. Đó là một hợp đồng ấn tượng. Wallerston giờ là một trong những khách hàng lớn nhất của chúng ta. Tôi nghĩ Amanda sẽ là lựa chọn tuyệt vời."],["W","OK. I'm glad we're on the same page. I'll complete the paperwork and send it to the human resources department later today.","Được. Tôi mừng là chúng ta cùng quan điểm. Tôi sẽ hoàn tất giấy tờ và gửi cho phòng nhân sự trong hôm nay."]],"qs":[{"n":44,"q":"What are the speakers mainly discussing?","qvi":"Những người nói chủ yếu đang thảo luận về điều gì?","opts":["A presenter at an event","End-of-year bonuses","Vacation requests","An applicant for a new role"],"vi":["Một diễn giả tại sự kiện","Tiền thưởng cuối năm","Các đơn xin nghỉ phép","Một ứng viên cho vị trí mới"],"ans":"D","xp":"Người đàn ông hỏi: \"Did you have a chance to look over the applications from our sales representatives who are interested in the new team leader role?\" và người phụ nữ khen đơn của Amanda Diop → họ bàn về ứng viên cho vị trí trưởng nhóm mới → (D)."},{"n":45,"q":"According to the speakers, what has Amanda Diop accomplished?","qvi":"Theo những người nói, Amanda Diop đã đạt được thành tích gì?","opts":["She secured a business deal.","She completed a professional certification.","She won an industry award.","She reduced production costs."],"vi":["Cô ấy đã giành được một hợp đồng kinh doanh.","Cô ấy đã hoàn thành một chứng chỉ chuyên môn.","Cô ấy đã đoạt một giải thưởng trong ngành.","Cô ấy đã giảm chi phí sản xuất."],"ans":"A","xp":"Người phụ nữ nói: \"She's the one who signed that deal with Wallerston Corporation.\" → 'signed that deal' = 'secured a business deal' (giành được hợp đồng) → (A)."},{"n":46,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Submit some documents","Reserve a venue","Calculate a budget","Check some references"],"vi":["Nộp một số giấy tờ","Đặt một địa điểm","Tính toán ngân sách","Kiểm tra thư giới thiệu"],"ans":"A","xp":"Người phụ nữ nói: \"I'll complete the paperwork and send it to the human resources department later today.\" → gửi giấy tờ cho phòng nhân sự = nộp tài liệu → (A)."}],"a":"E24-T08-44-46.mp3"},{"ns":[47,49],"script":[["W1","Thanks for agreeing to this interview for our upcoming article in the Thomasville Gazette, Ms. Haddad.","Cảm ơn bà đã đồng ý trả lời phỏng vấn cho bài báo sắp tới của chúng tôi trên tờ Thomasville Gazette, bà Haddad."],["W2","Of course. As you know, the city council is proposing the implementation of a road tax. And I want to make sure the public is informed about it.","Không có gì. Như các bạn biết, hội đồng thành phố đang đề xuất áp dụng thuế đường bộ. Và tôi muốn chắc chắn rằng người dân được thông tin đầy đủ về việc này."],["M","Well, we like to keep our readers in the know, so we have a long list of questions for you.","Chúng tôi luôn muốn độc giả nắm được thông tin, nên chúng tôi có cả một danh sách dài câu hỏi dành cho bà."],["W1","I'll start. What does the city plan to do with this tax revenue, Ms. Haddad?","Tôi sẽ bắt đầu. Thành phố dự định làm gì với khoản thu thuế này, thưa bà Haddad?"],["W2","The money will be used to add bicycle lanes citywide, which I'm excited about. Bicycle lanes should reduce traffic and promote health.","Số tiền sẽ được dùng để làm thêm làn đường xe đạp trên toàn thành phố, điều mà tôi rất hào hứng. Làn xe đạp sẽ giúp giảm ùn tắc giao thông và tăng cường sức khỏe."],["M","Some business owners are concerned about losing street parking. Are you worried about that?","Một số chủ doanh nghiệp lo ngại sẽ mất chỗ đậu xe trên đường. Bà có lo về điều đó không?"]],"qs":[{"n":47,"q":"What is the topic of the conversation?","qvi":"Chủ đề của cuộc hội thoại là gì?","opts":["A hiring initiative","A tax proposal","A volunteer opportunity","A community festival"],"vi":["Một kế hoạch tuyển dụng","Một đề xuất về thuế","Một cơ hội tình nguyện","Một lễ hội cộng đồng"],"ans":"B","xp":"Bà Haddad nói: \"the city council is proposing the implementation of a road tax. And I want to make sure the public is informed about it.\" và cả cuộc phỏng vấn xoay quanh khoản thuế này → đề xuất thuế → (B)."},{"n":48,"q":"What is Ms. Haddad excited about?","qvi":"Bà Haddad hào hứng về điều gì?","opts":["Attracting international visitors","Increasing employment opportunities","Installing bicycle lanes","Improving a health-care facility"],"vi":["Thu hút du khách quốc tế","Tăng cơ hội việc làm","Lắp đặt làn đường xe đạp","Cải thiện một cơ sở y tế"],"ans":"C","xp":"Bà Haddad nói: \"The money will be used to add bicycle lanes citywide, which I'm excited about.\" → 'add bicycle lanes' = 'Installing bicycle lanes' → (C). (D) bẫy: có nhắc 'promote health' nhưng không nói về cơ sở y tế."},{"n":49,"q":"What concern does the man point out?","qvi":"Người đàn ông nêu ra mối lo ngại nào?","opts":["Some equipment is missing.","A project may be understaffed.","Some safety guidelines are unclear.","Some parking spaces may be lost."],"vi":["Một số thiết bị bị thiếu.","Một dự án có thể bị thiếu nhân sự.","Một số hướng dẫn an toàn không rõ ràng.","Một số chỗ đậu xe có thể bị mất."],"ans":"D","xp":"Người đàn ông nói: \"Some business owners are concerned about losing street parking.\" → 'losing street parking' = 'parking spaces may be lost' → (D)."}],"a":"E24-T08-47-49.mp3"},{"ns":[50,52],"script":[["M","Good morning, Ms. Gomez. I wanted to update you on the travel plans for your meeting with Scarney Department Store.","Chào buổi sáng, cô Gomez. Tôi muốn cập nhật cho cô về kế hoạch đi lại cho buổi gặp với Cửa hàng bách hóa Scarney."],["W","Thanks for taking care of that. They're prospective clients, and I've been so busy sending them samples and preparing my presentation that I haven't given a thought to my reservations.","Cảm ơn anh đã lo việc đó. Họ là khách hàng tiềm năng, và tôi bận gửi hàng mẫu cho họ và chuẩn bị bài thuyết trình đến mức chưa hề nghĩ đến việc đặt chỗ."],["M","Happy to help. I've confirmed your plane reservation. Just remember, Vela Air only allows one free piece of carry-on luggage. Otherwise, there'll be an extra charge.","Rất vui được giúp. Tôi đã xác nhận vé máy bay của cô. Chỉ cần nhớ là hãng Vela Air chỉ cho mang miễn phí một kiện hành lý xách tay. Nếu không sẽ bị tính thêm phí."],["W","OK. Can you forward the plane ticket confirmation, please?","Được rồi. Anh có thể chuyển tiếp xác nhận vé máy bay cho tôi được không?"],["M","I'll e-mail you right now.","Tôi sẽ gửi e-mail cho cô ngay bây giờ."]],"qs":[{"n":50,"q":"Who is the woman scheduled to meet with?","qvi":"Người phụ nữ có lịch gặp ai?","opts":["A company lawyer","A senior partner","A prospective employee","A potential customer"],"vi":["Luật sư của công ty","Một đối tác cấp cao","Một nhân viên tương lai","Một khách hàng tiềm năng"],"ans":"D","xp":"Người đàn ông nhắc đến \"your meeting with Scarney Department Store\", và người phụ nữ nói: \"They're prospective clients\" → 'prospective clients' = 'potential customer' → (D). (C) bẫy: 'prospective' đi với 'employee' chứ không phải 'clients'."},{"n":51,"q":"What does the man remind the woman about?","qvi":"Người đàn ông nhắc người phụ nữ về điều gì?","opts":["A luggage restriction","A required signature","An online guidebook","A refund policy"],"vi":["Một giới hạn về hành lý","Một chữ ký bắt buộc","Một cẩm nang trực tuyến","Một chính sách hoàn tiền"],"ans":"A","xp":"Người đàn ông nói: \"Just remember, Vela Air only allows one free piece of carry-on luggage.\" → chỉ được một kiện hành lý xách tay miễn phí = giới hạn hành lý → (A)."},{"n":52,"q":"What does the man agree to do?","qvi":"Người đàn ông đồng ý làm gì?","opts":["Look up a phone number","Arrange for a car rental","File an expense report","Forward an e-mail"],"vi":["Tra một số điện thoại","Sắp xếp thuê xe","Nộp báo cáo chi phí","Chuyển tiếp một e-mail"],"ans":"D","xp":"Người phụ nữ nhờ: \"Can you forward the plane ticket confirmation, please?\" – người đàn ông đáp: \"I'll e-mail you right now.\" → anh ấy đồng ý chuyển tiếp e-mail xác nhận → (D)."}],"a":"E24-T08-50-52.mp3"},{"ns":[53,55],"script":[["M","Hi. I'm Marcel from Novik Solutions. Glad you could stop by my trade show booth today.","Xin chào. Tôi là Marcel đến từ Novik Solutions. Rất vui vì hôm nay chị ghé gian hàng của tôi ở hội chợ thương mại."],["W","Nice to meet you. I'm Silvia from Media Futurescapes. So what type of product does your company provide?","Rất vui được gặp anh. Tôi là Silvia đến từ Media Futurescapes. Vậy công ty anh cung cấp loại sản phẩm nào?"],["M","We create accounting software so that companies can do their own accounting. Currently, I'm showcasing a new version for companies with under 50 employees.","Chúng tôi làm phần mềm kế toán để các công ty có thể tự làm kế toán. Hiện tôi đang giới thiệu một phiên bản mới dành cho các công ty có dưới 50 nhân viên."],["W","Well, we have about 200 employees.","À, công ty chúng tôi có khoảng 200 nhân viên."],["M","I understand. Here's a chart that provides an overview of our complete range of products.","Tôi hiểu. Đây là một biểu đồ giới thiệu tổng quan toàn bộ các dòng sản phẩm của chúng tôi."]],"qs":[{"n":53,"q":"Where are the speakers?","qvi":"Những người nói đang ở đâu?","opts":["At an electronics store","At a trade show","At a seminar","At an award ceremony"],"vi":["Ở cửa hàng điện tử","Ở hội chợ thương mại","Ở một hội thảo","Ở lễ trao giải"],"ans":"B","xp":"Người đàn ông nói: \"Glad you could stop by my trade show booth today.\" → họ đang ở hội chợ thương mại → (B)."},{"n":54,"q":"What does the woman mean when she says, \"we have about 200 employees\"?","qvi":"Người phụ nữ có ý gì khi nói \"chúng tôi có khoảng 200 nhân viên\"?","opts":["A product would not be useful for her company.","She is looking to hire a manager.","Her business has recently become successful.","Employees will need to be trained."],"vi":["Một sản phẩm sẽ không hữu ích cho công ty cô ấy.","Cô ấy đang muốn tuyển một quản lý.","Công việc kinh doanh của cô ấy gần đây đã thành công.","Nhân viên sẽ cần được đào tạo."],"ans":"A","xp":"Câu hỏi hàm ý. Người đàn ông nói đang giới thiệu phiên bản mới \"for companies with under 50 employees\" (cho công ty dưới 50 nhân viên). Cô ấy đáp công ty có khoảng 200 nhân viên → ngụ ý sản phẩm này không phù hợp với công ty cô → (A). Vì thế anh ấy đưa biểu đồ các sản phẩm khác."},{"n":55,"q":"What does the man give to the woman?","qvi":"Người đàn ông đưa cho người phụ nữ cái gì?","opts":["A regional map","A name tag","A résumé","A chart"],"vi":["Một bản đồ khu vực","Một thẻ tên","Một bản sơ yếu lý lịch","Một biểu đồ"],"ans":"D","xp":"Người đàn ông nói: \"Here's a chart that provides an overview of our complete range of products.\" → đưa biểu đồ → (D)."}],"a":"E24-T08-53-55.mp3"},{"ns":[56,58],"script":[["W","Rodrigo, aren't we scheduled to start the seal-coating job for the street parking around Bevelton Shopping Center next week?","Rodrigo, chẳng phải tuần sau chúng ta có lịch bắt đầu phủ lớp bảo vệ mặt đường cho khu đậu xe quanh Trung tâm mua sắm Bevelton sao?"],["M","We were going to start those repairs on Monday, but I've been looking at the weather; it's going to rain all weekend. I think we should reschedule.","Chúng ta định bắt đầu sửa chữa vào thứ Hai, nhưng tôi vừa xem thời tiết: trời sẽ mưa suốt cuối tuần. Tôi nghĩ chúng ta nên dời lịch."],["W","Right. We can't add a protective layer to the asphalt when it's wet. I'll contact the property manager at the shopping center to discuss alternative dates.","Đúng vậy. Chúng ta không thể phủ lớp bảo vệ lên nhựa đường khi nó còn ướt. Tôi sẽ liên hệ quản lý tòa nhà của trung tâm mua sắm để bàn ngày khác."],["M","OK. Just so you know, we've received a few new requests for consultations on our road repair services. I'll try to slot those in for Monday instead.","Được. Nói để chị biết, chúng ta vừa nhận được vài yêu cầu tư vấn mới về dịch vụ sửa đường. Tôi sẽ cố xếp những buổi đó vào thứ Hai thay thế."]],"qs":[{"n":56,"q":"Who most likely are the speakers?","qvi":"Những người nói nhiều khả năng là ai?","opts":["Plumbers","Commercial architects","Road repair contractors","Landscapers"],"vi":["Thợ sửa ống nước","Kiến trúc sư công trình thương mại","Nhà thầu sửa chữa đường","Người làm cảnh quan"],"ans":"C","xp":"Người phụ nữ nói: \"aren't we scheduled to start the seal-coating job for the street parking...\" và người đàn ông nhắc \"our road repair services\" → họ là nhà thầu sửa đường → (C)."},{"n":57,"q":"Why will a project be rescheduled?","qvi":"Tại sao một dự án sẽ bị dời lịch?","opts":["Rainy weather is expected.","A design requires revisions.","Some supplies have not arrived.","A crew member is not available."],"vi":["Dự báo trời sẽ mưa.","Một bản thiết kế cần chỉnh sửa.","Một số vật tư chưa đến.","Một thành viên trong đội không có mặt được."],"ans":"A","xp":"Người đàn ông nói: \"it's going to rain all weekend. I think we should reschedule.\" → 'going to rain' = 'Rainy weather is expected' → (A)."},{"n":58,"q":"What will the speakers most likely do on Monday?","qvi":"Những người nói nhiều khả năng sẽ làm gì vào thứ Hai?","opts":["Finalize a contract","Train some employees","Move some vehicles","Provide some consultations"],"vi":["Hoàn tất hợp đồng","Đào tạo nhân viên","Di chuyển một số xe","Thực hiện một số buổi tư vấn"],"ans":"D","xp":"Người đàn ông nói: \"we've received a few new requests for consultations... I'll try to slot those in for Monday instead.\" → thứ Hai họ sẽ tư vấn cho khách → (D)."}],"a":"E24-T08-56-58.mp3"},{"ns":[59,61],"script":[["M","Tasnim, I've been looking at the production process for soaps in our facility, and I think there's room for improvement.","Tasnim, tôi vừa xem xét quy trình sản xuất xà phòng ở cơ sở của chúng ta, và tôi nghĩ vẫn còn chỗ cần cải thiện."],["W","Improvements that could decrease our production time?","Những cải tiến có thể giảm thời gian sản xuất phải không?"],["M","Yes. Consider this: once the soap mixtures are poured into the molds, employees have to carry the batches across the room.","Đúng. Thử nghĩ xem: sau khi hỗn hợp xà phòng được đổ vào khuôn, nhân viên phải bê từng mẻ đi băng qua cả căn phòng."],["W","I see what you mean. If we reinstalled the drying racks closer to the mixing station, they wouldn't have to walk as far.","Tôi hiểu ý anh. Nếu chúng ta lắp lại giá phơi khô gần khu trộn hơn thì họ sẽ không phải đi xa như vậy."],["M","Exactly. A small change like that can have a big effect on total output.","Chính xác. Một thay đổi nhỏ như vậy có thể ảnh hưởng lớn đến tổng sản lượng."],["W","But wouldn't that be expensive?","Nhưng việc đó không tốn kém sao?"],["M","Let me show you the cost projection.","Để tôi cho chị xem bảng dự toán chi phí."]],"qs":[{"n":59,"q":"Where do the speakers most likely work?","qvi":"Những người nói nhiều khả năng làm việc ở đâu?","opts":["At a bookstore","At a dry cleaning business","At a bakery","At a factory"],"vi":["Ở hiệu sách","Ở tiệm giặt khô","Ở tiệm bánh","Ở nhà máy"],"ans":"D","xp":"Người đàn ông nói: \"I've been looking at the production process for soaps in our facility\" → họ làm ở nơi sản xuất xà phòng = nhà máy → (D)."},{"n":60,"q":"What does the man imply when he says, \"employees have to carry the batches across the room\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"nhân viên phải bê các mẻ hàng đi băng qua cả căn phòng\"?","opts":["A machine is malfunctioning.","A process is time-consuming.","Salaries should be increased.","More workers should be hired."],"vi":["Một chiếc máy đang bị trục trặc.","Một quy trình tốn nhiều thời gian.","Nên tăng lương.","Nên thuê thêm công nhân."],"ans":"B","xp":"Câu hỏi hàm ý. Người phụ nữ vừa hỏi về cải tiến để \"decrease our production time\" (giảm thời gian sản xuất); người đàn ông đáp 'Yes' rồi nêu ví dụ nhân viên phải bê hàng đi xa → ngụ ý khâu này mất nhiều thời gian → (B)."},{"n":61,"q":"What will the man show the woman?","qvi":"Người đàn ông sẽ cho người phụ nữ xem gì?","opts":["A cost estimate","A floor plan","A schedule","A catalog"],"vi":["Bảng ước tính chi phí","Sơ đồ mặt bằng","Lịch trình","Danh mục sản phẩm"],"ans":"A","xp":"Người đàn ông nói: \"Let me show you the cost projection.\" → 'cost projection' (dự toán chi phí) = 'cost estimate' → (A)."}],"a":"E24-T08-59-61.mp3"},{"ns":[62,64],"script":[["M","I was just looking at the supply request form you submitted for our engineering department.","Tôi vừa xem phiếu yêu cầu vật tư chị nộp cho phòng kỹ thuật của chúng ta."],["W","Yes?","Vâng?"],["M","I think you might've made a mistake. Do we really need that many computer mouses?","Tôi nghĩ có lẽ chị đã nhầm. Chúng ta có thật sự cần nhiều chuột máy tính đến vậy không?"],["W","Oh, that is a mistake! I meant to request two.","Ồ, đúng là nhầm rồi! Tôi định yêu cầu hai cái thôi."],["M","OK, great. I did think that was strange, given that there are only fifteen of us in our department!","Vậy thì tốt. Tôi cũng thấy lạ, vì phòng mình chỉ có mười lăm người!"],["W","Thanks for catching that. Do you know when the supplies will get here?","Cảm ơn anh đã phát hiện ra. Anh có biết khi nào vật tư sẽ đến không?"],["M","I'll place the order this afternoon, so they'll probably arrive next week.","Chiều nay tôi sẽ đặt hàng, nên có lẽ tuần sau hàng sẽ đến."]],"qs":[{"n":62,"q":"What department do the speakers work in?","qvi":"Những người nói làm việc ở phòng ban nào?","opts":["Legal","Engineering","Human Resources","Information Technology"],"vi":["Pháp chế","Kỹ thuật","Nhân sự","Công nghệ thông tin"],"ans":"B","xp":"Người đàn ông nói: \"the supply request form you submitted for our engineering department\" → họ làm ở phòng kỹ thuật → (B)."},{"n":63,"q":"Look at the graphic. Which quantity needs to be changed?","qvi":"Hãy nhìn bảng. Số lượng nào cần được thay đổi?","opts":["20","35","15","10"],"vi":["20","35","15","10"],"ans":"A","xp":"Người đàn ông hỏi: \"Do we really need that many computer mouses?\" và người phụ nữ thừa nhận nhầm, chỉ định yêu cầu 2 cái. Trong bảng, Computer mouse có số lượng 20 → cần sửa con số 20 → (A). (C) 15 là số người trong phòng, không phải số cần sửa."},{"n":64,"q":"What does the woman ask about?","qvi":"Người phụ nữ hỏi về điều gì?","opts":["A refund","A signature","A meeting location","A delivery date"],"vi":["Việc hoàn tiền","Chữ ký","Địa điểm họp","Ngày giao hàng"],"ans":"D","xp":"Người phụ nữ hỏi: \"Do you know when the supplies will get here?\" (khi nào vật tư đến) = hỏi ngày giao hàng → (D)."}],"a":"E24-T08-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","Welcome to Halcyon Florals. How can I help you?","Chào mừng đến với Halcyon Florals. Tôi có thể giúp gì cho anh?"],["M","Hi. I'm planning the Lambert-Evans wedding that's taking place this weekend. I received an e-mail this morning that there's a problem with the flowers I ordered for the floral arrangements.","Chào chị. Tôi đang lên kế hoạch cho đám cưới nhà Lambert-Evans diễn ra vào cuối tuần này. Sáng nay tôi nhận được e-mail báo rằng có vấn đề với số hoa tôi đặt để cắm."],["W","Yes, unfortunately, my supplier notified me that they're out of stock because of a shortage. I'm sorry, but you'll have to choose a replacement for the lilies.","Vâng, tiếc là nhà cung cấp báo với tôi rằng họ hết hàng do thiếu nguồn cung. Tôi xin lỗi, nhưng anh sẽ phải chọn loại hoa khác thay cho hoa ly."],["M","I know my client likes orchids, but I'm guessing those are too expensive. We'll still need a flower that's under five dollars per stem.","Tôi biết khách hàng của tôi thích hoa lan, nhưng tôi đoán loại đó quá đắt. Chúng tôi vẫn cần loại hoa dưới năm đô la một cành."],["W","Well, what about these? They fit within your budget.","Vậy loại này thì sao? Chúng nằm trong ngân sách của anh."],["M","Those will be perfect.","Loại đó thì tuyệt quá."]],"qs":[{"n":65,"q":"What type of event are the speakers discussing?","qvi":"Những người nói đang bàn về loại sự kiện nào?","opts":["A retirement party","A wedding","A garden show","A grand opening"],"vi":["Tiệc nghỉ hưu","Đám cưới","Triển lãm vườn","Lễ khai trương"],"ans":"B","xp":"Người đàn ông nói: \"I'm planning the Lambert-Evans wedding that's taking place this weekend.\" → đám cưới → (B)."},{"n":66,"q":"According to the woman, what has caused a problem?","qvi":"Theo người phụ nữ, điều gì đã gây ra vấn đề?","opts":["An invoice error","A rainstorm","A supply shortage","A reservation cancellation"],"vi":["Lỗi hóa đơn","Một trận mưa bão","Sự thiếu hụt nguồn cung","Việc hủy đặt chỗ"],"ans":"C","xp":"Người phụ nữ nói: \"my supplier notified me that they're out of stock because of a shortage.\" → hết hàng do thiếu nguồn cung → (C)."},{"n":67,"q":"Look at the graphic. Which flowers will be used in the arrangements?","qvi":"Hãy nhìn bảng. Loại hoa nào sẽ được dùng để cắm?","opts":["Lilies","Tulips","Roses","Orchids"],"vi":["Hoa ly","Hoa tulip","Hoa hồng","Hoa lan"],"ans":"B","xp":"Hoa ly đã hết hàng nên phải chọn loại thay thế, và người đàn ông nói: \"We'll still need a flower that's under five dollars per stem.\" Trong bảng, ngoài hoa ly ($4.50) chỉ có Tulips ($4.75) dưới 5 đô → dùng hoa tulip → (B)."}],"a":"E24-T08-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["W","I think I've inspected enough to determine a fair market value for your store.","Tôi nghĩ tôi đã kiểm tra đủ để xác định giá trị thị trường hợp lý cho cửa hàng của anh."],["M","OK. You have the paperwork verifying that I replaced my roof last year, right? Buyers look for properties that don't need major repairs.","Được. Chị có giấy tờ xác nhận tôi đã thay mái nhà năm ngoái rồi đúng không? Người mua thường tìm những bất động sản không cần sửa chữa lớn."],["W","I do have that. And you're right—recent repairs are a factor that add to the value of a property.","Tôi có giấy đó. Và anh nói đúng – việc mới sửa chữa gần đây là một yếu tố làm tăng giá trị bất động sản."],["M","The historic windows will be a selling point, I think. They're made of handblown glass. All the storefronts in this row of shops have them.","Tôi nghĩ những ô cửa sổ cổ sẽ là điểm thu hút người mua. Chúng được làm bằng kính thổi thủ công. Tất cả mặt tiền của dãy cửa hàng này đều có loại cửa đó."],["W","They do add character. Now, I need to walk around with my camera to take some photos to file with my paperwork.","Chúng đúng là tạo nét đặc trưng. Bây giờ tôi cần mang máy ảnh đi một vòng để chụp vài tấm ảnh lưu kèm hồ sơ."]],"qs":[{"n":68,"q":"What is the man most likely planning to do?","qvi":"Người đàn ông nhiều khả năng đang dự định làm gì?","opts":["Sell a shop","Expand warehouse space","Replace a sign","Install air-conditioning"],"vi":["Bán một cửa hàng","Mở rộng không gian nhà kho","Thay biển hiệu","Lắp máy điều hòa"],"ans":"A","xp":"Người phụ nữ định giá \"a fair market value for your store\", người đàn ông nói \"Buyers look for properties that don't need major repairs\" và cửa sổ cổ sẽ là \"a selling point\" → anh ấy định bán cửa hàng → (A)."},{"n":69,"q":"Look at the graphic. Which part of the storefront does the man say is historic?","qvi":"Hãy nhìn hình. Người đàn ông nói phần nào của mặt tiền cửa hàng là cổ (có giá trị lịch sử)?","opts":["Part 1","Part 2","Part 3","Part 4"],"vi":["Phần 1","Phần 2","Phần 3","Phần 4"],"ans":"D","xp":"Người đàn ông nói: \"The historic windows will be a selling point\" → phần cổ là cửa sổ. Trong hình, cửa sổ kính ô vuông được đánh số 4 → (D). (1) là đèn, (2) là biển hiệu, (3) là cửa ra vào."},{"n":70,"q":"What will the woman do next?","qvi":"Người phụ nữ sẽ làm gì tiếp theo?","opts":["Recommend a paint color","Inspect some lighting","Measure a wall","Take some photographs"],"vi":["Gợi ý màu sơn","Kiểm tra hệ thống đèn","Đo một bức tường","Chụp vài tấm ảnh"],"ans":"D","xp":"Người phụ nữ nói: \"I need to walk around with my camera to take some photos to file with my paperwork.\" → chụp ảnh → (D)."}],"a":"E24-T08-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Are you furnishing a small apartment? Go to Jillsbedstore.com and check out Jill's Cabinet Bed.","Bạn đang sắm đồ nội thất cho một căn hộ nhỏ? Hãy truy cập Jillsbedstore.com và xem ngay Giường tủ Jill's Cabinet Bed."],["","This unique bed fits into a hardwood cabinet, becoming compact and saving you space. When you need to use it, just open the cabinet and unfold it to set it up.","Chiếc giường độc đáo này gập gọn vào một chiếc tủ gỗ cứng, trở nên nhỏ gọn và giúp bạn tiết kiệm không gian. Khi cần dùng, bạn chỉ việc mở tủ và mở giường ra là xong."],["","And this month only, we're offering listeners a special deal: if you use the code 623Z to order on our Web site, we'll throw in two free pillows with your purchase.","Và chỉ riêng trong tháng này, chúng tôi dành cho quý thính giả một ưu đãi đặc biệt: nếu bạn dùng mã 623Z khi đặt hàng trên trang web của chúng tôi, chúng tôi sẽ tặng kèm hai chiếc gối miễn phí."],["","So visit Jillsbedstore.com to start enjoying a more spacious apartment!","Vậy hãy truy cập Jillsbedstore.com để bắt đầu tận hưởng một căn hộ rộng rãi hơn!"]],"qs":[{"n":71,"q":"What product is being advertised?","qvi":"Sản phẩm nào đang được quảng cáo?","opts":["A desk","A bed","A bookcase","A chair"],"vi":["Bàn làm việc","Giường","Tủ sách","Ghế"],"ans":"B","xp":"Người nói: \"check out Jill's Cabinet Bed. This unique bed fits into a hardwood cabinet...\" → sản phẩm là một chiếc giường → (B). (C) bẫy: có nhắc 'cabinet' (tủ) nhưng đó là phần chứa giường."},{"n":72,"q":"What advantage of the product does the speaker mention?","qvi":"Người nói đề cập đến ưu điểm nào của sản phẩm?","opts":["It helps save space.","It is guaranteed to last.","It comes in multiple sizes.","It is environmentally friendly."],"vi":["Nó giúp tiết kiệm không gian.","Nó được bảo đảm dùng bền lâu.","Nó có nhiều kích cỡ.","Nó thân thiện với môi trường."],"ans":"A","xp":"Người nói: \"This unique bed fits into a hardwood cabinet, becoming compact and saving you space.\" → tiết kiệm không gian → (A)."},{"n":73,"q":"How can the listeners receive a gift?","qvi":"Thính giả có thể nhận quà bằng cách nào?","opts":["By filling out a survey","By going into a store","By entering a code on a Web site","By subscribing to a newsletter"],"vi":["Bằng cách điền khảo sát","Bằng cách đến cửa hàng","Bằng cách nhập mã trên trang web","Bằng cách đăng ký nhận bản tin"],"ans":"C","xp":"Người nói: \"if you use the code 623Z to order on our Web site, we'll throw in two free pillows\" → dùng mã khi đặt hàng trên web sẽ được tặng gối (quà) → (C)."}],"a":"E24-T08-71-73.mp3"},{"ns":[74,76],"script":[["","For the rest of today, it is expected to remain dry and cloudy in the Jonesdale area. But beginning tomorrow, we'll see colder temperatures and moderate snowfall.","Trong thời gian còn lại của hôm nay, khu vực Jonesdale được dự báo sẽ tiếp tục khô ráo và nhiều mây. Nhưng bắt đầu từ ngày mai, nhiệt độ sẽ lạnh hơn và có tuyết rơi vừa."],["","So please remember to put on a heavy coat if you plan on doing anything outdoors. As we head into next week, it'll finally start to feel like spring.","Vì vậy, nếu bạn định làm gì đó ngoài trời, hãy nhớ mặc áo khoác dày. Sang tuần sau, thời tiết cuối cùng sẽ bắt đầu có cảm giác của mùa xuân."],["","OK, next up, we'll be covering our local sports teams' recent events, including a big victory last night.","Được rồi, tiếp theo chúng tôi sẽ đưa tin về các sự kiện gần đây của các đội thể thao địa phương, trong đó có một chiến thắng lớn tối qua."]],"qs":[{"n":74,"q":"What is the broadcast mainly about?","qvi":"Bản tin chủ yếu nói về điều gì?","opts":["The weather","Traffic updates","An outdoor festival","A city cleanup initiative"],"vi":["Thời tiết","Cập nhật giao thông","Một lễ hội ngoài trời","Một kế hoạch làm sạch thành phố"],"ans":"A","xp":"Người nói: \"it is expected to remain dry and cloudy... we'll see colder temperatures and moderate snowfall.\" → bản tin nói về thời tiết → (A)."},{"n":75,"q":"What does the speaker recommend?","qvi":"Người nói khuyên điều gì?","opts":["Filling out a form","Wearing appropriate clothing","Checking a map","Using public transportation"],"vi":["Điền vào một mẫu đơn","Mặc trang phục phù hợp","Xem bản đồ","Sử dụng phương tiện công cộng"],"ans":"B","xp":"Người nói: \"please remember to put on a heavy coat if you plan on doing anything outdoors.\" → 'put on a heavy coat' = mặc trang phục phù hợp → (B)."},{"n":76,"q":"What will the listeners hear next?","qvi":"Thính giả sẽ nghe gì tiếp theo?","opts":["An interview","An advertisement","Some sports updates","Some newly released songs"],"vi":["Một cuộc phỏng vấn","Một quảng cáo","Tin tức thể thao","Một số bài hát mới phát hành"],"ans":"C","xp":"Người nói: \"next up, we'll be covering our local sports teams' recent events\" → tiếp theo là tin thể thao → (C)."}],"a":"E24-T08-74-76.mp3"},{"ns":[77,79],"script":[["","This is Brilliant Watch Repair calling about the antique wristwatch that you dropped off yesterday.","Đây là tiệm sửa đồng hồ Brilliant Watch Repair gọi về chiếc đồng hồ đeo tay cổ mà quý khách gửi hôm qua."],["","As you mentioned, one of the watch hands was frequently skipping ahead, so we replaced the battery. That seemed to fix the issue.","Như quý khách đã nói, một trong các kim đồng hồ thường xuyên bị nhảy tới trước, nên chúng tôi đã thay pin. Có vẻ như việc đó đã khắc phục được sự cố."],["","However, because the watch is quite old, we also took it apart to give it a good cleaning. In the future, we suggest bringing it in for basic maintenance once every three years to keep it in good condition.","Tuy nhiên, vì chiếc đồng hồ khá cũ nên chúng tôi cũng tháo ra để vệ sinh kỹ. Sau này, chúng tôi khuyên quý khách mang đồng hồ đến bảo dưỡng cơ bản ba năm một lần để giữ nó ở tình trạng tốt."],["","The watch is ready for you at any time. Just be aware that tomorrow is a national holiday and we'll be closed. Thanks!","Đồng hồ đã sẵn sàng, quý khách có thể đến lấy bất cứ lúc nào. Chỉ lưu ý rằng ngày mai là ngày lễ quốc gia và chúng tôi sẽ đóng cửa. Xin cảm ơn!"]],"qs":[{"n":77,"q":"Why is the speaker calling?","qvi":"Tại sao người nói gọi điện?","opts":["To provide a cost estimate","To confirm some warranty information","To report that a service has been completed","To recommend that another business be contacted"],"vi":["Để báo giá ước tính","Để xác nhận thông tin bảo hành","Để báo rằng một dịch vụ đã hoàn tất","Để khuyên liên hệ một doanh nghiệp khác"],"ans":"C","xp":"Tiệm gọi về chiếc đồng hồ khách gửi: \"we replaced the battery. That seemed to fix the issue.\" và \"The watch is ready for you at any time.\" → báo rằng việc sửa chữa đã xong → (C)."},{"n":78,"q":"What does the speaker suggest the listener do?","qvi":"Người nói gợi ý người nghe làm gì?","opts":["Schedule regular maintenance","Wait for a sale price","Call the manufacturer","Ask for a second opinion"],"vi":["Lên lịch bảo dưỡng định kỳ","Đợi giá khuyến mãi","Gọi cho nhà sản xuất","Hỏi thêm ý kiến của người khác"],"ans":"A","xp":"Người nói: \"we suggest bringing it in for basic maintenance once every three years\" → bảo dưỡng ba năm một lần = bảo dưỡng định kỳ (regular maintenance) → (A)."},{"n":79,"q":"Why will a business be closed tomorrow?","qvi":"Tại sao ngày mai cửa hàng sẽ đóng cửa?","opts":["Some renovations will be done.","The owner will be on vacation.","An inspection will be conducted.","It will be a national holiday."],"vi":["Sẽ có việc sửa sang cửa hàng.","Chủ tiệm sẽ đi nghỉ.","Sẽ có một đợt kiểm tra.","Đó là ngày lễ quốc gia."],"ans":"D","xp":"Người nói: \"Just be aware that tomorrow is a national holiday and we'll be closed.\" → (D)."}],"a":"E24-T08-77-79.mp3"},{"ns":[80,82],"script":[["","We're here tonight to celebrate Fritz Schneider's outstanding service to the company on the eve of his retirement.","Tối nay chúng ta có mặt ở đây để tôn vinh những cống hiến xuất sắc của Fritz Schneider cho công ty, nhân dịp ông sắp nghỉ hưu."],["","Fritz has been with Elta Footwear since its inception, and without him, we wouldn't be where we are today. With unfailing optimism, he has provided consistent leadership to help us grow as a company.","Fritz đã gắn bó với Elta Footwear ngay từ khi công ty mới thành lập, và nếu không có ông, chúng ta đã không có được vị thế như ngày hôm nay. Với sự lạc quan không bao giờ phai, ông đã lãnh đạo một cách nhất quán để giúp công ty phát triển."],["","Thanks largely to his efforts, today we produce more than 25 lines of athletic footwear. We'll miss him, but we wish him well!","Phần lớn nhờ những nỗ lực của ông mà ngày nay chúng ta sản xuất hơn 25 dòng giày thể thao. Chúng ta sẽ nhớ ông, nhưng xin chúc ông mọi điều tốt đẹp!"],["","And now, I'd like to share a short video with some highlights of Fritz's many years with Elta.","Và bây giờ, tôi xin chiếu một đoạn video ngắn với những khoảnh khắc nổi bật trong nhiều năm Fritz gắn bó với Elta."]],"qs":[{"n":80,"q":"What is the purpose of the speech?","qvi":"Mục đích của bài phát biểu là gì?","opts":["To present an award","To announce a job promotion","To introduce a new product","To celebrate a retirement"],"vi":["Để trao giải thưởng","Để thông báo thăng chức","Để giới thiệu sản phẩm mới","Để chúc mừng sự nghỉ hưu"],"ans":"D","xp":"Người nói: \"We're here tonight to celebrate Fritz Schneider's outstanding service to the company on the eve of his retirement.\" → mục đích là tôn vinh, chúc mừng việc nghỉ hưu → (D)."},{"n":81,"q":"What does the company produce?","qvi":"Công ty sản xuất gì?","opts":["Cookware","Shoes","Cameras","Light fixtures"],"vi":["Dụng cụ nấu ăn","Giày","Máy ảnh","Thiết bị chiếu sáng"],"ans":"B","xp":"Người nói: \"today we produce more than 25 lines of athletic footwear.\" (tên công ty cũng là Elta Footwear) → 'athletic footwear' = giày → (B)."},{"n":82,"q":"What will the listeners most likely do next?","qvi":"Người nghe nhiều khả năng sẽ làm gì tiếp theo?","opts":["Watch a video","Ask questions","Eat a meal","Take a group photograph"],"vi":["Xem một đoạn video","Đặt câu hỏi","Dùng bữa","Chụp ảnh tập thể"],"ans":"A","xp":"Cuối bài người nói: \"I'd like to share a short video with some highlights of Fritz's many years with Elta.\" → mọi người sẽ xem video → (A)."}],"a":"E24-T08-80-82.mp3"},{"ns":[83,85],"script":[["","This is Yuliya, the building manager. I'm calling to let you know that workers are coming tomorrow morning to replace a defective water pipe under the pavement in front of your apartment.","Tôi là Yuliya, quản lý tòa nhà. Tôi gọi để báo với anh/chị rằng sáng mai công nhân sẽ đến thay một đường ống nước bị hỏng nằm dưới vỉa hè trước căn hộ của anh/chị."],["","It should only take a few hours to complete, but I know you sometimes work from home, and they'll be using loud machinery.","Việc này chỉ mất vài tiếng là xong, nhưng tôi biết anh/chị thỉnh thoảng làm việc tại nhà, và họ sẽ dùng máy móc gây ồn lớn."],["","Sorry this is such short notice—part of the pipe runs next to a telephone pole, so I was required to apply for a permit to have the work done safely. I thought approval would take at least a week, but it was issued yesterday.","Xin lỗi vì báo gấp như vậy – một phần đường ống chạy cạnh cột điện thoại, nên tôi phải xin giấy phép để công việc được thực hiện an toàn. Tôi tưởng phải mất ít nhất một tuần mới được duyệt, nhưng giấy phép đã được cấp ngay hôm qua."]],"qs":[{"n":83,"q":"What does the speaker say will happen tomorrow?","qvi":"Người nói cho biết điều gì sẽ xảy ra vào ngày mai?","opts":["A roof will be repaired.","A pipe will be replaced.","A payment will be processed.","An application will be submitted."],"vi":["Mái nhà sẽ được sửa.","Một đường ống sẽ được thay.","Một khoản thanh toán sẽ được xử lý.","Một đơn đăng ký sẽ được nộp."],"ans":"B","xp":"Người nói: \"workers are coming tomorrow morning to replace a defective water pipe\" → ngày mai sẽ thay ống nước → (B)."},{"n":84,"q":"Why does the speaker say, \"they'll be using loud machinery\"?","qvi":"Tại sao người nói nói \"họ sẽ dùng máy móc gây ồn lớn\"?","opts":["To reject a proposal","To explain a delay","To provide a warning","To make a complaint"],"vi":["Để từ chối một đề xuất","Để giải thích sự chậm trễ","Để đưa ra lời cảnh báo","Để phàn nàn"],"ans":"C","xp":"Câu hỏi hàm ý. Ngay trước đó người nói nói: \"I know you sometimes work from home\" → nhắc rằng máy móc sẽ rất ồn để người nghe chuẩn bị trước (vì có thể ảnh hưởng việc làm tại nhà) → mục đích là cảnh báo → (C)."},{"n":85,"q":"What does the speaker say about a permit?","qvi":"Người nói nói gì về giấy phép?","opts":["It has been mailed to the listener.","It has been denied.","It cost a lot of money.","It was granted sooner than expected."],"vi":["Nó đã được gửi qua bưu điện cho người nghe.","Nó đã bị từ chối.","Nó tốn rất nhiều tiền.","Nó được cấp sớm hơn dự kiến."],"ans":"D","xp":"Người nói: \"I thought approval would take at least a week, but it was issued yesterday.\" → giấy phép được cấp sớm hơn dự kiến → (D)."}],"a":"E24-T08-83-85.mp3"},{"ns":[86,88],"script":[["","I called this quick meeting for hospital staff. Our wireless Internet has gone down, and we are in the process of getting it restored.","Tôi triệu tập cuộc họp nhanh này dành cho nhân viên bệnh viện. Mạng Internet không dây của chúng ta đã bị sập, và chúng tôi đang trong quá trình khôi phục."],["","But don't worry—hardwired access is still available, so all doctors, nurses, and essential staff will still be able to use the desktop computers at each workstation.","Nhưng đừng lo – kết nối có dây vẫn hoạt động, nên tất cả bác sĩ, y tá và nhân viên thiết yếu vẫn có thể sử dụng máy tính để bàn ở từng vị trí làm việc."],["","However, our patients will be wondering why they can't connect to the Wi-Fi. So please remember to let them know what's going on.","Tuy nhiên, bệnh nhân sẽ thắc mắc tại sao họ không kết nối được Wi-Fi. Vì vậy, hãy nhớ cho họ biết chuyện gì đang xảy ra."]],"qs":[{"n":86,"q":"Where is the meeting taking place?","qvi":"Cuộc họp đang diễn ra ở đâu?","opts":["At an office building","At a museum","At a hospital","At a hotel"],"vi":["Ở một tòa nhà văn phòng","Ở bảo tàng","Ở bệnh viện","Ở khách sạn"],"ans":"C","xp":"Người nói: \"I called this quick meeting for hospital staff.\" và nhắc đến bác sĩ, y tá, bệnh nhân → ở bệnh viện → (C)."},{"n":87,"q":"What problem does the speaker mention?","qvi":"Người nói đề cập đến vấn đề gì?","opts":["A door to a room is locked.","There is a staff shortage.","A delivery has been delayed.","Wireless Internet is not available."],"vi":["Cửa một căn phòng bị khóa.","Thiếu nhân viên.","Một đơn hàng bị giao trễ.","Không dùng được Internet không dây."],"ans":"D","xp":"Người nói: \"Our wireless Internet has gone down\" (mạng không dây bị sập) = 'Wireless Internet is not available' → (D)."},{"n":88,"q":"What does the speaker remind the listeners to do?","qvi":"Người nói nhắc người nghe làm gì?","opts":["Submit their time sheets","Limit their mobile phone usage","Share some information","Use an alternate product"],"vi":["Nộp bảng chấm công","Hạn chế dùng điện thoại di động","Chia sẻ một số thông tin","Dùng một sản phẩm thay thế"],"ans":"C","xp":"Người nói: \"please remember to let them know what's going on.\" (cho bệnh nhân biết chuyện gì đang xảy ra) → chia sẻ thông tin → (C)."}],"a":"E24-T08-86-88.mp3"},{"ns":[89,91],"script":[["","As a consulting nutritionist, I'll work with your company cafeteria to review the items that are currently sold and suggest updates.","Với vai trò chuyên gia dinh dưỡng tư vấn, tôi sẽ làm việc với căng tin công ty các bạn để xem xét các món đang bán và đề xuất thay đổi."],["","Consuming less meat is not only better for our health but is also better for the environment. And consider this interesting fact: a recent study of thousands of cafeteria meals shows that when additional vegetarian options are offered, there is a significant increase in the number of vegetarian meals consumed.","Ăn ít thịt hơn không chỉ tốt cho sức khỏe mà còn tốt cho môi trường. Và hãy xem xét sự thật thú vị này: một nghiên cứu gần đây trên hàng nghìn bữa ăn ở căng tin cho thấy khi có thêm các lựa chọn món chay, số suất ăn chay được tiêu thụ tăng lên đáng kể."],["","Some of you have expressed concern that I might ask you to completely overhaul the entire menu. Well, small changes can have surprising results!","Một số bạn đã bày tỏ lo ngại rằng tôi có thể yêu cầu thay đổi toàn bộ thực đơn. Ồ, những thay đổi nhỏ cũng có thể mang lại kết quả bất ngờ đấy!"]],"qs":[{"n":89,"q":"What is the speaker mainly discussing?","qvi":"Người nói chủ yếu đang bàn về điều gì?","opts":["Updating a menu","Organizing a health fair","Planting a vegetable garden","Reviewing some survey results"],"vi":["Cập nhật thực đơn","Tổ chức hội chợ sức khỏe","Trồng vườn rau","Xem xét kết quả khảo sát"],"ans":"A","xp":"Người nói: \"I'll work with your company cafeteria to review the items that are currently sold and suggest updates.\" và cả bài nói về thêm món chay vào thực đơn → cập nhật thực đơn → (A)."},{"n":90,"q":"Why does the speaker mention a recent study?","qvi":"Tại sao người nói nhắc đến một nghiên cứu gần đây?","opts":["To support her opinion","To suggest a process","To request a guest speaker","To publicize an event"],"vi":["Để củng cố quan điểm của mình","Để đề xuất một quy trình","Để mời một diễn giả khách mời","Để quảng bá một sự kiện"],"ans":"A","xp":"Người nói cho rằng nên ăn ít thịt, rồi dẫn: \"a recent study... shows that when additional vegetarian options are offered, there is a significant increase in the number of vegetarian meals consumed.\" → dẫn nghiên cứu để làm bằng chứng ủng hộ ý kiến thêm món chay → (A)."},{"n":91,"q":"Why does the speaker say, \"small changes can have surprising results\"?","qvi":"Tại sao người nói nói \"những thay đổi nhỏ có thể mang lại kết quả bất ngờ\"?","opts":["To agree with a decision","To reassure the listeners","To congratulate the listeners","To request some assistance"],"vi":["Để đồng ý với một quyết định","Để trấn an người nghe","Để chúc mừng người nghe","Để nhờ giúp đỡ"],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó: \"Some of you have expressed concern that I might ask you to completely overhaul the entire menu.\" (lo phải thay đổi toàn bộ thực đơn) → người nói đáp rằng thay đổi nhỏ cũng hiệu quả, tức là không cần thay đổi lớn → trấn an người nghe → (B)."}],"a":"E24-T08-89-91.mp3"},{"ns":[92,94],"script":[["","We've received feedback from one of our major clients. The most recent advertisements we created for social media increased traffic to our client's Web site by 20 percent, which is great.","Chúng ta vừa nhận được phản hồi từ một trong những khách hàng lớn. Những quảng cáo gần đây nhất mà chúng ta làm cho mạng xã hội đã giúp tăng 20% lượng truy cập vào trang web của khách hàng, thật tuyệt vời."],["","In other news, we're on track to exceed our annual goal in terms of revenue. Having said that, 40 percent of our business comes from two clients. And either could back out at any time.","Một tin khác, chúng ta đang trên đà vượt mục tiêu doanh thu của năm. Dù vậy, 40% công việc kinh doanh của chúng ta đến từ hai khách hàng. Và bất kỳ ai trong số họ cũng có thể rút lui bất cứ lúc nào."],["","We plan to ask existing clients to recommend our ad services to their business contacts. As an incentive, we'll offer a discount to those whose referrals result in new business for us.","Chúng ta dự định nhờ các khách hàng hiện tại giới thiệu dịch vụ quảng cáo của mình cho các đối tác làm ăn của họ. Để khuyến khích, chúng ta sẽ giảm giá cho những ai giới thiệu mang lại hợp đồng mới cho chúng ta."]],"qs":[{"n":92,"q":"What type of service does the speaker's company provide?","qvi":"Công ty của người nói cung cấp loại dịch vụ nào?","opts":["Travel planning","Online advertising","Staff recruitment","Inventory management"],"vi":["Lập kế hoạch du lịch","Quảng cáo trực tuyến","Tuyển dụng nhân sự","Quản lý hàng tồn kho"],"ans":"B","xp":"Người nói: \"The most recent advertisements we created for social media increased traffic to our client's Web site\" và nhắc \"our ad services\" → quảng cáo trên mạng xã hội = quảng cáo trực tuyến → (B)."},{"n":93,"q":"What does the speaker mean when he says, \"40 percent of our business comes from two clients\"?","qvi":"Người nói có ý gì khi nói \"40% công việc kinh doanh của chúng ta đến từ hai khách hàng\"?","opts":["His team should be rewarded.","He has time to develop more projects.","The clients are major corporations.","The company needs more clients."],"vi":["Nhóm của anh ấy nên được khen thưởng.","Anh ấy có thời gian để phát triển thêm dự án.","Các khách hàng đó là những tập đoàn lớn.","Công ty cần thêm khách hàng."],"ans":"D","xp":"Câu hỏi hàm ý. Phụ thuộc quá nhiều vào hai khách hàng là rủi ro (\"either could back out at any time\"), nên ngay sau đó anh ấy nói kế hoạch nhờ khách hàng giới thiệu thêm khách mới → ngụ ý công ty cần thêm khách hàng → (D)."},{"n":94,"q":"What incentive does the company plan to offer?","qvi":"Công ty dự định đưa ra ưu đãi khuyến khích nào?","opts":["A discount for referrals","A subscription to an online magazine","A satisfaction guarantee","A certification course"],"vi":["Giảm giá cho việc giới thiệu khách","Gói đăng ký tạp chí trực tuyến","Cam kết hài lòng","Khóa học lấy chứng chỉ"],"ans":"A","xp":"Người nói: \"As an incentive, we'll offer a discount to those whose referrals result in new business for us.\" → giảm giá cho người giới thiệu khách → (A)."}],"a":"E24-T08-92-94.mp3"},{"ns":[95,97],"script":[["","Welcome to the annual Chesterfield Community Festival. I have a few quick announcements.","Chào mừng quý vị đến với Lễ hội Cộng đồng Chesterfield thường niên. Tôi có vài thông báo nhanh."],["","First, thank you to all of our vendors. They were selected because they use sustainable, environmentally friendly practices to produce their goods. We know protecting the environment is important to our community.","Trước tiên, xin cảm ơn tất cả các gian hàng của chúng ta. Họ được chọn vì sử dụng các phương thức bền vững, thân thiện với môi trường để sản xuất hàng hóa. Chúng tôi biết bảo vệ môi trường là điều quan trọng với cộng đồng mình."],["","Second, there are still a few tickets available for tonight's jazz concert. You can stop by Marta's Treats next to Wei Family Farms to buy a ticket.","Thứ hai, vẫn còn vài vé cho buổi hòa nhạc jazz tối nay. Quý vị có thể ghé gian hàng Marta's Treats bên cạnh Wei Family Farms để mua vé."],["","Finally, remember that we are no longer handing out paper programs. You can download the event program from our Web site at www.chesterfieldcommunityfestival.com.","Cuối cùng, xin lưu ý chúng tôi không còn phát chương trình in giấy nữa. Quý vị có thể tải chương trình sự kiện từ trang web của chúng tôi tại www.chesterfieldcommunityfestival.com."]],"qs":[{"n":95,"q":"What does the speaker say about the vendors?","qvi":"Người nói nói gì về các gian hàng (người bán)?","opts":["They use sustainable practices.","They are offering free samples.","Their goods are homemade.","Their prices are reasonable."],"vi":["Họ sử dụng các phương thức bền vững.","Họ đang phát hàng mẫu miễn phí.","Hàng hóa của họ là đồ tự làm.","Giá của họ hợp lý."],"ans":"A","xp":"Người nói: \"They were selected because they use sustainable, environmentally friendly practices to produce their goods.\" → (A)."},{"n":96,"q":"Look at the graphic. Where can the listeners purchase concert tickets?","qvi":"Hãy nhìn sơ đồ. Người nghe có thể mua vé hòa nhạc ở đâu?","opts":["At location 1","At location 2","At location 3","At location 4"],"vi":["Ở vị trí 1","Ở vị trí 2","Ở vị trí 3","Ở vị trí 4"],"ans":"C","xp":"Người nói: \"You can stop by Marta's Treats next to Wei Family Farms to buy a ticket.\" Trên sơ đồ, Marta's Treats nằm ở vị trí số 3 (cạnh Wei Family Farms ở số 4) → (C)."},{"n":97,"q":"According to the speaker, what can be found on the festival Web site?","qvi":"Theo người nói, có thể tìm thấy gì trên trang web của lễ hội?","opts":["A job listing","An event program","Safety regulations","Names of sponsors"],"vi":["Danh sách việc làm","Chương trình sự kiện","Quy định an toàn","Tên các nhà tài trợ"],"ans":"B","xp":"Người nói: \"You can download the event program from our Web site\" → chương trình sự kiện → (B)."}],"a":"E24-T08-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","I hope you enjoyed the conference's keynote speaker, Ms. Olabisi Adewale. What a phenomenal speech.","Tôi hy vọng quý vị đã thích phần trình bày của diễn giả chính hội nghị, bà Olabisi Adewale. Thật là một bài phát biểu tuyệt vời."],["","If you're interested in more of what she has to say about running a business, her latest book is for sale in the lobby. It's definitely an engaging read!","Nếu quý vị muốn tìm hiểu thêm những chia sẻ của bà về việc điều hành doanh nghiệp, cuốn sách mới nhất của bà đang được bán ở sảnh. Chắc chắn đó là một cuốn sách rất cuốn hút!"],["","The rest of the conference is ahead of you now. We're excited that this year because of popular demand and all the feedback we received, we've added an additional day to the conference offerings.","Phần còn lại của hội nghị đang chờ quý vị. Chúng tôi rất vui vì năm nay, do nhu cầu lớn và tất cả những phản hồi nhận được, chúng tôi đã thêm một ngày nữa vào chương trình hội nghị."],["","And before you head off to your sessions, I wanted to announce a change of location for the twelve-thirty session today. It's been moved, and the schedule board has been updated.","Và trước khi quý vị đến các phiên của mình, tôi muốn thông báo thay đổi địa điểm của phiên lúc mười hai giờ ba mươi hôm nay. Phiên này đã được chuyển chỗ, và bảng lịch trình đã được cập nhật."]],"qs":[{"n":98,"q":"What does the speaker encourage the listeners to do?","qvi":"Người nói khuyến khích người nghe làm gì?","opts":["Pick up refreshments","Purchase a book","Exchange contact details","Volunteer for an activity"],"vi":["Lấy đồ ăn nhẹ","Mua một cuốn sách","Trao đổi thông tin liên lạc","Tình nguyện tham gia một hoạt động"],"ans":"B","xp":"Người nói: \"If you're interested in more of what she has to say about running a business, her latest book is for sale in the lobby.\" → khuyến khích mua sách → (B)."},{"n":99,"q":"What does the speaker say happened as a result of attendee feedback?","qvi":"Người nói cho biết điều gì đã xảy ra nhờ phản hồi của người tham dự?","opts":["Registration was conducted online.","A more diverse range of speakers were invited.","Extra charging stations were provided.","Another conference day was added."],"vi":["Việc đăng ký được thực hiện trực tuyến.","Nhiều diễn giả đa dạng hơn được mời.","Có thêm các trạm sạc điện.","Hội nghị được thêm một ngày."],"ans":"D","xp":"Người nói: \"because of popular demand and all the feedback we received, we've added an additional day to the conference offerings.\" → thêm một ngày hội nghị → (D)."},{"n":100,"q":"Look at the graphic. Which session's location has changed?","qvi":"Hãy nhìn bảng. Phiên nào đã thay đổi địa điểm?","opts":["Remote Workforces","Team Collaboration","Innovation Tools","Problem-Solving"],"vi":["Lực lượng làm việc từ xa","Hợp tác nhóm","Công cụ đổi mới","Giải quyết vấn đề"],"ans":"C","xp":"Người nói: \"I wanted to announce a change of location for the twelve-thirty session today.\" Trong bảng, phiên bắt đầu lúc 12:30 là Innovation Tools (12:30–1:30) → (C)."}],"a":"E24-T08-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"The order is estimated to arrive ------- November 15.","opts":["by","until","at","down"],"ans":"A","xp":"Giới từ chỉ thời gian: 'arrive' là hành động xảy ra một lần → dùng 'by + mốc thời gian' = trước/chậm nhất là ngày 15/11. (B) until = cho đến khi (dùng với hành động kéo dài như 'stay, wait'), (C) at dùng với giờ (at 5 P.M.), (D) down = xuống.\nDịch: Đơn hàng dự kiến sẽ đến chậm nhất là ngày 15 tháng 11."},{"n":102,"q":"Please make sure that ------- personal belongings are safely stored out of sight.","opts":["you","yourself","yours","your"],"ans":"D","xp":"Đại từ: sau chỗ trống là cụm danh từ 'personal belongings' → cần tính từ sở hữu 'your' (của bạn). (A) you là đại từ chủ ngữ/tân ngữ, (B) yourself là đại từ phản thân, (C) yours là đại từ sở hữu (đứng một mình, không đi kèm danh từ).\nDịch: Vui lòng đảm bảo rằng đồ dùng cá nhân của bạn được cất giữ an toàn, khuất tầm nhìn."},{"n":103,"q":"Be sure to fold all the clothes ------- before placing them in bags for customers.","opts":["neatly","deeply","highly","surely"],"ans":"A","xp":"Từ vựng (trạng từ): bổ nghĩa cho 'fold the clothes' (gấp quần áo). (A) neatly = gọn gàng, ngay ngắn → hợp nghĩa. (B) deeply = sâu sắc, (C) highly = rất, cao, (D) surely = chắc chắn.\nDịch: Hãy nhớ gấp gọn gàng tất cả quần áo trước khi cho vào túi cho khách hàng."},{"n":104,"q":"Visitors should not take ------- while touring the restricted areas of the facility.","opts":["photographic","photographing","photographs","photographed"],"ans":"C","xp":"Từ loại: sau động từ 'take' cần danh từ làm tân ngữ; cụm cố định 'take photographs' = chụp ảnh. (C) photographs là danh từ số nhiều → chọn (C). (A) photographic là tính từ, (B) photographing là V-ing, (D) photographed là V-ed.\nDịch: Khách tham quan không được chụp ảnh khi đi tham quan các khu vực hạn chế của cơ sở."},{"n":105,"q":"The new novel by mystery writer Meredith Delgado will be ------- in bookstores nationwide on July 9.","opts":["regular","available","convenient","completed"],"ans":"B","xp":"Từ vựng (tính từ): 'be available in bookstores' = có bán ở các hiệu sách. (A) regular = thường xuyên, đều đặn, (C) convenient = tiện lợi, (D) completed = được hoàn thành – không hợp với 'in bookstores'.\nDịch: Cuốn tiểu thuyết mới của nhà văn trinh thám Meredith Delgado sẽ có bán tại các hiệu sách trên toàn quốc vào ngày 9 tháng 7."},{"n":106,"q":"Cashiers should call for an ------- cashier when more than three customers are in line.","opts":["addition","additions","additional","additionally"],"ans":"C","xp":"Từ loại: giữa mạo từ 'an' và danh từ 'cashier' cần tính từ. (C) additional = thêm, bổ sung → chọn (C). (A) addition và (B) additions là danh từ, (D) additionally là trạng từ.\nDịch: Nhân viên thu ngân nên gọi thêm một thu ngân khác khi có hơn ba khách hàng đang xếp hàng."},{"n":107,"q":"Nga Ho, currently the sales manager for the southern division, will take on a new ------- within the Trang Media Group in February.","opts":["view","access","role","session"],"ans":"C","xp":"Từ vựng (danh từ): 'take on a new role' = đảm nhận một vai trò/vị trí mới – hợp với ngữ cảnh người đang là trưởng phòng kinh doanh. (A) view = quan điểm, tầm nhìn, (B) access = quyền truy cập, (D) session = phiên, buổi.\nDịch: Nga Ho, hiện là trưởng phòng kinh doanh khu vực phía nam, sẽ đảm nhận một vai trò mới trong Tập đoàn Trang Media vào tháng Hai."},{"n":108,"q":"To prevent the sauce from scorching while being heated, stir it ------- with a wooden spoon.","opts":["continues","continue","continuously","continuous"],"ans":"C","xp":"Từ loại: câu đã đủ 'stir it' (động từ + tân ngữ) → chỗ trống cần trạng từ bổ nghĩa cho động từ 'stir'. (C) continuously = liên tục → chọn (C). (A)(B) là động từ, (D) continuous là tính từ.\nDịch: Để tránh nước sốt bị cháy khi đun nóng, hãy khuấy liên tục bằng thìa gỗ."},{"n":109,"q":"Naito Travel Agency is ------- experienced guides to lead tours in Japan.","opts":["seeking","spreading","working","focusing"],"ans":"A","xp":"Từ vựng (động từ): cần động từ đi trực tiếp với tân ngữ 'experienced guides'. (A) seeking = tìm kiếm (seek + người/vật) → 'đang tìm hướng dẫn viên có kinh nghiệm'. (B) spreading = lan truyền, (C) working = làm việc (nội động từ, không có tân ngữ trực tiếp), (D) focusing = tập trung (cần 'on').\nDịch: Công ty du lịch Naito đang tìm kiếm các hướng dẫn viên có kinh nghiệm để dẫn tour tại Nhật Bản."},{"n":110,"q":"------- a mineral-rich spring was discovered nearby, Hotel Denzali became a popular tourist destination.","opts":["That","After","How","Every"],"ans":"B","xp":"Liên từ: câu có hai mệnh đề ('a mineral-rich spring was discovered nearby' và 'Hotel Denzali became...') → cần liên từ nối. (B) After = sau khi → hợp nghĩa (phát hiện suối trước, nổi tiếng sau). (A) That và (C) How mở đầu mệnh đề danh từ, không nối được như vậy; (D) Every là từ hạn định.\nDịch: Sau khi một suối nước giàu khoáng chất được phát hiện gần đó, Khách sạn Denzali đã trở thành điểm du lịch nổi tiếng."},{"n":111,"q":"To save time, download your tickets to your mobile phone ------- arriving at the venue.","opts":["since","before","although","without"],"ans":"B","xp":"Giới từ/liên từ + V-ing: theo nghĩa, phải tải vé về điện thoại trước khi đến địa điểm để tiết kiệm thời gian. (B) before = trước khi → chọn (B). (A) since = kể từ khi/vì, (C) although = mặc dù (thường đi với mệnh đề), (D) without = mà không.\nDịch: Để tiết kiệm thời gian, hãy tải vé về điện thoại di động của bạn trước khi đến địa điểm tổ chức."},{"n":112,"q":"Several companies have already ------- bids to paint logos on our delivery trucks.","opts":["submit","submission","submitted","submitting"],"ans":"C","xp":"Thì động từ: 'have already + V3/V-ed' là thì hiện tại hoàn thành → (C) submitted = đã nộp. (A) submit là động từ nguyên mẫu, (B) submission là danh từ, (D) submitting là V-ing.\nDịch: Một số công ty đã nộp hồ sơ dự thầu để sơn logo lên các xe tải giao hàng của chúng tôi."},{"n":113,"q":"The jewel-toned fabrics featured in Norfolk Fashion's spring collection gave the ------- a luxurious look.","opts":["marks","portions","types","garments"],"ans":"D","xp":"Từ vựng (danh từ): vải (fabrics) trong bộ sưu tập thời trang mang lại vẻ sang trọng cho quần áo. (D) garments = quần áo, trang phục → chọn (D). (A) marks = dấu, vết, (B) portions = phần, khẩu phần, (C) types = loại.\nDịch: Những loại vải màu đá quý trong bộ sưu tập mùa xuân của Norfolk Fashion đã mang lại cho các bộ trang phục vẻ ngoài sang trọng."},{"n":114,"q":"Please do not share your resident access code with ------- living in communities other than Arbor Hill Apartments.","opts":["anyone","either","most","each"],"ans":"A","xp":"Đại từ bất định: sau giới từ 'with' cần một đại từ làm tân ngữ, được bổ nghĩa bởi 'living in...' (= who lives in...). (A) anyone = bất kỳ ai → chọn (A). (B) either = một trong hai, (C) most = hầu hết (thường 'most of'), (D) each = mỗi (thường 'each of') – không hợp.\nDịch: Vui lòng không chia sẻ mã ra vào dành cho cư dân của bạn với bất kỳ ai sống ở khu dân cư khác ngoài Arbor Hill Apartments."},{"n":115,"q":"The social media specialist should always be looking for ways to make people more ------- of the Zintaman brand.","opts":["concise","aware","precious","defined"],"ans":"B","xp":"Từ vựng (tính từ): cấu trúc 'make + người + adj'; cụm cố định 'be aware of' = biết đến, nhận thức về → 'aware of the brand' (biết đến thương hiệu). (A) concise = ngắn gọn, (C) precious = quý giá, (D) defined = được xác định rõ – không đi với 'of' theo nghĩa này.\nDịch: Chuyên viên mạng xã hội nên luôn tìm cách giúp mọi người biết đến thương hiệu Zintaman nhiều hơn."},{"n":116,"q":"All Tayton residents ------- their unwanted appliances at the public works facility for a small fee.","opts":["can discard","have been discarded","to be discarding","discarding"],"ans":"A","xp":"Động từ chính + dạng chủ động/bị động: câu thiếu động từ chính, chủ ngữ 'residents' tự vứt bỏ và có tân ngữ 'their unwanted appliances' → cần dạng chủ động. (A) can discard = có thể vứt bỏ → chọn (A). (B) là bị động (sai vì có tân ngữ), (C) to-V và (D) V-ing không làm động từ chính.\nDịch: Tất cả cư dân Tayton có thể bỏ các thiết bị gia dụng không dùng nữa tại cơ sở công trình công cộng với một khoản phí nhỏ."},{"n":117,"q":"Following numerous requests from customers, Manilla Lunchbox has ------- added vegetarian options to its menu.","opts":["extremely","typically","finally","closely"],"ans":"C","xp":"Từ vựng (trạng từ): sau nhiều yêu cầu của khách, cuối cùng nhà hàng đã thêm món chay → (C) finally = cuối cùng. (A) extremely = cực kỳ (bổ nghĩa cho tính từ), (B) typically = thường thì (không hợp với hành động đã xảy ra một lần), (D) closely = chặt chẽ, sát sao.\nDịch: Sau nhiều yêu cầu từ khách hàng, Manilla Lunchbox cuối cùng đã thêm các món chay vào thực đơn."},{"n":118,"q":"Crutchfield Heating and Cooling installs gas, oil, and electric furnaces from the industry's ------- manufacturers.","opts":["leading","leader","leads","leadership"],"ans":"A","xp":"Từ loại: giữa sở hữu cách 'the industry's' và danh từ 'manufacturers' cần tính từ. (A) leading = hàng đầu → 'các nhà sản xuất hàng đầu'. (B) leader và (D) leadership là danh từ, (C) leads là động từ/danh từ số nhiều.\nDịch: Crutchfield Heating and Cooling lắp đặt lò sưởi dùng gas, dầu và điện của các nhà sản xuất hàng đầu trong ngành."},{"n":119,"q":"To reduce stress and ------- productivity, Sciallo Corp. offers free lunchtime fitness classes to its employees.","opts":["distribute","boost","sweat","tone"],"ans":"B","xp":"Từ vựng (động từ): song song với 'reduce stress' (giảm căng thẳng), cần động từ đi với 'productivity'. (B) boost = tăng cường, thúc đẩy → 'tăng năng suất'. (A) distribute = phân phát, (C) sweat = đổ mồ hôi, (D) tone = làm săn chắc (cơ bắp).\nDịch: Để giảm căng thẳng và tăng năng suất, Tập đoàn Sciallo cung cấp các lớp thể dục miễn phí vào giờ nghỉ trưa cho nhân viên."},{"n":120,"q":"Yoshimi Fashion customers ------- a secure online shopping experience.","opts":["are guaranteed","to guarantee","guaranteeing","having guaranteed"],"ans":"A","xp":"Động từ chính + bị động: câu thiếu động từ chính → loại (B) to-V, (C) V-ing, (D) having V3. Khách hàng được (công ty) đảm bảo một trải nghiệm an toàn → bị động 'are guaranteed' (guarantee sb sth → sb is guaranteed sth).\nDịch: Khách hàng của Yoshimi Fashion được đảm bảo một trải nghiệm mua sắm trực tuyến an toàn."},{"n":121,"q":"Using last year's record profits, Mr. Shakar was able to invest ------- a new grocery delivery service.","opts":["about","near","in","of"],"ans":"C","xp":"Giới từ đi với động từ: 'invest in something' = đầu tư vào cái gì → chọn (C) in. (A) about = về, (B) near = gần, (D) of = của – không đi với 'invest'.\nDịch: Nhờ lợi nhuận kỷ lục năm ngoái, ông Shakar đã có thể đầu tư vào một dịch vụ giao hàng tạp hóa mới."},{"n":122,"q":"Central Oregon Power must renew the ------- at least 30 days before the current one expires.","opts":["contractor","contract","contracting","contracted"],"ans":"B","xp":"Từ loại + nghĩa: sau 'the' cần danh từ làm tân ngữ của 'renew'; thứ được gia hạn và 'expires' (hết hạn) là hợp đồng. (B) contract = hợp đồng → chọn (B). (A) contractor = nhà thầu (là người, không 'gia hạn' được), (C) contracting là V-ing, (D) contracted là V-ed.\nDịch: Công ty Điện lực Central Oregon phải gia hạn hợp đồng ít nhất 30 ngày trước khi hợp đồng hiện tại hết hạn."},{"n":123,"q":"Please park on the west side of the building ------- parking spaces closer to the entrance can be used by customers.","opts":["instead of","so that","resulting from","as if"],"ans":"B","xp":"Liên từ: sau chỗ trống là một mệnh đề đầy đủ ('parking spaces ... can be used ...') → cần liên từ. Nghĩa: đỗ xe phía tây để chỗ gần lối vào dành cho khách → chỉ mục đích: (B) so that = để mà. (A) instead of và (C) resulting from là giới từ (đi với danh từ), (D) as if = như thể – sai nghĩa.\nDịch: Vui lòng đỗ xe ở phía tây tòa nhà để khách hàng có thể sử dụng những chỗ đỗ xe gần lối vào hơn."},{"n":124,"q":"The report was authored ------- by Chae-Won Sohn in the research department and by Ray Hahn, the head of marketing.","opts":["joint","joints","jointed","jointly"],"ans":"D","xp":"Từ loại: câu bị động đã đủ 'was authored by...' → cần trạng từ bổ nghĩa cho động từ 'authored'. (D) jointly = cùng nhau, chung → chọn (D). (A) joint là tính từ/danh từ, (B) joints là danh từ số nhiều, (C) jointed là tính từ 'có khớp nối'.\nDịch: Bản báo cáo được đồng biên soạn bởi Chae-Won Sohn ở phòng nghiên cứu và Ray Hahn, trưởng phòng tiếp thị."},{"n":125,"q":"The Teason Resort offers ------- activities for children and adults throughout the day.","opts":["capable","dense","absent","numerous"],"ans":"D","xp":"Từ vựng (tính từ): bổ nghĩa cho danh từ số nhiều 'activities'. (D) numerous = nhiều, đông đảo → 'nhiều hoạt động'. (A) capable = có khả năng, (B) dense = dày đặc, (C) absent = vắng mặt.\nDịch: Khu nghỉ dưỡng Teason cung cấp nhiều hoạt động cho trẻ em và người lớn suốt cả ngày."},{"n":126,"q":"Because the museum receives generous donations, it ------- raises the price of admission tickets.","opts":["nearly","likely","generally","rarely"],"ans":"D","xp":"Từ vựng (trạng từ): vì bảo tàng nhận được nhiều tiền quyên góp nên hiếm khi phải tăng giá vé → (D) rarely = hiếm khi. (A) nearly = gần như, (B) likely = có lẽ (thường 'is likely to'), (C) generally = nói chung, thường – mâu thuẫn với lý do 'nhận nhiều quyên góp'.\nDịch: Vì bảo tàng nhận được những khoản quyên góp hào phóng nên hiếm khi tăng giá vé vào cửa."},{"n":127,"q":"Global Data LLC will promote Hae-In Ahn to Chief Financial Officer ------- June 1.","opts":["effective","effecting","effected","effect"],"ans":"A","xp":"Cụm cố định: 'effective + ngày' = có hiệu lực từ ngày... → chọn (A) effective. (B) effecting, (C) effected là dạng của động từ 'effect' (gây ra), (D) effect là danh từ 'ảnh hưởng/hiệu quả'.\nDịch: Công ty Global Data LLC sẽ thăng chức Hae-In Ahn lên Giám đốc Tài chính, có hiệu lực từ ngày 1 tháng 6."},{"n":128,"q":"The upcoming focus group will be an online meeting during ------- each participant can join via a videoconferencing program.","opts":["through","there","which","who"],"ans":"C","xp":"Đại từ quan hệ: sau giới từ 'during' và thay cho danh từ chỉ vật 'an online meeting' → dùng 'which' (during which = trong cuộc họp đó). (D) who chỉ người, (B) there là trạng từ, (A) through là giới từ – không đứng sau giới từ 'during'.\nDịch: Buổi thảo luận nhóm sắp tới sẽ là một cuộc họp trực tuyến, trong đó mỗi người tham gia có thể kết nối qua một chương trình hội nghị truyền hình."},{"n":129,"q":"Patricia Park developed a proprietary ------- for Sprayeze, an all-organic cleaning compound.","opts":["menu","formula","article","decision"],"ans":"B","xp":"Từ vựng (danh từ): Sprayeze là một hợp chất tẩy rửa → thứ được phát triển là công thức. (B) formula = công thức (pha chế) → 'proprietary formula' = công thức độc quyền. (A) menu = thực đơn, (C) article = bài báo, (D) decision = quyết định.\nDịch: Patricia Park đã phát triển một công thức độc quyền cho Sprayeze, một hợp chất tẩy rửa hoàn toàn hữu cơ."},{"n":130,"q":"Rayel Pharmaceutical provides a list of its ------- and their affiliations on its Web site.","opts":["research","researching","researched","researchers"],"ans":"D","xp":"Từ loại + nghĩa: sau 'its' cần danh từ; 'their affiliations' (nơi công tác/tổ chức liên kết của họ) cho thấy danh từ chỉ người số nhiều. (D) researchers = các nhà nghiên cứu → chọn (D). (A) research là danh từ chỉ việc nghiên cứu (không có 'affiliations'), (B) researching là V-ing, (C) researched là V-ed.\nDịch: Công ty Dược phẩm Rayel cung cấp danh sách các nhà nghiên cứu của mình và tổ chức mà họ liên kết trên trang web."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> mnandy@gmantcs.com</p><p><b>From:</b> jblaire@blaireaccounting.ca</p><p><b>Re:</b> AUTOMATIC REPLY</p><p><b>Date:</b> 9 January, 10:34 AM</p></div><p>Hello, and thank you for contacting Blaire Accounting. I will be out of the office until 31 January. I will respond to your message when I <span class=\"blank\" data-n=\"131\">-------</span>. If you need <span class=\"blank\" data-n=\"132\">-------</span> assistance, please contact Susan Lewis, my administrative assistant, at slewis@blaireaccounting.ca. You can <span class=\"blank\" data-n=\"133\">-------</span> call her directly at 416-555-0193. <span class=\"blank\" data-n=\"134\">-------</span>.</p><p>Jean Blaire, President</p>","vi":"Đến: mnandy@gmantcs.com\nTừ: jblaire@blaireaccounting.ca\nV/v: TRẢ LỜI TỰ ĐỘNG\nNgày: 9 tháng 1, 10:34 sáng\n\nXin chào, và cảm ơn bạn đã liên hệ với Công ty Kế toán Blaire. Tôi sẽ vắng mặt tại văn phòng cho đến ngày 31 tháng 1. Tôi sẽ trả lời tin nhắn của bạn khi tôi quay lại. Nếu bạn cần hỗ trợ ngay, vui lòng liên hệ Susan Lewis, trợ lý hành chính của tôi, theo địa chỉ slewis@blaireaccounting.ca. Bạn cũng có thể gọi trực tiếp cho cô ấy theo số 416-555-0193. Cô Lewis làm việc tại văn phòng vào các ngày trong tuần từ 9 giờ sáng đến 5 giờ chiều.\n\nJean Blaire, Chủ tịch","qs":[{"n":131,"opts":["recover","return","begin","finish"],"ans":"B","xp":"Từ vựng (động từ): câu trước nói 'I will be out of the office until 31 January' (tôi vắng mặt đến 31/1) → tôi sẽ trả lời khi tôi quay lại: (B) return = trở về. (A) recover = hồi phục, (C) begin = bắt đầu, (D) finish = kết thúc – không hợp nghĩa.\nDịch: Tôi sẽ trả lời tin nhắn của bạn khi tôi quay lại."},{"n":132,"opts":["immediate","immediately","immediacy","immediacies"],"ans":"A","xp":"Từ loại: trước danh từ 'assistance' cần tính từ. (A) immediate = ngay lập tức → 'immediate assistance' = sự hỗ trợ ngay. (B) immediately là trạng từ, (C)(D) là danh từ.\nDịch: Nếu bạn cần hỗ trợ ngay, vui lòng liên hệ Susan Lewis, trợ lý hành chính của tôi."},{"n":133,"opts":["also","lightly","similarly","again"],"ans":"A","xp":"Từ vựng (trạng từ): câu trước đưa ra cách liên hệ bằng e-mail; câu này đưa thêm một cách nữa là gọi điện → (A) also = cũng, ngoài ra. (B) lightly = nhẹ nhàng, (C) similarly = tương tự, (D) again = lại lần nữa (chưa gọi lần nào nên không dùng 'again').\nDịch: Bạn cũng có thể gọi trực tiếp cho cô ấy theo số 416-555-0193."},{"n":134,"opts":["Ms. Blaire will be back in the office earlier than expected.","Please come and see us if you ever find yourself in Toronto.","It is essential to hire a competent payroll and tax accountant.","Ms. Lewis is in the office on weekdays from 9 A.M. to 5 P.M."],"ans":"D","xp":"Điền câu: câu trước nói có thể gọi trực tiếp cho cô Lewis → câu tiếp theo hợp lý là cho biết giờ cô ấy có mặt để nghe máy: (D) 'Cô Lewis làm việc tại văn phòng vào các ngày trong tuần từ 9 giờ sáng đến 5 giờ chiều.' (A) mâu thuẫn với thư trả lời tự động đã nói vắng mặt đến 31/1 (và người viết chính là Jean Blaire, không xưng ngôi thứ ba). (B) mời ghé thăm Toronto – lạc đề. (C) nói về việc thuê kế toán – không liên quan.\n(A) Bà Blaire sẽ quay lại văn phòng sớm hơn dự kiến.\n(B) Hãy đến thăm chúng tôi nếu bạn có dịp đến Toronto.\n(C) Việc thuê một kế toán viên lương và thuế giỏi là rất cần thiết.\n(D) Cô Lewis làm việc tại văn phòng vào các ngày trong tuần từ 9 giờ sáng đến 5 giờ chiều."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following notice.","passage":"<p><b>Attention customers of Metro Coffee:</b></p><p>We are excited to announce that we <span class=\"blank\" data-n=\"135\">-------</span> a second Metro Coffee store! As you know, we recently expanded our offerings to include baked goods as well as coffee. As a result, our <span class=\"blank\" data-n=\"136\">-------</span> has increased significantly. To keep up with demand, we decided that a second store was necessary. <span class=\"blank\" data-n=\"137\">-------</span>. Our new space is substantially <span class=\"blank\" data-n=\"138\">-------</span> but offers the same wide selection of items. Make sure to stop by and check out our new location today!</p>","vi":"Kính gửi quý khách hàng của Metro Coffee:\n\nChúng tôi rất vui mừng thông báo rằng chúng tôi đã khai trương cửa hàng Metro Coffee thứ hai! Như quý khách đã biết, gần đây chúng tôi đã mở rộng các sản phẩm của mình, bao gồm cả bánh nướng bên cạnh cà phê. Nhờ đó, lượng khách kinh doanh của chúng tôi đã tăng lên đáng kể. Để đáp ứng nhu cầu, chúng tôi quyết định cần có cửa hàng thứ hai. Cửa hàng này nằm cách đây hai dặm, trong khu phố cổ. Không gian mới của chúng tôi rộng hơn đáng kể nhưng vẫn cung cấp cùng nhiều lựa chọn sản phẩm phong phú như trước. Hãy nhớ ghé qua và tham quan địa điểm mới của chúng tôi ngay hôm nay!","qs":[{"n":135,"opts":["will open","can open","are opening","have opened"],"ans":"D","xp":"Thì động từ: câu cuối của thông báo nói 'stop by and check out our new location today!' (hãy ghé qua địa điểm mới ngay hôm nay) → cửa hàng thứ hai đã mở rồi → dùng hiện tại hoàn thành (D) have opened = đã khai trương. (A) will open và (C) are opening chỉ tương lai (chưa mở, không thể ghé 'today'), (B) can open = có thể mở – sai nghĩa.\nDịch: Chúng tôi rất vui mừng thông báo rằng chúng tôi đã khai trương cửa hàng Metro Coffee thứ hai!"},{"n":136,"opts":["debt","payroll","business","investment"],"ans":"C","xp":"Từ vựng (danh từ): vì có thêm bánh nướng nên việc kinh doanh (lượng khách) tăng mạnh; câu sau 'To keep up with demand' (để đáp ứng nhu cầu) xác nhận điều này → (C) business = việc kinh doanh. (A) debt = nợ, (B) payroll = bảng lương, (D) investment = khoản đầu tư – không giải thích được việc cần mở thêm cửa hàng để đáp ứng nhu cầu.\nDịch: Nhờ đó, việc kinh doanh của chúng tôi đã tăng lên đáng kể."},{"n":137,"opts":["Metro Coffee has been a part of the community for nine years.","We roast our coffee beans right here on-site.","Many people enjoy eating a pastry while drinking a cup of coffee.","It is located two miles away in the historic district."],"ans":"D","xp":"Điền câu: câu trước nói cần có cửa hàng thứ hai; câu sau nói 'Our new space is...' (không gian mới) → câu ở giữa hợp lý nhất là giới thiệu vị trí của cửa hàng mới: (D) 'It is located two miles away in the historic district.' – 'It' chính là 'a second store'. (A) nói về lịch sử cửa hàng, (B) nói về rang cà phê, (C) là nhận xét chung – đều không nối được với 'Our new space'.\n(A) Metro Coffee đã gắn bó với cộng đồng được chín năm.\n(B) Chúng tôi rang hạt cà phê ngay tại chỗ.\n(C) Nhiều người thích ăn bánh ngọt khi uống một tách cà phê.\n(D) Cửa hàng nằm cách đây hai dặm, trong khu phố cổ."},{"n":138,"opts":["large","larger","largely","largest"],"ans":"B","xp":"So sánh hơn: trạng từ 'substantially' (đáng kể) thường đứng trước tính từ so sánh hơn để nhấn mạnh (substantially/much/far + adj-er); ở đây so sánh cửa hàng mới với cửa hàng cũ → (B) larger = rộng hơn. (A) large là dạng nguyên, (C) largely là trạng từ, (D) largest là so sánh nhất (cần 'the').\nDịch: Không gian mới của chúng tôi rộng hơn đáng kể nhưng vẫn cung cấp cùng nhiều lựa chọn sản phẩm phong phú."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following memo.","passage":"<div class=\"hdr\"><p><b>To:</b> All Ferrese Hotel Employees</p><p><b>From:</b> Sergio Prieto, Hotel Manager</p><p><b>Date:</b> Monday, July 4</p><p><b>Subject:</b> Global Shipping Partners Conference</p></div><p>The Ferrese Hotel will be hosting the Global Shipping Partners Conference next week, from Tuesday to Sunday. <span class=\"blank\" data-n=\"139\">-------</span>, management expects to see many more customers in the hotel's restaurants and gift shops. <span class=\"blank\" data-n=\"140\">-------</span>. I will be hiring temporary staff to ensure that <span class=\"blank\" data-n=\"141\">-------</span> can meet these increased demands. Please take the time to help them learn our <span class=\"blank\" data-n=\"142\">-------</span> when they are here. Doing so will ensure that all operations run smoothly while the conference is taking place.</p>","vi":"Gửi: Toàn thể nhân viên Khách sạn Ferrese\nTừ: Sergio Prieto, Quản lý khách sạn\nNgày: Thứ Hai, 4 tháng 7\nChủ đề: Hội nghị Đối tác Vận tải Toàn cầu\n\nKhách sạn Ferrese sẽ tổ chức Hội nghị Đối tác Vận tải Toàn cầu vào tuần tới, từ thứ Ba đến Chủ nhật. Vì vậy, ban quản lý dự kiến sẽ có nhiều khách hơn tại các nhà hàng và cửa hàng quà tặng của khách sạn. Trung tâm dịch vụ doanh nhân cũng sẽ đông hơn bình thường. Tôi sẽ tuyển nhân viên thời vụ để đảm bảo rằng chúng ta có thể đáp ứng những nhu cầu tăng thêm này. Xin hãy dành thời gian giúp họ làm quen với các quy trình công việc thường ngày của chúng ta khi họ ở đây. Làm như vậy sẽ đảm bảo mọi hoạt động diễn ra suôn sẻ trong thời gian hội nghị.","qs":[{"n":139,"opts":["If not","After all","Therefore","In the meantime"],"ans":"C","xp":"Trạng từ liên kết: câu trước nói khách sạn sẽ tổ chức hội nghị; câu sau nói ban quản lý dự kiến nhiều khách hơn ở nhà hàng, cửa hàng → quan hệ nguyên nhân – kết quả: (C) Therefore = vì vậy. (A) If not = nếu không, (B) After all = rốt cuộc/dù sao thì, (D) In the meantime = trong lúc đó – không thể hiện quan hệ kết quả.\nDịch: Vì vậy, ban quản lý dự kiến sẽ có nhiều khách hơn tại các nhà hàng và cửa hàng quà tặng của khách sạn."},{"n":140,"opts":["Restaurant renovations are almost completed.","Conference registration forms have been posted online.","Applications will be reviewed later this week.","The business center will also be busier than usual."],"ans":"D","xp":"Điền câu: câu trước liệt kê nơi sẽ đông khách (nhà hàng, cửa hàng quà tặng); câu sau nói 'these increased demands' (những nhu cầu tăng thêm này) → câu ở giữa nên bổ sung thêm một nơi bận rộn: (D) 'The business center will also be busier than usual.' – từ 'also' nối tiếp ý câu trước. (A) sửa nhà hàng, (B) mẫu đăng ký hội nghị, (C) xét hồ sơ ứng tuyển – không khớp với 'increased demands'.\n(A) Việc cải tạo nhà hàng sắp hoàn tất.\n(B) Mẫu đăng ký hội nghị đã được đăng trực tuyến.\n(C) Hồ sơ ứng tuyển sẽ được xem xét vào cuối tuần này.\n(D) Trung tâm dịch vụ doanh nhân cũng sẽ đông hơn bình thường."},{"n":141,"opts":["it","we","both","something"],"ans":"B","xp":"Đại từ: chỗ trống là chủ ngữ của 'can meet these increased demands'; người viết (quản lý) nói với toàn bộ nhân viên → 'we' = chúng ta (khách sạn) đáp ứng nhu cầu. (A) it và (D) something chỉ vật, (C) both = cả hai – không có hai đối tượng cụ thể nào được nhắc đến.\nDịch: Tôi sẽ tuyển nhân viên thời vụ để đảm bảo rằng chúng ta có thể đáp ứng những nhu cầu tăng thêm này."},{"n":142,"opts":["lines","steps","names","routines"],"ans":"D","xp":"Từ vựng (danh từ): nhân viên cũ giúp nhân viên thời vụ học cách làm việc → (D) routines = quy trình/công việc thường ngày. (A) lines = hàng, dòng, (B) steps = bước (cần nói rõ bước của việc gì), (C) names = tên – không hợp với câu sau 'all operations run smoothly'.\nDịch: Xin hãy dành thời gian giúp họ làm quen với các quy trình công việc thường ngày của chúng ta khi họ ở đây."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following article.","passage":"<p>DALLAS (July 28)—Zura Technology Solutions (ZTS) announced today that it has completed the <span class=\"blank\" data-n=\"143\">-------</span> of an office building located at 425 Van Kirk Street here in Dallas. The building, most recently the headquarters of Brickhall Insurance, will serve as ZTS's <span class=\"blank\" data-n=\"144\">-------</span> base of operations. The company's relocation from Fort Worth is expected to be complete by the end of the calendar year. <span class=\"blank\" data-n=\"145\">-------</span>. \"Our decision to acquire the building reflects ZTS's ongoing commitment to the Dallas area and will enable us to better serve our customers, business partners, and stakeholders,\" said Gloria Rubirosa, ZTS's CEO. \"From our new home in Dallas, we <span class=\"blank\" data-n=\"146\">-------</span> to work hard to meet the needs of each and every one of our customers around the world.\"</p>","vi":"DALLAS (28 tháng 7) — Công ty Giải pháp Công nghệ Zura (ZTS) hôm nay thông báo đã hoàn tất việc mua một tòa nhà văn phòng tại số 425 phố Van Kirk ở Dallas. Tòa nhà, gần đây nhất là trụ sở của Công ty Bảo hiểm Brickhall, sẽ trở thành cơ sở hoạt động chính của ZTS. Việc chuyển trụ sở của công ty từ Fort Worth dự kiến sẽ hoàn tất vào cuối năm dương lịch. Ban lãnh đạo ZTS xem việc chuyển địa điểm này là một bước đi chiến lược. \"Quyết định mua tòa nhà này thể hiện cam kết lâu dài của ZTS đối với khu vực Dallas và sẽ giúp chúng tôi phục vụ tốt hơn khách hàng, đối tác kinh doanh và các bên liên quan,\" bà Gloria Rubirosa, Giám đốc điều hành của ZTS, cho biết. \"Từ ngôi nhà mới ở Dallas, chúng tôi sẽ tiếp tục làm việc chăm chỉ để đáp ứng nhu cầu của từng khách hàng trên khắp thế giới.\"","qs":[{"n":143,"opts":["construction","cleaning","inspection","purchase"],"ans":"D","xp":"Từ vựng (danh từ): phía sau CEO nói 'Our decision to acquire the building' (quyết định mua lại tòa nhà) → công ty đã hoàn tất việc mua tòa nhà: (D) purchase = việc mua. 'acquire' là từ đồng nghĩa của 'purchase'. (A) construction = xây dựng (tòa nhà đã có sẵn, từng là trụ sở Brickhall), (B) cleaning = dọn dẹp, (C) inspection = kiểm tra.\nDịch: ZTS hôm nay thông báo đã hoàn tất việc mua một tòa nhà văn phòng tại số 425 phố Van Kirk ở Dallas."},{"n":144,"opts":["voluntary","primary","short-term","occasional"],"ans":"B","xp":"Từ vựng (tính từ): câu sau nói công ty chuyển hẳn từ Fort Worth sang (relocation) và gọi Dallas là 'our new home' → tòa nhà sẽ là cơ sở hoạt động chính: (B) primary = chính, chủ yếu. (A) voluntary = tự nguyện, (C) short-term = ngắn hạn, (D) occasional = thỉnh thoảng – mâu thuẫn với việc chuyển trụ sở lâu dài.\nDịch: Tòa nhà, gần đây nhất là trụ sở của Công ty Bảo hiểm Brickhall, sẽ trở thành cơ sở hoạt động chính của ZTS."},{"n":145,"opts":["ZTS's leadership team sees the move as strategic.","For example, it provides a range of services to small businesses.","There are only a few available sites in the Main Street District.","Over 15,000 people are employed by ZTS worldwide."],"ans":"A","xp":"Điền câu: câu trước nói về việc chuyển trụ sở (relocation); câu sau là lời CEO giải thích quyết định mua tòa nhà sẽ giúp phục vụ khách hàng tốt hơn → câu ở giữa hợp lý là (A) 'ZTS's leadership team sees the move as strategic.' – 'the move' = việc chuyển trụ sở, và lời CEO minh họa cho tính chiến lược đó. (B) 'For example' không có ý trước để làm ví dụ, (C) nói về Main Street District – không liên quan (tòa nhà ở Van Kirk Street), (D) số nhân viên – lạc ý.\n(A) Ban lãnh đạo ZTS xem việc chuyển địa điểm này là một bước đi chiến lược.\n(B) Ví dụ, công ty cung cấp nhiều dịch vụ cho các doanh nghiệp nhỏ.\n(C) Chỉ có một vài địa điểm còn trống ở Khu Main Street.\n(D) ZTS có hơn 15.000 nhân viên trên toàn thế giới."},{"n":146,"opts":["continued","continuing","would have continued","will continue"],"ans":"D","xp":"Thì động từ: câu thiếu động từ chính sau chủ ngữ 'we' → loại (B) continuing. Công ty chưa chuyển xong (dự kiến hoàn tất cuối năm), 'From our new home' nói về tương lai → (D) will continue = sẽ tiếp tục. (A) continued là quá khứ, (C) would have continued là giả định quá khứ – sai nghĩa.\nDịch: Từ ngôi nhà mới ở Dallas, chúng tôi sẽ tiếp tục làm việc chăm chỉ để đáp ứng nhu cầu của từng khách hàng trên khắp thế giới."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following advertisement.","passages":["<h3>Zoya's Basket</h3><p>12 Tilton Street, Tenafly, NJ 07670<br>www.zoyasbasket.com</p><p>Do you love all the products at Zoya's Basket? Here's a reason to love them even more! Sign up for our reward program and get up to 5% back on everything Zoya's offers! Use your cash rewards in the store or online.</p><ul><li>Vitamins and supplements</li><li>Nut and seed butters</li><li>Jams, jellies, and fruit spreads</li><li>Whole grains and cereals</li><li>Health and wellness products</li></ul><p>We ship throughout New Jersey. Shipping is free with a minimum $35 purchase. Please allow up to three days for delivery.</p>"],"vi":"Zoya's Basket\n12 Tilton Street, Tenafly, NJ 07670\nwww.zoyasbasket.com\n\nBạn có yêu thích tất cả các sản phẩm tại Zoya's Basket không? Đây là một lý do để bạn yêu chúng hơn nữa! Hãy đăng ký chương trình tích điểm thưởng của chúng tôi và nhận lại tới 5% cho mọi sản phẩm mà Zoya's cung cấp! Hãy dùng tiền thưởng của bạn tại cửa hàng hoặc mua trực tuyến.\n\n- Vitamin và thực phẩm bổ sung\n- Bơ các loại hạt\n- Mứt, thạch trái cây và các loại phết trái cây\n- Ngũ cốc nguyên hạt và ngũ cốc ăn sáng\n- Sản phẩm sức khỏe và chăm sóc cơ thể\n\nChúng tôi giao hàng trên toàn bang New Jersey. Miễn phí giao hàng cho đơn hàng tối thiểu 35 đô la. Vui lòng chờ tối đa ba ngày để nhận hàng.","qs":[{"n":147,"q":"What is one purpose of the advertisement?","qvi":"Một mục đích của quảng cáo là gì?","opts":["To announce a sale on discontinued products","To ask consumers for feedback on their favorite items","To encourage consumers to join a reward program","To advertise a special offer on fresh fruits and vegetables"],"ans":"C","xp":"Câu hỏi mục đích. Bằng chứng: \"Sign up for our reward program and get up to 5% back on everything Zoya's offers!\" → quảng cáo kêu gọi khách đăng ký chương trình tích điểm thưởng. \"Sign up for\" = \"join\" (tham gia). → Chọn (C).\n(A) sai: không nói gì về giảm giá hàng ngừng sản xuất. (B) sai: không xin ý kiến khách. (D) sai: danh sách sản phẩm không có trái cây và rau tươi (chỉ có mứt, phết trái cây).\n(A) Để thông báo đợt giảm giá các sản phẩm ngừng kinh doanh\n(B) Để xin ý kiến phản hồi của khách hàng về các món họ yêu thích\n(C) Để khuyến khích khách hàng tham gia một chương trình tích điểm thưởng\n(D) Để quảng cáo ưu đãi đặc biệt cho trái cây và rau tươi"},{"n":148,"q":"What is indicated about deliveries?","qvi":"Điều gì được nêu về việc giao hàng?","opts":["They require a signature.","They arrive within three days.","They are free with a coupon code.","They must be scheduled at the time the order is placed."],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"Please allow up to three days for delivery.\" (Vui lòng chờ tối đa ba ngày để nhận hàng) → hàng đến trong vòng ba ngày. \"up to three days\" = \"within three days\". → Chọn (B).\n(C) sai: miễn phí giao hàng khi mua tối thiểu 35 đô la (\"free with a minimum $35 purchase\"), không phải nhờ mã giảm giá. (A), (D) không được nhắc đến.\n(A) Cần có chữ ký khi nhận.\n(B) Hàng đến trong vòng ba ngày.\n(C) Được miễn phí khi dùng mã giảm giá.\n(D) Phải hẹn lịch giao ngay khi đặt hàng."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following advertisement.","passages":["<h3>Grecian Terrace Hotel</h3><p>Host your next business conference at our five-star hotel on the beautiful Messenian Gulf. Our facility has spacious meeting rooms overlooking the sea and the picturesque beach. The hotel is the perfect setting for a corporate retreat for your staff. Enjoy a team bonding experience while taking advantage of gourmet meals, great views, and first-rate entertainment.</p><p><b>Contact:</b> Helena Samaras, Hospitality Manager<br>hsamaras@grecianterrace.com.gr<br>+30 2721 093365</p>"],"vi":"Khách sạn Grecian Terrace\n\nHãy tổ chức hội nghị kinh doanh sắp tới của bạn tại khách sạn năm sao của chúng tôi bên vịnh Messenian xinh đẹp. Cơ sở của chúng tôi có các phòng họp rộng rãi nhìn ra biển và bãi biển đẹp như tranh. Khách sạn là địa điểm hoàn hảo cho một chuyến nghỉ dưỡng tập thể của công ty dành cho nhân viên của bạn. Hãy tận hưởng trải nghiệm gắn kết đội nhóm đồng thời thưởng thức những bữa ăn hảo hạng, cảnh đẹp và các hoạt động giải trí hàng đầu.\n\nLiên hệ: Helena Samaras, Quản lý dịch vụ khách hàng\nhsamaras@grecianterrace.com.gr\n+30 2721 093365","qs":[{"n":149,"q":"For whom is the advertisement most likely intended?","qvi":"Quảng cáo này nhiều khả năng dành cho ai?","opts":["Residents of Kalamata","Overseas visitors on holiday","Corporate travel planners","Local catering companies"],"ans":"C","xp":"Câu hỏi suy luận (đối tượng). Bằng chứng: \"Host your next business conference at our five-star hotel\" và \"The hotel is the perfect setting for a corporate retreat for your staff.\" → quảng cáo nhắm đến những người lo việc tổ chức hội nghị, chuyến đi cho nhân viên công ty → người lên kế hoạch các chuyến công tác/sự kiện của doanh nghiệp. → Chọn (C).\n(B) sai: quảng cáo không nói về khách du lịch nghỉ lễ mà về hội nghị, nghỉ dưỡng cho nhân viên. (A), (D) không có căn cứ.\n(A) Cư dân thành phố Kalamata\n(B) Du khách nước ngoài đi nghỉ\n(C) Người lên kế hoạch các chuyến đi/sự kiện cho doanh nghiệp\n(D) Các công ty cung cấp đồ ăn địa phương"},{"n":150,"q":"What is indicated about the Grecian Terrace Hotel?","qvi":"Điều gì được nêu về khách sạn Grecian Terrace?","opts":["It just renovated its dining room.","It is under new management.","It has several locations.","It is near the seaside."],"ans":"D","xp":"Câu hỏi chi tiết. Bằng chứng: \"our five-star hotel on the beautiful Messenian Gulf\" và \"meeting rooms overlooking the sea and the picturesque beach\" → khách sạn nằm bên vịnh, phòng họp nhìn ra biển → gần bờ biển. → Chọn (D).\n(A), (B), (C) không được nhắc đến.\n(A) Khách sạn vừa sửa lại phòng ăn.\n(B) Khách sạn có ban quản lý mới.\n(C) Khách sạn có nhiều chi nhánh.\n(D) Khách sạn ở gần bờ biển."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following report.","passages":["<h4>Cozilete Slippers</h4><h3>Social Media Report for December</h3><table><tr><th>Metric</th><th>Results</th></tr><tr><td>Number of posts this month</td><td>8</td></tr><tr><td>For each post, average number of times the post was viewed</td><td>223,648</td></tr><tr><td>Average number of individuals who viewed each post</td><td>87,122</td></tr><tr><td>Average number of advertisements for Cozilete Slippers per post</td><td>1</td></tr><tr><td>Average number of times a link to an advertisement in a post was clicked</td><td>24,015</td></tr><tr><td>Average total interactions per post (number of likes, shares, and comments)</td><td>674</td></tr></table><p>Data for corporate internal use only</p>"],"vi":"Cozilete Slippers\nBáo cáo mạng xã hội tháng Mười Hai\n\nChỉ số | Kết quả\nSố bài đăng trong tháng | 8\nVới mỗi bài đăng, số lượt xem trung bình | 223.648\nSố người trung bình đã xem mỗi bài đăng | 87.122\nSố quảng cáo trung bình cho Cozilete Slippers trong mỗi bài đăng | 1\nSố lần trung bình đường dẫn đến quảng cáo trong bài đăng được nhấp vào | 24.015\nTổng số lượt tương tác trung bình mỗi bài (số lượt thích, chia sẻ và bình luận) | 674\n\nDữ liệu chỉ dùng nội bộ công ty","qs":[{"n":151,"q":"For whom is the report most likely intended?","qvi":"Báo cáo này nhiều khả năng dành cho ai?","opts":["Cozilete Slippers' suppliers","Cozilete Slippers' marketing team","Cozilete Slippers' shipping department","Cozilete Slippers' most loyal customers"],"ans":"B","xp":"Câu hỏi suy luận (đối tượng). Đây là \"Social Media Report\" (báo cáo mạng xã hội) với các số liệu về lượt xem, quảng cáo, lượt nhấp vào quảng cáo, lượt thích/chia sẻ/bình luận, và ghi chú \"Data for corporate internal use only\" (chỉ dùng nội bộ). Những số liệu này phục vụ cho việc quảng bá sản phẩm → dành cho đội marketing của công ty. → Chọn (B).\n(A), (D) sai vì dữ liệu chỉ dùng nội bộ, không dành cho người ngoài. (C) bộ phận vận chuyển không liên quan đến mạng xã hội.\n(A) Các nhà cung cấp của Cozilete Slippers\n(B) Đội marketing của Cozilete Slippers\n(C) Bộ phận vận chuyển của Cozilete Slippers\n(D) Những khách hàng trung thành nhất của Cozilete Slippers"},{"n":152,"q":"What is indicated in the report?","qvi":"Điều gì được nêu trong báo cáo?","opts":["Every post contained more than one advertisement for Cozilete Slippers.","Most individuals commented on each post they viewed.","Each post was viewed by an average of about 87,000 individuals.","Few individuals viewed a post more than one time."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"Average number of individuals who viewed each post — 87,122\" → trung bình mỗi bài được khoảng 87.000 người xem. → Chọn (C).\n(A) sai: trung bình chỉ có 1 quảng cáo mỗi bài. (B) sai: tổng tương tác (thích, chia sẻ, bình luận) chỉ 674 trên 87.122 người xem. (D) sai: lượt xem trung bình 223.648 lớn hơn nhiều so với 87.122 người → nhiều người xem một bài hơn một lần.\n(A) Mỗi bài đăng có nhiều hơn một quảng cáo cho Cozilete Slippers.\n(B) Hầu hết mọi người đều bình luận vào mỗi bài họ xem.\n(C) Mỗi bài đăng được trung bình khoảng 87.000 người xem.\n(D) Rất ít người xem một bài đăng nhiều hơn một lần."}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Keri Mohan (12:40 P.M.)</b></p><p>I'm nearly done readying the jewelry orders for shipment. I've inserted a packing slip and business card in each box. Should anything else be included before I seal them up and drop them off at the post office?</p></div><div class=\"msg\"><p><b>Sujay Rishi (12:42 P.M.)</b></p><p>Can you put a Rishi Gemstones magnet in each box?</p></div><div class=\"msg\"><p><b>Keri Mohan (12:43 P.M.)</b></p><p>Certainly! I'll do that right away.</p></div><div class=\"msg\"><p><b>Keri Mohan (12:50 P.M.)</b></p><p>Also, we're running low on shipping labels. I can order some more.</p></div><div class=\"msg\"><p><b>Sujay Rishi (12:54 P.M.)</b></p><p>Actually, we have an entire bin of them. Check the supply closet. Let me know if you can't find them.</p></div>"],"vi":"Keri Mohan (12:40 chiều): Tôi sắp chuẩn bị xong các đơn hàng trang sức để gửi đi. Tôi đã cho một phiếu đóng gói và danh thiếp vào mỗi hộp. Có cần cho thêm thứ gì nữa trước khi tôi dán kín hộp và mang ra bưu điện không?\n\nSujay Rishi (12:42 chiều): Chị có thể cho một miếng nam châm Rishi Gemstones vào mỗi hộp được không?\n\nKeri Mohan (12:43 chiều): Chắc chắn rồi! Tôi sẽ làm ngay.\n\nKeri Mohan (12:50 chiều): À, chúng ta cũng sắp hết nhãn gửi hàng. Tôi có thể đặt mua thêm.\n\nSujay Rishi (12:54 chiều): Thật ra chúng ta có nguyên một thùng nhãn. Chị kiểm tra tủ đồ dùng nhé. Nếu không tìm thấy thì báo tôi.","qs":[{"n":153,"q":"What does Ms. Mohan ask about?","qvi":"Cô Mohan hỏi về điều gì?","opts":["What to include in some boxes","When an order will be shipped","How to safely package the jewelry","Where the business cards are stored"],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"Should anything else be included before I seal them up...?\" (Có cần cho thêm thứ gì vào nữa trước khi dán kín hộp không?) → cô hỏi nên cho thêm gì vào các hộp. → Chọn (A).\n(D) sai: cô đã cho danh thiếp vào hộp rồi, không hỏi danh thiếp để ở đâu. (B), (C) không được hỏi.\n(A) Nên cho những gì vào một số hộp\n(B) Khi nào một đơn hàng sẽ được gửi đi\n(C) Cách đóng gói trang sức an toàn\n(D) Danh thiếp được cất ở đâu"},{"n":154,"q":"At 12:54 P.M., what does Mr. Rishi most likely mean when he writes, \"Actually, we have an entire bin of them\"?","qvi":"Lúc 12:54 chiều, khi anh Rishi viết \"Actually, we have an entire bin of them\", ý anh ấy nhiều khả năng là gì?","opts":["Ms. Mohan can give away the magnets.","Ms. Mohan can reorganize the supply closet.","Ms. Mohan should not order more labels.","Ms. Mohan should not go to the post office."],"ans":"C","xp":"Câu hỏi hàm ý. Ngay trước đó cô Mohan viết: \"we're running low on shipping labels. I can order some more.\" (sắp hết nhãn gửi hàng, tôi có thể đặt thêm). Anh Rishi trả lời \"Actually, we have an entire bin of them. Check the supply closet.\" → \"them\" = nhãn gửi hàng; vẫn còn cả một thùng nên không cần đặt mua thêm. → Chọn (C).\n(A) sai: \"them\" không chỉ nam châm. (B) anh chỉ bảo kiểm tra tủ, không bảo sắp xếp lại. (D) không liên quan.\n(A) Cô Mohan có thể tặng các miếng nam châm.\n(B) Cô Mohan có thể sắp xếp lại tủ đồ dùng.\n(C) Cô Mohan không nên đặt mua thêm nhãn.\n(D) Cô Mohan không nên đến bưu điện."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following notice.","passages":["<h3>Twin Lakes</h3><p><i>The best place to live in Tielersburg!</i></p><p><b>Please join the staff of Twin Lakes for our monthly resident information meeting.</b></p><p><b>Date and time:</b> Tuesday, March 21, 7:00 P.M.–8:30 P.M.<br><b>Location:</b> Community Center conference room (across the hall from the rental office)</p><p><b>Agenda items and presenters:</b></p><ol><li>Property enhancements: overview of plans for fence repair and new landscaping in the pool area—Mr. Abgarian, groundskeeping and maintenance supervisor</li><li>Community garden: details for garden plot sign-up and annual biggest tomato contest—Ms. Kantor, events and activities coordinator</li><li>Water main work on Huron Street: progress update—Mr. Carter, Department of Public Works, City of Tielersburg</li><li>Utility rates: discussion about the rise in quarterly utility fees charged to Twin Lakes property management by the city—Mr. Underwood, general manager</li><li>New business: creation of Resident Advisory Board—Ms. Davis, leasing and resident relations manager</li><li>Questions and comments</li><li>Adjournment</li></ol>"],"vi":"Twin Lakes\nNơi sống tuyệt vời nhất ở Tielersburg!\n\nMời quý cư dân tham dự buổi họp thông tin cư dân hằng tháng cùng đội ngũ nhân viên Twin Lakes.\n\nNgày giờ: Thứ Ba, ngày 21 tháng 3, 7:00 tối – 8:30 tối\nĐịa điểm: Phòng hội nghị của Trung tâm Cộng đồng (đối diện văn phòng cho thuê, bên kia hành lang)\n\nCác nội dung trong chương trình và người trình bày:\n1. Nâng cấp khu nhà: tổng quan kế hoạch sửa hàng rào và làm cảnh quan mới ở khu hồ bơi — ông Abgarian, giám sát chăm sóc khuôn viên và bảo trì\n2. Vườn cộng đồng: chi tiết về việc đăng ký ô đất trồng và cuộc thi quả cà chua to nhất hằng năm — bà Kantor, điều phối viên sự kiện và hoạt động\n3. Công trình đường ống nước chính trên phố Huron: cập nhật tiến độ — ông Carter, Sở Công chính, Thành phố Tielersburg\n4. Giá dịch vụ tiện ích: thảo luận về việc thành phố tăng phí tiện ích hằng quý tính cho ban quản lý Twin Lakes — ông Underwood, tổng giám đốc\n5. Vấn đề mới: thành lập Ban Tư vấn Cư dân — bà Davis, quản lý cho thuê và quan hệ cư dân\n6. Hỏi đáp và góp ý\n7. Kết thúc buổi họp","qs":[{"n":155,"q":"What most likely is Twin Lakes?","qvi":"Twin Lakes nhiều khả năng là gì?","opts":["A group of shops","A gardening center","An amusement park","A housing complex"],"ans":"D","xp":"Câu hỏi suy luận. Bằng chứng: khẩu hiệu \"The best place to live in Tielersburg!\" (nơi tốt nhất để sống), buổi họp dành cho cư dân \"monthly resident information meeting\", có \"rental office\" (văn phòng cho thuê), hồ bơi, \"leasing and resident relations manager\" → đây là một khu nhà ở/khu căn hộ cho thuê. → Chọn (D).\n(B) sai: vườn cộng đồng chỉ là một tiện ích trong khu. (A), (C) không phù hợp.\n(A) Một dãy cửa hàng\n(B) Một trung tâm làm vườn\n(C) Một công viên giải trí\n(D) Một khu nhà ở"},{"n":156,"q":"What is Mr. Abgarian's role in the meeting?","qvi":"Vai trò của ông Abgarian trong buổi họp là gì?","opts":["To provide information about scheduled improvements","To explain details of an annual contest","To plan the repair of a broken water pipe","To set the fees people will pay"],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"Property enhancements: overview of plans for fence repair and new landscaping in the pool area—Mr. Abgarian\" → ông trình bày tổng quan kế hoạch nâng cấp (sửa hàng rào, làm cảnh quan mới). \"enhancements / plans\" = \"scheduled improvements\" (các cải tiến đã lên kế hoạch). → Chọn (A).\n(B) là phần của bà Kantor. (C) đường ống nước là phần cập nhật của ông Carter. (D) phí tiện ích do ông Underwood thảo luận, và cũng không phải \"đặt ra\" phí.\n(A) Cung cấp thông tin về các hạng mục cải tiến đã lên lịch\n(B) Giải thích chi tiết về một cuộc thi hằng năm\n(C) Lên kế hoạch sửa một đường ống nước bị vỡ\n(D) Đặt ra mức phí mọi người sẽ phải trả"},{"n":157,"q":"Who has job responsibilities outside of Twin Lakes?","qvi":"Ai có trách nhiệm công việc bên ngoài Twin Lakes?","opts":["Ms. Kantor","Mr. Carter","Mr. Underwood","Ms. Davis"],"ans":"B","xp":"Câu hỏi suy luận. Bằng chứng: \"Mr. Carter, Department of Public Works, City of Tielersburg\" → ông Carter làm cho Sở Công chính của thành phố, không phải nhân viên Twin Lakes. Những người còn lại đều có chức danh thuộc Twin Lakes: Ms. Kantor (điều phối sự kiện), Mr. Underwood (tổng giám đốc), Ms. Davis (quản lý cho thuê và quan hệ cư dân). → Chọn (B).\n(A) Bà Kantor\n(B) Ông Carter\n(C) Ông Underwood\n(D) Bà Davis"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following notice.","passages":["<h3>Lingate Chemical Corporation</h3><h4>Laboratory Safety Rules</h4><p>The following is a partial list of rules you must follow while in the laboratory. Before beginning work in the lab, all workers are also required to read our most recent safety manual and complete our basic safety course. Please contact Mr. Kang if you need to complete these prerequisites.</p><ul><li>Wear mandatory lab coat, goggles, and footwear.</li><li>Follow directions on posted signs in case of an accident.</li><li>Know how to properly operate all safety equipment (fire extinguishers, eye wash stations, etc.).</li><li>Know the location of all emergency exits.</li><li>Refrain from eating or drinking in the laboratory.</li><li>Report any unsafe conditions, accidents, or spills immediately to your supervisor.</li><li>In an emergency, exit immediately, call emergency services, and then contact your supervisor.</li></ul>"],"vi":"Tập đoàn Hóa chất Lingate\nQuy định an toàn phòng thí nghiệm\n\nDưới đây là một phần danh sách các quy định bạn phải tuân theo khi ở trong phòng thí nghiệm. Trước khi bắt đầu làm việc trong phòng thí nghiệm, tất cả nhân viên cũng bắt buộc phải đọc cẩm nang an toàn mới nhất của chúng tôi và hoàn thành khóa học an toàn cơ bản. Vui lòng liên hệ ông Kang nếu bạn cần hoàn thành các yêu cầu bắt buộc này.\n\n- Mặc áo khoác phòng thí nghiệm, đeo kính bảo hộ và mang giày dép theo quy định.\n- Làm theo hướng dẫn trên các biển báo được dán sẵn khi xảy ra sự cố.\n- Biết cách sử dụng đúng tất cả thiết bị an toàn (bình chữa cháy, trạm rửa mắt, v.v.).\n- Biết vị trí của tất cả các lối thoát hiểm.\n- Không ăn uống trong phòng thí nghiệm.\n- Báo cáo ngay cho người giám sát mọi tình trạng mất an toàn, tai nạn hoặc sự cố tràn đổ hóa chất.\n- Khi có tình huống khẩn cấp, hãy ra ngoài ngay lập tức, gọi dịch vụ cấp cứu, rồi sau đó liên hệ người giám sát của bạn.","qs":[{"n":158,"q":"Who is the notice most likely intended for?","qvi":"Thông báo này nhiều khả năng dành cho ai?","opts":["Students","Employees","Cleaning crews","Emergency personnel"],"ans":"B","xp":"Câu hỏi suy luận (đối tượng). Bằng chứng: \"Before beginning work in the lab, all workers are also required to read our most recent safety manual...\" và \"Report any unsafe conditions... to your supervisor.\" → người đọc là những người làm việc trong phòng thí nghiệm của công ty, có người giám sát → nhân viên. \"workers\" ≈ \"employees\". → Chọn (B).\n(A) đây là tập đoàn hóa chất, không phải trường học. (C), (D) không có căn cứ; nhân viên cấp cứu là người được gọi đến chứ không phải người đọc.\n(A) Học sinh, sinh viên\n(B) Nhân viên\n(C) Đội vệ sinh\n(D) Nhân viên cấp cứu"},{"n":159,"q":"Why would Mr. Kang be contacted?","qvi":"Tại sao người ta liên hệ với ông Kang?","opts":["To obtain safety equipment","To report unsafe conditions","To arrange to complete a course","To submit revisions to the safety manual"],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"all workers are also required to read our most recent safety manual and complete our basic safety course. Please contact Mr. Kang if you need to complete these prerequisites.\" → liên hệ ông Kang nếu cần hoàn thành các yêu cầu bắt buộc, trong đó có khóa học an toàn cơ bản → để sắp xếp hoàn thành khóa học. → Chọn (C).\n(B) sai: tình trạng mất an toàn phải báo cho \"your supervisor\" (người giám sát), không phải ông Kang. (A), (D) không được nhắc đến.\n(A) Để nhận thiết bị an toàn\n(B) Để báo cáo tình trạng mất an toàn\n(C) Để sắp xếp hoàn thành một khóa học\n(D) Để nộp các chỉnh sửa cho cẩm nang an toàn"},{"n":160,"q":"What is NOT a stated rule for working in the laboratory?","qvi":"Điều nào KHÔNG phải là quy định được nêu khi làm việc trong phòng thí nghiệm?","opts":["Goggles must be worn.","Exits must remain open.","Food must not be eaten.","Accidents must be reported."],"ans":"B","xp":"Câu hỏi NOT. Đối chiếu từng phương án:\n(A) có: \"Wear mandatory lab coat, goggles, and footwear.\"\n(C) có: \"Refrain from eating or drinking in the laboratory.\"\n(D) có: \"Report any unsafe conditions, accidents, or spills immediately to your supervisor.\"\n(B) không có: thông báo chỉ yêu cầu \"Know the location of all emergency exits\" (biết vị trí lối thoát hiểm), không nói lối thoát phải luôn để mở. → Chọn (B).\n(A) Phải đeo kính bảo hộ.\n(B) Các lối ra phải luôn để mở.\n(C) Không được ăn uống.\n(D) Phải báo cáo các tai nạn."}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> All staff</p><p><b>From:</b> Liza Chu, IT Department</p><p><b>Date:</b> June 8, 1:13 P.M.</p><p><b>Subject:</b> Network issues</p></div><p>Good afternoon everyone. <span class=\"pos\">[1]</span></p><p>At 10:00 this morning, the Information Technology team did some network maintenance, resulting in a series of issues across the building. <span class=\"pos\">[2]</span> We quickly received reports of printer malfunctions, missing network drives, difficulty loading e-mail messages, and other problems. <span class=\"pos\">[3]</span></p><p>We have now stabilized the situation, but if you should still encounter these or similar issues, please attempt first to address them by restarting your computer. <span class=\"pos\">[4]</span></p>"],"vi":"Đến: Toàn thể nhân viên\nTừ: Liza Chu, Phòng Công nghệ Thông tin\nNgày: 8 tháng 6, 1:13 chiều\nChủ đề: Sự cố mạng\n\nChào buổi chiều mọi người.\n\nVào lúc 10 giờ sáng nay, nhóm Công nghệ Thông tin đã tiến hành bảo trì mạng, dẫn đến một loạt sự cố trong toàn tòa nhà. Chúng tôi nhanh chóng nhận được các báo cáo về việc máy in trục trặc, mất ổ đĩa mạng, khó tải thư điện tử và các vấn đề khác.\n\nHiện chúng tôi đã ổn định được tình hình, nhưng nếu bạn vẫn gặp những sự cố này hoặc sự cố tương tự, trước tiên vui lòng thử khắc phục bằng cách khởi động lại máy tính.","qs":[{"n":161,"q":"What is the e-mail about?","qvi":"E-mail nói về điều gì?","opts":["Scheduling a team meeting","Setting up a new e-mail account","Concerns about Web browsing security","Problems with a computer network"],"ans":"D","xp":"Câu hỏi chủ đề. Bằng chứng: tiêu đề \"Subject: Network issues\" và \"the Information Technology team did some network maintenance, resulting in a series of issues across the building.\" → e-mail nói về các sự cố của mạng máy tính. → Chọn (D).\n(B) sai: chỉ nhắc khó tải e-mail, không phải lập tài khoản mới. (A), (C) không được nhắc đến.\n(A) Lên lịch một cuộc họp nhóm\n(B) Thiết lập một tài khoản e-mail mới\n(C) Lo ngại về bảo mật khi duyệt web\n(D) Các sự cố với một mạng máy tính"},{"n":162,"q":"What probably happened before Ms. Chu sent the e-mail?","qvi":"Điều gì có lẽ đã xảy ra trước khi cô Chu gửi e-mail?","opts":["Employees requested assistance from the IT department.","Log-on procedures for company accounts were changed.","Computer equipment was removed from the building.","Some staff members received new printers."],"ans":"A","xp":"Câu hỏi suy luận. Bằng chứng: \"We quickly received reports of printer malfunctions, missing network drives, difficulty loading e-mail messages, and other problems.\" → nhân viên đã báo cáo sự cố cho phòng IT, tức là đã nhờ phòng IT hỗ trợ. → Chọn (A).\n(D) sai: chỉ nói máy in trục trặc, không nói nhận máy in mới. (B), (C) không được nhắc đến.\n(A) Nhân viên đã yêu cầu phòng IT hỗ trợ.\n(B) Quy trình đăng nhập tài khoản công ty đã được thay đổi.\n(C) Thiết bị máy tính đã được chuyển ra khỏi tòa nhà.\n(D) Một số nhân viên đã nhận máy in mới."},{"n":163,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"If you continue to have problems after doing so, then give us a call.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Nếu bạn vẫn tiếp tục gặp sự cố sau khi làm như vậy, hãy gọi cho chúng tôi.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"Câu hỏi điền câu. Câu cần điền có cụm \"after doing so\" (sau khi làm như vậy) → phải đứng sau một câu nêu một việc cần làm. Câu trước vị trí [4] là: \"please attempt first to address them by restarting your computer.\" (trước tiên hãy thử khởi động lại máy tính). \"doing so\" = khởi động lại máy; \"first\" (trước tiên) ... rồi nếu vẫn lỗi thì \"give us a call\" (gọi cho chúng tôi) → mạch logic hoàn chỉnh. → Chọn (D).\nCác vị trí [1], [2], [3] chưa có hành động nào để \"doing so\" chỉ đến."}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Sunisa Sommer (1:30 P.M.)</b></p><p>Hi Raphael and Hamed. Can either of you tell me where I can find the laptop that's usually in Conference Room B? It isn't on the cart with the projector.</p></div><div class=\"msg\"><p><b>Raphael Luongo (1:32 P.M.)</b></p><p>I used it for my presentation on Monday, but I left it in the conference room.</p></div><div class=\"msg\"><p><b>Hamed Gabr (1:32 P.M.)</b></p><p>I believe Martin Dabliz was going to ask someone in the IT department to look at it because it wasn't working properly.</p></div><div class=\"msg\"><p><b>Sunisa Sommer (1:34 P.M.)</b></p><p>Got it. Do you know if a repair ticket was submitted?</p></div><div class=\"msg\"><p><b>Hamed Gabr (1:35 P.M.)</b></p><p>I don't think Martin knows all the IT procedures. He's only in his first week.</p></div><div class=\"msg\"><p><b>Sunisa Sommer (1:37 P.M.)</b></p><p>Right. We should make sure that information is included in the employee orientation materials.</p></div><div class=\"msg\"><p><b>Raphael Luongo (1:41 P.M.)</b></p><p>I don't see a ticket on the IT site. I'll reach out to IT and take care of that now.</p></div>"],"vi":"Sunisa Sommer (1:30 chiều): Chào Raphael và Hamed. Có ai trong hai anh biết chiếc máy tính xách tay thường để ở Phòng họp B giờ ở đâu không? Nó không có trên xe đẩy cùng với máy chiếu.\n\nRaphael Luongo (1:32 chiều): Tôi đã dùng nó cho buổi thuyết trình hôm thứ Hai, nhưng tôi để nó lại trong phòng họp.\n\nHamed Gabr (1:32 chiều): Tôi nghĩ Martin Dabliz định nhờ ai đó ở phòng IT xem giúp vì nó không hoạt động bình thường.\n\nSunisa Sommer (1:34 chiều): Tôi hiểu rồi. Các anh có biết đã gửi phiếu yêu cầu sửa chữa chưa?\n\nHamed Gabr (1:35 chiều): Tôi không nghĩ Martin biết hết các quy trình của IT. Cậu ấy mới đi làm tuần đầu tiên thôi.\n\nSunisa Sommer (1:37 chiều): Đúng vậy. Chúng ta nên đảm bảo thông tin đó có trong tài liệu định hướng cho nhân viên mới.\n\nRaphael Luongo (1:41 chiều): Tôi không thấy phiếu yêu cầu nào trên trang của IT. Tôi sẽ liên hệ IT và lo việc đó ngay bây giờ.","qs":[{"n":164,"q":"Why does Ms. Sommer message her colleagues?","qvi":"Tại sao cô Sommer nhắn tin cho đồng nghiệp?","opts":["To alert them that a projector is broken","To ask where a computer has been put","To request help creating a presentation","To find out whether a conference room is available"],"ans":"B","xp":"Câu hỏi mục đích. Bằng chứng: \"Can either of you tell me where I can find the laptop that's usually in Conference Room B?\" → cô hỏi chiếc máy tính xách tay đang ở đâu. \"laptop\" = \"a computer\". → Chọn (B).\n(A) sai: máy chiếu chỉ được nhắc đến như nơi để laptop (\"the cart with the projector\"), không bị hỏng; thứ không hoạt động là laptop. (C), (D) không đúng.\n(A) Để báo cho họ biết một máy chiếu bị hỏng\n(B) Để hỏi một chiếc máy tính đã được để ở đâu\n(C) Để nhờ giúp làm một bài thuyết trình\n(D) Để tìm hiểu xem một phòng họp có trống không"},{"n":165,"q":"At 1:34 P.M., what does Ms. Sommer most likely mean when she writes, \"Got it\"?","qvi":"Lúc 1:34 chiều, khi cô Sommer viết \"Got it\", ý cô ấy nhiều khả năng là gì?","opts":["She found the repair ticket.","She now has access to a Web site.","She knows the correct procedure to follow.","She understands what happened."],"ans":"D","xp":"Câu hỏi hàm ý. Ngay trước đó anh Gabr giải thích: \"Martin Dabliz was going to ask someone in the IT department to look at it because it wasn't working properly.\" (laptop bị trục trặc nên Martin định nhờ IT xem). Cô Sommer đáp \"Got it.\" (Tôi hiểu rồi) rồi hỏi tiếp về phiếu sửa chữa → cô đã hiểu chuyện gì đã xảy ra với chiếc laptop. → Chọn (D).\n(A) sai: cô còn đang hỏi có phiếu sửa chữa chưa. (B), (C) không có căn cứ.\n(A) Cô ấy đã tìm thấy phiếu yêu cầu sửa chữa.\n(B) Giờ cô ấy đã truy cập được một trang web.\n(C) Cô ấy biết đúng quy trình cần làm theo.\n(D) Cô ấy hiểu điều gì đã xảy ra."},{"n":166,"q":"What is suggested about Mr. Dabliz?","qvi":"Điều gì được gợi ý về anh Dabliz?","opts":["He was recently hired.","He is Mr. Gabr's supervisor.","He is the chief technology officer.","He was interviewed on Monday."],"ans":"A","xp":"Câu hỏi suy luận. Bằng chứng: \"I don't think Martin knows all the IT procedures. He's only in his first week.\" và cô Sommer muốn đưa thông tin này vào \"employee orientation materials\" (tài liệu định hướng cho nhân viên mới) → Martin Dabliz là nhân viên mới được tuyển. → Chọn (A).\n(B), (C), (D) không có căn cứ; \"Monday\" là ngày anh Luongo thuyết trình.\n(A) Anh ấy mới được tuyển dụng gần đây.\n(B) Anh ấy là cấp trên của anh Gabr.\n(C) Anh ấy là giám đốc công nghệ.\n(D) Anh ấy được phỏng vấn vào thứ Hai."},{"n":167,"q":"What will Mr. Luongo probably do next?","qvi":"Anh Luongo có lẽ sẽ làm gì tiếp theo?","opts":["Revise a company policy","Repair the laptop himself","Contact the IT department","Update the training materials"],"ans":"C","xp":"Câu hỏi hành động tiếp theo. Bằng chứng: \"I don't see a ticket on the IT site. I'll reach out to IT and take care of that now.\" → anh sẽ liên hệ phòng IT. \"reach out to\" = \"contact\". → Chọn (C).\n(B) sai: anh nhờ IT chứ không tự sửa. (D) là ý cô Sommer đề xuất (\"We should make sure that information is included in the employee orientation materials\"), không phải việc anh Luongo nói sẽ làm. (A) không được nhắc đến.\n(A) Sửa đổi một chính sách của công ty\n(B) Tự sửa chiếc laptop\n(C) Liên hệ phòng IT\n(D) Cập nhật tài liệu đào tạo"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Lindsey Galloway &lt;lgalloway@sportsupplies.com&gt;</p><p><b>From:</b> Samuel Bains &lt;samuelbains@exertreks.com&gt;</p><p><b>Date:</b> August 16</p><p><b>Subject:</b> Exertreks boots for winter activities</p></div><p>Hello Ms. Galloway,</p><p>I am sorry I missed your call this morning. The answers to your questions are given below.</p><p>We here at Exertreks have recently completed the development of our Winter Hikers. Like our other models, they are waterproof, but the Winter Hikers are most appropriate for use in extreme cold. The boots are lined with a proprietary material that is highly effective at retaining body heat. They are also durable, light, and comfortable. For orders of 50 pairs or more of the Winter Hikers, the wholesale price per pair is $65. The recommended retail price is $89. We can deliver your order in two weeks.</p><p>Presale reviews of the boots by experts in outdoor sports have been enthusiastic. You can expect the Winter Hikers to be a big hit with your customers this year. I look forward to hearing from you soon to answer any other questions and to help you with your first order.</p><p>Sincerely,</p><p>Samuel Bains</p>"],"vi":"Đến: Lindsey Galloway <lgalloway@sportsupplies.com>\nTừ: Samuel Bains <samuelbains@exertreks.com>\nNgày: 16 tháng 8\nChủ đề: Giày ống Exertreks cho các hoạt động mùa đông\n\nChào cô Galloway,\n\nTôi rất tiếc đã lỡ cuộc gọi của cô sáng nay. Câu trả lời cho các câu hỏi của cô ở bên dưới.\n\nChúng tôi tại Exertreks vừa hoàn thành việc phát triển dòng giày Winter Hikers. Giống như các mẫu khác của chúng tôi, chúng có khả năng chống thấm nước, nhưng Winter Hikers phù hợp nhất để sử dụng trong điều kiện cực lạnh. Giày được lót bằng một chất liệu độc quyền giữ nhiệt cơ thể rất hiệu quả. Giày cũng bền, nhẹ và thoải mái. Với đơn hàng từ 50 đôi Winter Hikers trở lên, giá bán sỉ mỗi đôi là 65 đô la. Giá bán lẻ đề xuất là 89 đô la. Chúng tôi có thể giao hàng cho cô trong vòng hai tuần.\n\nCác bài đánh giá trước khi mở bán của các chuyên gia thể thao ngoài trời về đôi giày này rất nhiệt tình. Cô có thể kỳ vọng Winter Hikers sẽ là sản phẩm rất được khách hàng của cô ưa chuộng trong năm nay. Tôi mong sớm nhận được hồi âm của cô để giải đáp thêm các thắc mắc khác và hỗ trợ cô với đơn hàng đầu tiên.\n\nTrân trọng,\n\nSamuel Bains","qs":[{"n":168,"q":"What is implied in Mr. Bains's e-mail?","qvi":"Điều gì được ngụ ý trong e-mail của anh Bains?","opts":["Ms. Galloway asked him to check on an order she recently placed.","Ms. Galloway left a message for him asking for information.","He asked Ms. Galloway to return a call he had made the day before.","He and Ms. Galloway met earlier in the day."],"ans":"B","xp":"Câu hỏi suy luận. Bằng chứng: \"I am sorry I missed your call this morning. The answers to your questions are given below.\" → cô Galloway đã gọi (anh lỡ cuộc gọi) và anh biết cô có các câu hỏi → cô đã để lại lời nhắn hỏi thông tin. → Chọn (B).\n(A) sai: cô chưa đặt hàng (\"help you with your first order\" – đơn hàng đầu tiên). (C) sai: chính cô là người gọi. (D) sai: họ không gặp nhau, anh lỡ cuộc gọi của cô.\n(A) Cô Galloway nhờ anh kiểm tra một đơn hàng cô vừa đặt.\n(B) Cô Galloway để lại lời nhắn cho anh để hỏi thông tin.\n(C) Anh nhờ cô Galloway gọi lại về cuộc gọi anh đã gọi hôm trước.\n(D) Anh và cô Galloway đã gặp nhau trước đó trong ngày."},{"n":169,"q":"What is NOT mentioned about the boots?","qvi":"Điều gì KHÔNG được nhắc đến về đôi giày?","opts":["Their color","Their weight","Their durability","Their warmth"],"ans":"A","xp":"Câu hỏi NOT. Đối chiếu:\n(B) trọng lượng: \"They are also durable, light, and comfortable.\" (light = nhẹ)\n(C) độ bền: \"durable\" (bền)\n(D) độ ấm: \"lined with a proprietary material that is highly effective at retaining body heat\" (giữ nhiệt cơ thể rất tốt)\n(A) màu sắc: không được nhắc đến trong e-mail. → Chọn (A).\n(A) Màu sắc của giày\n(B) Trọng lượng của giày\n(C) Độ bền của giày\n(D) Độ ấm của giày"},{"n":170,"q":"The word \"hit\" in paragraph 3, line 2, is closest in meaning to","qvi":"Từ \"hit\" ở đoạn 3, dòng 2 gần nghĩa nhất với","opts":["match","arrival","success","request"],"ans":"C","xp":"Câu hỏi đồng nghĩa. Câu chứa từ: \"You can expect the Winter Hikers to be a big hit with your customers this year.\" Trước đó nói các chuyên gia đánh giá rất nhiệt tình → \"a big hit\" = một sản phẩm rất thành công, được ưa chuộng → \"success\" (sự thành công). → Chọn (C).\n(A) match: trận đấu / sự phù hợp; (B) arrival: sự đến nơi; (D) request: yêu cầu → không hợp nghĩa.\n(A) trận đấu, sự tương xứng\n(B) sự đến nơi\n(C) sự thành công\n(D) yêu cầu"},{"n":171,"q":"What does Mr. Bains want Ms. Galloway to do?","qvi":"Anh Bains muốn cô Galloway làm gì?","opts":["Give the boots a good review online","Contact him to arrange delivery of some boots","Charge customers $65 for each pair of boots","Sell him insulation material to be used in the boots"],"ans":"B","xp":"Câu hỏi chi tiết (yêu cầu). Bằng chứng: \"I look forward to hearing from you soon to answer any other questions and to help you with your first order.\" và \"We can deliver your order in two weeks.\" → anh muốn cô liên hệ lại để đặt đơn hàng giày đầu tiên (sắp xếp việc giao giày). → Chọn (B).\n(A) sai: các bài đánh giá là của chuyên gia. (C) sai: 65 đô la là giá sỉ cô trả cho anh; giá bán lẻ đề xuất cho khách là 89 đô la. (D) sai: chất liệu lót là của chính Exertreks (\"proprietary material\").\n(A) Viết đánh giá tốt cho đôi giày trên mạng\n(B) Liên hệ với anh để sắp xếp giao một số đôi giày\n(C) Tính giá khách hàng 65 đô la cho mỗi đôi giày\n(D) Bán cho anh chất liệu cách nhiệt để dùng trong giày"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following Web page.","passages":["<p>https://www.hurnhamhistoricalsociety.org/news</p><h3>Tuesday Evening Lecture Series</h3><p>We are pleased to announce that our third annual lecture series will be hosted by the Hurnham Heritage Museum on Tuesday evenings over the next six weeks. <span class=\"pos\">[1]</span> Each guest speaker will focus on objects from the museum's permanent collection. <span class=\"pos\">[2]</span> The first lecture, on June 15 at 7:00 P.M., features Georgia Hinds, head curator of the Knowles Art Gallery. <span class=\"pos\">[3]</span> Ms. Hinds will use a writing desk, a chest, and a household table to discuss what furniture can reveal to us about the lives of the first Hurnham residents over 200 years ago.</p><p>The lecture series is open to the public and includes free admission to the Hurnham Heritage Museum. <span class=\"pos\">[4]</span> The Fasseller Café, next door to the museum, will stay open late on Tuesdays to accommodate lecture attendees and the general public.</p><p><i>Posted on June 8</i></p>"],"vi":"https://www.hurnhamhistoricalsociety.org/news\n\nChuỗi bài giảng tối thứ Ba\n\nChúng tôi vui mừng thông báo rằng chuỗi bài giảng thường niên lần thứ ba của chúng tôi sẽ được Bảo tàng Di sản Hurnham tổ chức vào các tối thứ Ba trong sáu tuần tới. Mỗi diễn giả khách mời sẽ tập trung vào các hiện vật thuộc bộ sưu tập thường trực của bảo tàng. Bài giảng đầu tiên, vào ngày 15 tháng 6 lúc 7:00 tối, có sự góp mặt của Georgia Hinds, trưởng ban giám tuyển của Phòng trưng bày Nghệ thuật Knowles. Bà Hinds sẽ dùng một chiếc bàn viết, một chiếc rương và một chiếc bàn gia dụng để bàn về những điều đồ nội thất có thể tiết lộ cho chúng ta về cuộc sống của những cư dân đầu tiên của Hurnham cách đây hơn 200 năm.\n\nChuỗi bài giảng mở cửa cho công chúng và bao gồm vé vào cửa miễn phí Bảo tàng Di sản Hurnham. Quán cà phê Fasseller, ngay cạnh bảo tàng, sẽ mở cửa muộn vào các ngày thứ Ba để phục vụ người tham dự bài giảng và công chúng.\n\nĐăng ngày 8 tháng 6","qs":[{"n":172,"q":"What is true about the lecture series?","qvi":"Điều gì đúng về chuỗi bài giảng?","opts":["It highlights modern arts and crafts.","It schedules events on a monthly basis.","It is sponsored by local art galleries.","It is being offered for the third year."],"ans":"D","xp":"Câu hỏi chi tiết (True). Bằng chứng: \"our third annual lecture series\" (chuỗi bài giảng thường niên lần thứ ba) → năm nay là năm thứ ba tổ chức. → Chọn (D).\n(A) sai: các hiện vật là đồ cổ, về cư dân \"over 200 years ago\". (B) sai: tổ chức hằng tuần, \"on Tuesday evenings over the next six weeks\". (C) sai: Knowles Art Gallery chỉ là nơi làm việc của diễn giả, không phải nhà tài trợ.\n(A) Nó làm nổi bật nghệ thuật và thủ công hiện đại.\n(B) Nó tổ chức sự kiện hằng tháng.\n(C) Nó được các phòng trưng bày nghệ thuật địa phương tài trợ.\n(D) Nó được tổ chức năm thứ ba."},{"n":173,"q":"Who owns the objects that Ms. Hinds will speak about?","qvi":"Ai sở hữu các hiện vật mà bà Hinds sẽ nói đến?","opts":["The Hurnham Historical Society","The Knowles Art Gallery","The Hurnham Heritage Museum","The Fasseller Café"],"ans":"C","xp":"Câu hỏi chi tiết/suy luận. Bằng chứng: \"Each guest speaker will focus on objects from the museum's permanent collection.\" (the museum = Hurnham Heritage Museum) → các hiện vật bà Hinds dùng (bàn viết, rương, bàn gia dụng) thuộc bộ sưu tập thường trực của Bảo tàng Di sản Hurnham. → Chọn (C).\n(A) Hội Lịch sử Hurnham là nơi đăng tin (theo địa chỉ web). (B) chỉ là nơi bà Hinds làm việc. (D) quán cà phê cạnh bảo tàng.\n(A) Hội Lịch sử Hurnham\n(B) Phòng trưng bày Nghệ thuật Knowles\n(C) Bảo tàng Di sản Hurnham\n(D) Quán cà phê Fasseller"},{"n":174,"q":"What is suggested about the town of Hurnham?","qvi":"Điều gì được gợi ý về thị trấn Hurnham?","opts":["It was founded more than a hundred years ago.","It has an aging population.","It attracts many artists.","It was a center for furniture production."],"ans":"A","xp":"Câu hỏi suy luận. Bằng chứng: \"...what furniture can reveal to us about the lives of the first Hurnham residents over 200 years ago.\" → những cư dân đầu tiên của Hurnham sống cách đây hơn 200 năm → thị trấn được thành lập cách đây hơn một trăm năm. → Chọn (A).\n(D) sai: chỉ nói đồ nội thất cho biết về cuộc sống cư dân, không nói Hurnham là trung tâm sản xuất đồ nội thất. (B), (C) không có căn cứ.\n(A) Nó được thành lập cách đây hơn một trăm năm.\n(B) Nó có dân số đang già đi.\n(C) Nó thu hút nhiều nghệ sĩ.\n(D) Nó từng là trung tâm sản xuất đồ nội thất."},{"n":175,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"These include items such as furniture, needlework, diaries, musical instruments, and clothing.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Những hiện vật này bao gồm các món như đồ nội thất, đồ thêu may, nhật ký, nhạc cụ và quần áo.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu hỏi điền câu. Câu cần điền bắt đầu bằng \"These include items such as...\" → \"These\" phải chỉ một nhóm đồ vật vừa được nhắc đến ở câu trước. Câu trước vị trí [2] là: \"Each guest speaker will focus on objects from the museum's permanent collection.\" → \"These\" = \"objects from the museum's permanent collection\"; câu điền liệt kê ví dụ các hiện vật đó. Câu sau giới thiệu bài giảng đầu tiên về đồ nội thất, nối mạch tự nhiên. → Chọn (B).\n[1]: câu trước chưa nói đến đồ vật nào. [3], [4]: câu trước nói về diễn giả và việc miễn phí vé vào cửa, không hợp với \"These include items\"."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following table of contents and book review.","passages":["<h3><i>Leadership: Essays on Being a Great Leader</i></h3><p>Skymill Publishing<br>Joan Cristophe, Senior Editor</p><h4>Table of Contents</h4><table><tr><td>Introduction</td><td>ii</td></tr><tr><td>Beyond the Meeting Agenda: Leadership in Action<br>Francisca Conde</td><td>2</td></tr><tr><td>Leadership Lessons from Local Business<br>Xiaofeng Li</td><td>34</td></tr><tr><td>Think Small...Details Matter<br>Ron Blake</td><td>51</td></tr><tr><td>Low-Tech Managers in Business<br>T. Walker Prince</td><td>83</td></tr><tr><td>Future Leadership Models<br>Roderick Muller</td><td>119</td></tr></table>","<h4>Book Review: <i>Leadership: Essays on Being a Great Leader</i></h4><p>As a businessperson, I am glad there is a publisher whose sole focus is on business. Skymill Publishing's latest book is a great one for leaders in all industries. Joan Cristophe has sought out some of the world's best minds to write essays for this book that will provide readers with some unique perspectives. In her own introduction, she argues that there is a greater need than ever before for more effective leaders in business.</p><p>Cristophe expertly arranges the essays in this collection so that the voices of each author complement one another. The essay by Xiaofeng Li is the perfect example of this. It is strategically sandwiched between Francisca Conde's essay on leadership in action and Ron Blake's essay on focusing on the details. Roderick Muller's essay is the sole disappointment. Surprisingly little new information or insight is offered on its pages, and the writing style is rather flat. Besides that, the collection is excellent, and readers with an interest in leadership in many different situations will find useful nuggets of wisdom and vision within.</p>"],"vi":"Leadership: Essays on Being a Great Leader (Lãnh đạo: Những bài tiểu luận về việc trở thành một nhà lãnh đạo giỏi)\nNhà xuất bản Skymill\nJoan Cristophe, Biên tập viên cấp cao\n\nMỤC LỤC\nLời giới thiệu — trang ii\nVượt ra ngoài chương trình họp: Lãnh đạo trong hành động — Francisca Conde — trang 2\nBài học lãnh đạo từ doanh nghiệp địa phương — Xiaofeng Li — trang 34\nNghĩ nhỏ... Chi tiết mới quan trọng — Ron Blake — trang 51\nNhững nhà quản lý 'ít công nghệ' trong kinh doanh — T. Walker Prince — trang 83\nCác mô hình lãnh đạo tương lai — Roderick Muller — trang 119\n\nĐiểm sách: Leadership: Essays on Being a Great Leader\n\nLà một người làm kinh doanh, tôi rất vui vì có một nhà xuất bản chỉ tập trung duy nhất vào lĩnh vực kinh doanh. Cuốn sách mới nhất của Nhà xuất bản Skymill là một cuốn sách tuyệt vời cho các nhà lãnh đạo trong mọi ngành. Joan Cristophe đã tìm đến một số bộ óc xuất sắc nhất thế giới để viết các bài tiểu luận cho cuốn sách này, mang đến cho người đọc những góc nhìn độc đáo. Trong lời giới thiệu do chính mình viết, bà cho rằng hơn bao giờ hết, giới kinh doanh đang cần những nhà lãnh đạo hiệu quả hơn.\n\nCristophe sắp xếp các bài tiểu luận trong tuyển tập này một cách khéo léo để tiếng nói của từng tác giả bổ sung cho nhau. Bài tiểu luận của Xiaofeng Li là ví dụ hoàn hảo cho điều này. Nó được đặt một cách có chủ ý vào giữa bài của Francisca Conde về lãnh đạo trong hành động và bài của Ron Blake về việc chú trọng vào chi tiết. Bài tiểu luận của Roderick Muller là điểm đáng thất vọng duy nhất. Thật bất ngờ là các trang viết của nó đưa ra rất ít thông tin hay hiểu biết mới, và lối viết khá nhạt nhẽo. Ngoài điều đó ra, tuyển tập này rất xuất sắc, và những độc giả quan tâm đến việc lãnh đạo trong nhiều hoàn cảnh khác nhau sẽ tìm thấy trong đó những hạt ngọc hữu ích về sự khôn ngoan và tầm nhìn.","qs":[{"n":176,"q":"According to the table of contents, who is Ms. Cristophe?","qvi":"Theo mục lục, bà Cristophe là ai?","opts":["The owner of Skymill Publishing","A book editor","A local business person","An industry leader"],"ans":"B","xp":"Câu hỏi chi tiết. Trong mục lục ghi: \"Joan Cristophe, Senior Editor\" → bà là biên tập viên cấp cao của cuốn sách → (B) A book editor (một biên tập viên sách).\n(A) Mục lục không nói bà là chủ nhà xuất bản. (C), (D) không được nhắc đến.\n(A) Chủ sở hữu Nhà xuất bản Skymill\n(B) Một biên tập viên sách\n(C) Một người kinh doanh ở địa phương\n(D) Một nhà lãnh đạo trong ngành"},{"n":177,"q":"What is indicated about Skymill Publishing?","qvi":"Điều gì được nói đến về Nhà xuất bản Skymill?","opts":["It recently won an award.","It specializes in business books.","It is currently hiring.","It is releasing its first book."],"ans":"B","xp":"Câu hỏi chi tiết. Bài điểm sách viết: \"I am glad there is a publisher whose sole focus is on business. Skymill Publishing's latest book...\" → nhà xuất bản chỉ tập trung vào kinh doanh, tức là chuyên về sách kinh doanh. \"sole focus is on business\" = \"specializes in business books\" → (B).\n(D) sai vì \"latest book\" (cuốn mới nhất) cho thấy họ đã xuất bản sách trước đó. (A), (C) không được nhắc đến.\n(A) Họ vừa đoạt một giải thưởng.\n(B) Họ chuyên về sách kinh doanh.\n(C) Họ hiện đang tuyển dụng.\n(D) Họ đang phát hành cuốn sách đầu tiên."},{"n":178,"q":"According to the book review, what is the topic of the book introduction?","qvi":"Theo bài điểm sách, chủ đề của lời giới thiệu cuốn sách là gì?","opts":["The current need for strong business leadership","Learning from famous business leaders","Popular training programs in corporations","Process improvements that work"],"ans":"A","xp":"Câu hỏi chi tiết. \"In her own introduction, she argues that there is a greater need than ever before for more effective leaders in business.\" → lời giới thiệu nói về nhu cầu hiện nay đối với các nhà lãnh đạo kinh doanh giỏi. \"greater need than ever before\" ≈ \"current need\", \"more effective leaders\" ≈ \"strong leadership\" → (A).\n(A) Nhu cầu hiện nay về khả năng lãnh đạo kinh doanh vững mạnh\n(B) Học hỏi từ những nhà lãnh đạo kinh doanh nổi tiếng\n(C) Các chương trình đào tạo phổ biến trong các tập đoàn\n(D) Những cải tiến quy trình hiệu quả"},{"n":179,"q":"In the book review, the word \"sole\" in paragraph 2, line 5, is closest in meaning to","qvi":"Trong bài điểm sách, từ \"sole\" ở đoạn 2, dòng 5 gần nghĩa nhất với","opts":["underlying","entire","only","usual"],"ans":"C","xp":"Câu hỏi đồng nghĩa. \"Roderick Muller's essay is the sole disappointment.\" → bài của Muller là điểm thất vọng DUY NHẤT (câu sau còn nói \"Besides that, the collection is excellent\" — ngoài điều đó ra thì tuyển tập rất xuất sắc). \"sole\" = \"only\" (duy nhất) → (C).\n(A) underlying: tiềm ẩn, cơ bản\n(B) entire: toàn bộ\n(C) only: duy nhất\n(D) usual: thông thường"},{"n":180,"q":"On what page does the essay with notably minimal new information begin?","qvi":"Bài tiểu luận có rất ít thông tin mới bắt đầu ở trang nào?","opts":["Page 34","Page 51","Page 83","Page 119"],"ans":"D","xp":"Câu hỏi kết hợp 2 đoạn văn. Bài điểm sách: \"Roderick Muller's essay is the sole disappointment. Surprisingly little new information or insight is offered on its pages\" → bài của Roderick Muller có rất ít thông tin mới. Mục lục: \"Future Leadership Models — Roderick Muller — 119\" → bài này bắt đầu ở trang 119 → (D).\n(A) Trang 34 (bài của Xiaofeng Li)\n(B) Trang 51 (bài của Ron Blake)\n(C) Trang 83 (bài của T. Walker Prince)\n(D) Trang 119"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following policy and e-mail.","passages":["<h3>Tanyalog Industries Policy 4-02</h3><p>The cafeteria (3rd floor) is open to all employees and guests from 8:00 A.M. to 2:30 P.M. Food from the cafeteria may be eaten there or brought on trays to the following conference rooms: Chestnut Room (1st floor), Burnside Room (2nd floor), Smith Room (3rd floor), and Danville Room (4th floor).</p><p>Using the rooms at lunchtime does not require a reservation. However, please do not enter the room if it is already occupied by staff members for a business meeting. The room schedule is displayed on a digital panel by the door of each conference room.</p><p>All food items and trash must be removed from the conference room after use. Bins are located directly outside each of the conference rooms.</p><p>No food or drink is allowed in the Essex Room (3rd floor) or the Martinelli Room (4th floor).</p>","<div class=\"hdr\"><p><b>From:</b> Eugene Lasich</p><p><b>To:</b> All Expansion Committee Members</p><p><b>Subject:</b> Tanyalog Industries Expansion Meeting</p><p><b>Date:</b> September 10</p></div><p>Committee Members,</p><p>Please join me for the first meeting of the Expansion Committee on Monday, September 17. All attendees should arrive at the Martinelli Room at 10:00 A.M. Then, at 12:00 P.M., we will break for lunch and you can visit the cafeteria to receive a complimentary meal. Just show your visitor's badge at Window 4. All committee members should bring their trays to the conference room on the third floor right beside the cafeteria, where we will continue our meeting from 12:45 P.M. until 4:00 P.M.</p><p>Thank you. We look forward to your input at the meeting.</p><p>Eugene Lasich, Expansion Committee Chair<br>Tanyalog Industries</p>"],"vi":"Quy định 4-02 của Tanyalog Industries\n\nCăng tin (tầng 3) mở cửa cho tất cả nhân viên và khách từ 8:00 sáng đến 2:30 chiều. Đồ ăn từ căng tin có thể ăn tại chỗ hoặc mang bằng khay đến các phòng hội nghị sau: Phòng Chestnut (tầng 1), Phòng Burnside (tầng 2), Phòng Smith (tầng 3) và Phòng Danville (tầng 4).\n\nViệc sử dụng các phòng vào giờ ăn trưa không cần đặt trước. Tuy nhiên, vui lòng không vào phòng nếu phòng đang được nhân viên sử dụng cho một cuộc họp công việc. Lịch sử dụng phòng được hiển thị trên một bảng điện tử cạnh cửa mỗi phòng hội nghị.\n\nTất cả đồ ăn và rác phải được dọn khỏi phòng hội nghị sau khi sử dụng. Thùng rác được đặt ngay bên ngoài mỗi phòng hội nghị.\n\nKhông được phép mang đồ ăn hoặc đồ uống vào Phòng Essex (tầng 3) hoặc Phòng Martinelli (tầng 4).\n\nTừ: Eugene Lasich\nĐến: Tất cả thành viên Ủy ban Mở rộng\nTiêu đề: Cuộc họp Mở rộng của Tanyalog Industries\nNgày: 10 tháng 9\n\nCác thành viên Ủy ban thân mến,\n\nMời các bạn tham dự cuộc họp đầu tiên của Ủy ban Mở rộng cùng tôi vào thứ Hai, ngày 17 tháng 9. Tất cả người tham dự nên có mặt tại Phòng Martinelli lúc 10:00 sáng. Sau đó, lúc 12:00 trưa, chúng ta sẽ nghỉ ăn trưa và các bạn có thể đến căng tin để nhận một bữa ăn miễn phí. Chỉ cần xuất trình thẻ khách tại Quầy số 4. Tất cả thành viên ủy ban nên mang khay của mình đến phòng hội nghị ở tầng ba ngay cạnh căng tin, nơi chúng ta sẽ tiếp tục cuộc họp từ 12:45 chiều đến 4:00 chiều.\n\nXin cảm ơn. Chúng tôi mong nhận được ý kiến đóng góp của các bạn tại cuộc họp.\n\nEugene Lasich, Chủ tịch Ủy ban Mở rộng\nTanyalog Industries","qs":[{"n":181,"q":"According to the policy, what is shown on a digital panel?","qvi":"Theo quy định, cái gì được hiển thị trên bảng điện tử?","opts":["The agenda for an upcoming meeting","Rules for meeting room use","Details about a room's availability","Instructions for room devices"],"ans":"C","xp":"Câu hỏi chi tiết. \"The room schedule is displayed on a digital panel by the door of each conference room.\" → bảng điện tử hiển thị lịch sử dụng phòng, tức là cho biết phòng có trống hay không. \"room schedule\" ≈ \"details about a room's availability\" → (C).\n(A) Chương trình cho một cuộc họp sắp tới\n(B) Quy định sử dụng phòng họp\n(C) Thông tin về tình trạng trống/bận của phòng\n(D) Hướng dẫn sử dụng thiết bị trong phòng"},{"n":182,"q":"What are conference room users asked to do before leaving a room?","qvi":"Người sử dụng phòng hội nghị được yêu cầu làm gì trước khi rời phòng?","opts":["Sign the attendance sheet","Close the door","Turn off the lights","Clean up the space"],"ans":"D","xp":"Câu hỏi chi tiết. \"All food items and trash must be removed from the conference room after use. Bins are located directly outside each of the conference rooms.\" → phải dọn đồ ăn và rác sau khi dùng = dọn dẹp phòng → (D).\n(A) Ký vào danh sách điểm danh\n(B) Đóng cửa\n(C) Tắt đèn\n(D) Dọn dẹp chỗ đã dùng"},{"n":183,"q":"In the e-mail, the word \"complimentary\" in paragraph 1, line 4, is closest in meaning to","qvi":"Trong e-mail, từ \"complimentary\" ở đoạn 1, dòng 4 gần nghĩa nhất với","opts":["free","healthy","favorable","balanced"],"ans":"A","xp":"Câu hỏi đồng nghĩa. \"...you can visit the cafeteria to receive a complimentary meal. Just show your visitor's badge at Window 4.\" → chỉ cần xuất trình thẻ là nhận được bữa ăn, không phải trả tiền. \"complimentary\" ở đây = \"free\" (miễn phí) → (A).\nLưu ý: \"complimentary\" còn có nghĩa \"khen ngợi\", nhưng đi với \"meal\" thì nghĩa là miễn phí.\n(A) free: miễn phí\n(B) healthy: tốt cho sức khỏe\n(C) favorable: thuận lợi, tán thành\n(D) balanced: cân bằng"},{"n":184,"q":"What should committee members do at Window 4?","qvi":"Các thành viên ủy ban nên làm gì ở Quầy số 4?","opts":["Collect meeting materials","Show proof of identification","Submit their food orders","Return their used trays"],"ans":"B","xp":"Câu hỏi chi tiết. \"Just show your visitor's badge at Window 4.\" → xuất trình thẻ khách tại Quầy 4. \"visitor's badge\" là một loại giấy tờ nhận dạng → \"show proof of identification\" (xuất trình giấy tờ nhận dạng) → (B).\n(A) Nhận tài liệu cuộc họp\n(B) Xuất trình giấy tờ nhận dạng\n(C) Gửi yêu cầu gọi món\n(D) Trả lại khay đã dùng"},{"n":185,"q":"Where will committee members most likely be at 1:00 P.M.?","qvi":"Lúc 1:00 chiều, các thành viên ủy ban nhiều khả năng sẽ ở đâu?","opts":["In the cafeteria","In the Smith Room","In the Essex Room","In the Martinelli Room"],"ans":"B","xp":"Câu hỏi kết hợp 2 đoạn văn. E-mail: \"All committee members should bring their trays to the conference room on the third floor right beside the cafeteria, where we will continue our meeting from 12:45 P.M. until 4:00 P.M.\" → lúc 1:00 chiều họ đang họp ở phòng hội nghị tầng 3, có mang khay đồ ăn vào. Quy định: ở tầng 3 có Smith Room (được mang đồ ăn vào) và Essex Room (\"No food or drink is allowed in the Essex Room (3rd floor)\"). Vì họ mang khay đồ ăn nên phòng đó phải là Smith Room → (B).\n(A) sai vì từ 12:45 họ đã rời căng tin. (C) Essex cấm đồ ăn. (D) Martinelli ở tầng 4 và cũng cấm đồ ăn; họ chỉ họp ở đó lúc 10:00 sáng.\n(A) Trong căng tin\n(B) Trong Phòng Smith\n(C) Trong Phòng Essex\n(D) Trong Phòng Martinelli"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following article and e-mails.","passages":["<h3>Hiking Permits to Be Required for Upton Parks</h3><p>UPTON (January 8)—Starting on May 25, hikers will be required to obtain a permit for each day they hike on certain trails in Upton parks. The designated trails include some of the most popular hiking spots in the area. The permits are free of charge and require only that hikers register online at www.uptonparks.org or at any Upton Parks Department office. Upon registering, hikers will receive a permit that they can print out or display on a mobile device.</p><p>The move is part of an effort to reduce foot traffic on the most used trails, but some hikers are concerned. \"I might not be able to get a permit for my favorite trails if none are left when I want to go,\" says Regina Faroni, an Upton parks hiker. \"In addition, I often check the weather in the morning and then decide if it's a good day to hike,\" she says. Having to apply for a permit could prevent her from taking spontaneous hikes. \"On the other hand, it would reduce the number of hikers on certain trails,\" Faroni admits.</p><p><i>—EJ Harjo, Upton Digest</i></p>","<div class=\"hdr\"><p><b>From:</b> Arlo Gomes &lt;arlog@uptonhikingclub.org&gt;</p><p><b>To:</b> Upton Parks Department &lt;info@uptonparks.org&gt;</p><p><b>Subject:</b> Hiking permits</p><p><b>Date:</b> January 22</p></div><p>To Whom It May Concern,</p><p>I read in the <i>Upton Digest</i> that hikers soon will be required to register for permits to hike on certain trails. As the organizer of the Upton Hiking Club, I would like more details on how this will affect our club. For example, is there a list of hiking trails that will require permits? I checked your Web site and could not find one.</p><p>Is it also the case that the number of permits issued will vary from trail to trail? About seventeen to twenty club members participate in our group hikes. I'm concerned that we may not get enough permits to hike together. Are there special considerations for large groups?</p><p>Finally, I am concerned that the permit requirement will not allow our club members to get together for a hike on the spur of the moment. We often will take an unplanned hike if we find that several members have a free day.</p><p>I hope you are able to respond soon, as we are already planning our spring and summer hikes.</p><p>Regards,</p><p>Arlo Gomes<br>Organizer, Upton Hiking Club</p>","<div class=\"hdr\"><p><b>From:</b> Upton Parks Department &lt;info@uptonparks.org&gt;</p><p><b>To:</b> Arlo Gomes &lt;arlog@uptonhikingclub.org&gt;</p><p><b>Subject:</b> RE: Hiking permits</p><p><b>Date:</b> January 23</p><p><b>Attachment:</b> Permit_Information_DRAFT</p></div><p>Hello, Mr. Gomes,</p><p>Thank you for your e-mail. I apologize that our Web site has not yet been updated with the information you were searching for and that the article in the <i>Upton Digest</i> was not clear. I have attached a proposed list of the twelve trails that will require permits and the number of permits that will be issued per day for each trail. The list will be finalized next month.</p><p>Permits can be reserved up to two weeks in advance, and the number of permits available for most trails is substantially higher than the number of Upton Hiking Club members who join your group hikes. Same-day permits can be obtained.</p><p>If you have not already done so, you can sign up on our Web site for our weekly newsletter. Doing so will ensure that you get advance notice of any updates to our policies.</p><p>Jenny Grieb, Public Relations, Upton Parks Department</p>"],"vi":"Sẽ yêu cầu giấy phép đi bộ đường dài tại các công viên ở Upton\n\nUPTON (8 tháng 1) — Bắt đầu từ ngày 25 tháng 5, người đi bộ đường dài sẽ phải xin giấy phép cho mỗi ngày họ đi bộ trên một số con đường mòn nhất định trong các công viên ở Upton. Những con đường được chỉ định bao gồm một số địa điểm đi bộ đường dài nổi tiếng nhất trong khu vực. Giấy phép được cấp miễn phí và chỉ yêu cầu người đi bộ đăng ký trực tuyến tại www.uptonparks.org hoặc tại bất kỳ văn phòng nào của Sở Công viên Upton. Sau khi đăng ký, người đi bộ sẽ nhận được giấy phép có thể in ra hoặc hiển thị trên thiết bị di động.\n\nĐộng thái này là một phần trong nỗ lực giảm lượng người đi bộ trên những con đường mòn được sử dụng nhiều nhất, nhưng một số người đi bộ tỏ ra lo ngại. \"Có thể tôi sẽ không xin được giấy phép cho những con đường yêu thích nếu chúng đã hết khi tôi muốn đi,\" Regina Faroni, một người hay đi bộ ở các công viên Upton, cho biết. \"Ngoài ra, tôi thường xem thời tiết vào buổi sáng rồi mới quyết định hôm đó có nên đi bộ hay không,\" cô nói. Việc phải xin giấy phép có thể khiến cô không thể đi bộ một cách ngẫu hứng. \"Mặt khác, nó sẽ giúp giảm số người đi bộ trên một số con đường mòn,\" Faroni thừa nhận.\n— EJ Harjo, Upton Digest\n\nTừ: Arlo Gomes <arlog@uptonhikingclub.org>\nĐến: Sở Công viên Upton <info@uptonparks.org>\nTiêu đề: Giấy phép đi bộ đường dài\nNgày: 22 tháng 1\n\nKính gửi Quý cơ quan,\n\nTôi đọc trên tờ Upton Digest rằng sắp tới người đi bộ đường dài sẽ phải đăng ký giấy phép để đi trên một số con đường mòn nhất định. Với tư cách là người tổ chức của Câu lạc bộ Đi bộ Đường dài Upton, tôi muốn biết thêm chi tiết về việc điều này sẽ ảnh hưởng đến câu lạc bộ của chúng tôi như thế nào. Ví dụ, có danh sách những con đường mòn cần giấy phép không? Tôi đã xem trang web của quý vị nhưng không tìm thấy.\n\nCó phải số lượng giấy phép được cấp cũng sẽ khác nhau tùy từng con đường không? Khoảng mười bảy đến hai mươi thành viên câu lạc bộ tham gia các chuyến đi bộ theo nhóm của chúng tôi. Tôi lo rằng chúng tôi có thể không xin đủ giấy phép để đi cùng nhau. Có sự ưu tiên đặc biệt nào cho các nhóm đông người không?\n\nCuối cùng, tôi lo rằng yêu cầu về giấy phép sẽ khiến các thành viên câu lạc bộ không thể tụ tập đi bộ một cách ngẫu hứng. Chúng tôi thường tổ chức một chuyến đi không lên kế hoạch trước nếu thấy vài thành viên có ngày rảnh.\n\nTôi mong quý vị sớm phản hồi, vì chúng tôi đang lên kế hoạch cho các chuyến đi mùa xuân và mùa hè.\n\nTrân trọng,\n\nArlo Gomes\nNgười tổ chức, Câu lạc bộ Đi bộ Đường dài Upton\n\nTừ: Sở Công viên Upton <info@uptonparks.org>\nĐến: Arlo Gomes <arlog@uptonhikingclub.org>\nTiêu đề: RE: Giấy phép đi bộ đường dài\nNgày: 23 tháng 1\nTệp đính kèm: Permit_Information_DRAFT (Thông tin giấy phép_BẢN NHÁP)\n\nChào ông Gomes,\n\nCảm ơn ông đã gửi e-mail. Tôi xin lỗi vì trang web của chúng tôi chưa được cập nhật thông tin ông đang tìm và vì bài báo trên Upton Digest chưa rõ ràng. Tôi đã đính kèm danh sách đề xuất gồm mười hai con đường mòn sẽ cần giấy phép và số lượng giấy phép sẽ được cấp mỗi ngày cho từng con đường. Danh sách sẽ được chốt vào tháng sau.\n\nGiấy phép có thể được đặt trước tối đa hai tuần, và số giấy phép có sẵn cho hầu hết các con đường cao hơn đáng kể so với số thành viên Câu lạc bộ Đi bộ Đường dài Upton tham gia các chuyến đi nhóm của ông. Có thể xin giấy phép trong ngày.\n\nNếu ông chưa đăng ký, ông có thể đăng ký nhận bản tin hằng tuần của chúng tôi trên trang web. Việc này sẽ đảm bảo ông được thông báo trước về mọi thay đổi trong chính sách của chúng tôi.\n\nJenny Grieb, Bộ phận Quan hệ Công chúng, Sở Công viên Upton","qs":[{"n":186,"q":"According to the article, why will permits be required for some trails?","qvi":"Theo bài báo, tại sao một số con đường mòn sẽ yêu cầu giấy phép?","opts":["To raise money to maintain the parks","To encourage visitors to explore park activities other than hiking","To ensure the trails are not too crowded","To determine which trails are most frequently used"],"ans":"C","xp":"Câu hỏi chi tiết. \"The move is part of an effort to reduce foot traffic on the most used trails\" → mục đích là giảm lượng người đi trên những con đường đông nhất, tức là để đường mòn không quá đông → (C).\n(A) sai vì giấy phép \"free of charge\" (miễn phí). (D) sai vì những con đường đông nhất đã được biết sẵn (\"the most used trails\").\n(A) Để gây quỹ bảo trì công viên\n(B) Để khuyến khích du khách khám phá các hoạt động khác ngoài đi bộ đường dài\n(C) Để đảm bảo các con đường mòn không quá đông đúc\n(D) Để xác định con đường mòn nào được sử dụng nhiều nhất"},{"n":187,"q":"Why did Mr. Gomes contact the Upton Parks Department?","qvi":"Tại sao ông Gomes liên hệ với Sở Công viên Upton?","opts":["To request information","To obtain trail maps","To apply for a group permit","To discuss membership options"],"ans":"A","xp":"Câu hỏi mục đích. Trong e-mail thứ nhất: \"I would like more details on how this will affect our club. For example, is there a list of hiking trails that will require permits?\" và ông đặt thêm nhiều câu hỏi khác → mục đích là xin thêm thông tin → (A).\n(B) Ông hỏi danh sách đường mòn, không phải bản đồ. (C) Ông chỉ hỏi có ưu tiên cho nhóm lớn không, chưa nộp đơn xin giấy phép.\n(A) Để yêu cầu thông tin\n(B) Để xin bản đồ đường mòn\n(C) Để xin giấy phép cho nhóm\n(D) Để thảo luận các lựa chọn hội viên"},{"n":188,"q":"What concern does Mr. Gomes share with the Upton Digest reader?","qvi":"Ông Gomes có chung mối lo ngại nào với người được tờ Upton Digest phỏng vấn?","opts":["Too many trails will require permits.","Last-minute permits may not be available.","It is expensive to get a hiking permit.","Overnight permits will be for groups only."],"ans":"B","xp":"Câu hỏi kết hợp 2 đoạn văn. Bài báo: bà Faroni lo rằng \"Having to apply for a permit could prevent her from taking spontaneous hikes\" (không thể đi bộ ngẫu hứng). E-mail của ông Gomes: \"I am concerned that the permit requirement will not allow our club members to get together for a hike on the spur of the moment.\" (không thể đi bộ ngay lập tức, không kế hoạch trước). Cả hai cùng lo không xin được giấy phép vào phút chót → (B) Last-minute permits may not be available.\n(C) sai vì giấy phép miễn phí. (A), (D) không được nhắc đến.\n(A) Quá nhiều con đường mòn sẽ cần giấy phép.\n(B) Có thể không xin được giấy phép vào phút chót.\n(C) Xin giấy phép đi bộ rất tốn kém.\n(D) Giấy phép qua đêm sẽ chỉ dành cho các nhóm."},{"n":189,"q":"How many permits will likely be offered for most trails?","qvi":"Có khả năng bao nhiêu giấy phép sẽ được cấp cho hầu hết các con đường mòn?","opts":["Fewer than twelve","Twelve to seventeen","Eighteen to twenty","More than twenty"],"ans":"D","xp":"Câu hỏi kết hợp 2 đoạn văn. E-mail thứ hai: \"the number of permits available for most trails is substantially higher than the number of Upton Hiking Club members who join your group hikes\" (cao hơn đáng kể so với số thành viên đi nhóm). E-mail thứ nhất: \"About seventeen to twenty club members participate in our group hikes.\" → số giấy phép cho hầu hết các con đường sẽ nhiều hơn hai mươi → (D).\nLưu ý: con số \"twelve\" trong e-mail là số con đường mòn, không phải số giấy phép.\n(A) Ít hơn mười hai\n(B) Từ mười hai đến mười bảy\n(C) Từ mười tám đến hai mươi\n(D) Nhiều hơn hai mươi"},{"n":190,"q":"According to the second e-mail, what does the newsletter provide?","qvi":"Theo e-mail thứ hai, bản tin cung cấp điều gì?","opts":["Articles written by the Upton Hiking Club","Details about trail conditions","Information about policy changes","Access to additional permits"],"ans":"C","xp":"Câu hỏi chi tiết. \"...you can sign up on our Web site for our weekly newsletter. Doing so will ensure that you get advance notice of any updates to our policies.\" → bản tin thông báo trước về các thay đổi chính sách. \"updates to our policies\" = \"policy changes\" → (C).\n(A) Các bài viết do Câu lạc bộ Đi bộ Đường dài Upton viết\n(B) Chi tiết về tình trạng đường mòn\n(C) Thông tin về những thay đổi chính sách\n(D) Quyền tiếp cận thêm giấy phép"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following reservation and e-mails.","passages":["<h3>Your Move Vehicle Rental Company</h3><table><tr><td>Reservation Number:</td><td>15288242</td></tr><tr><td>Pickup Location:</td><td>2833 Centennial Rd., Muncie, IN 47303</td></tr><tr><td>Date and Time:</td><td>October 31, 10:00 A.M.</td></tr><tr><td>Drop-off Location:</td><td>Same as pickup</td></tr><tr><td>Date and Time:</td><td>October 31, 6:30 P.M.</td></tr><tr><td>Vehicle Description:</td><td>5-meter moving van</td></tr></table><p>If you need to change your reservation, you can do so via your online account until three days before your scheduled pickup. After that point, contact customer support at reservations@yourmove.com. Please include your reservation number in the e-mail subject.</p>","<div class=\"hdr\"><p><b>To:</b> reservations@yourmove.com</p><p><b>From:</b> selina_os@chestnutmail.com</p><p><b>Date:</b> October 29</p><p><b>Subject:</b> Reservation 15288242</p></div><p>Hello,</p><p>I reserved a moving van online and was given an estimated price of $150. However, I mistakenly listed the same location for both pickup and drop-off. I'd like to know if there is a drop-off location closer to my destination in Cumberland. If so, can you please help me update the reservation?</p><p>Sincerely,</p><p>Selina Osman</p>","<div class=\"hdr\"><p><b>To:</b> selina_os@chestnutmail.com</p><p><b>From:</b> reservations@yourmove.com</p><p><b>Date:</b> October 30</p><p><b>Subject:</b> RE: Reservation 15288242</p></div><p>Dear Ms. Osman,</p><p>We have a rental office just outside Indianapolis, about a ten-minute drive from Cumberland. If that is the drop-off location, you would have about 90 kilometers of driving from the starting point in Muncie. Based on this, we have updated your price estimate as follows.</p><p>Rental: 5-meter moving van for 1 day = $39.99</p><p>Rental: wheeled furniture cart = $6.99</p><p>Rental: furniture pads (set of 12) = $9.99</p><p>Distance: $1.05 per kilometer = $94.50 (90 kilometers estimated)</p><p>Vehicle damage insurance = $19.99</p><p>Total = $171.46</p><p>Please note that this total does not include taxes. The final price may vary based on the actual distance driven and will be calculated once the vehicle is returned to the drop-off location. Until that time, your credit card on file will be charged for the rental equipment only.</p><p>Sincerely,</p><p>Alistair Muhn<br>Your Move Vehicle Rental Company</p>"],"vi":"Công ty Cho thuê Xe Your Move\n\nSố đặt chỗ: 15288242\nĐịa điểm nhận xe: 2833 Centennial Rd., Muncie, IN 47303\nNgày và giờ: 31 tháng 10, 10:00 sáng\nĐịa điểm trả xe: Giống địa điểm nhận xe\nNgày và giờ: 31 tháng 10, 6:30 chiều\nMô tả xe: Xe tải chở đồ chuyển nhà dài 5 mét\n\nNếu bạn cần thay đổi đặt chỗ, bạn có thể thực hiện qua tài khoản trực tuyến cho đến ba ngày trước thời gian nhận xe đã hẹn. Sau thời điểm đó, hãy liên hệ bộ phận hỗ trợ khách hàng tại reservations@yourmove.com. Vui lòng ghi số đặt chỗ của bạn vào tiêu đề e-mail.\n\nĐến: reservations@yourmove.com\nTừ: selina_os@chestnutmail.com\nNgày: 29 tháng 10\nTiêu đề: Đặt chỗ 15288242\n\nXin chào,\n\nTôi đã đặt một xe tải chuyển nhà trực tuyến và được báo giá ước tính là 150 đô la. Tuy nhiên, tôi đã điền nhầm cùng một địa điểm cho cả nơi nhận xe và trả xe. Tôi muốn biết có địa điểm trả xe nào gần điểm đến của tôi ở Cumberland hơn không. Nếu có, bạn có thể giúp tôi cập nhật đặt chỗ được không?\n\nTrân trọng,\n\nSelina Osman\n\nĐến: selina_os@chestnutmail.com\nTừ: reservations@yourmove.com\nNgày: 30 tháng 10\nTiêu đề: RE: Đặt chỗ 15288242\n\nKính gửi cô Osman,\n\nChúng tôi có một văn phòng cho thuê ngay bên ngoài Indianapolis, cách Cumberland khoảng mười phút lái xe. Nếu đó là địa điểm trả xe, cô sẽ phải lái khoảng 90 ki-lô-mét từ điểm xuất phát ở Muncie. Dựa trên điều này, chúng tôi đã cập nhật báo giá ước tính của cô như sau.\n\nThuê: xe tải chuyển nhà 5 mét trong 1 ngày = 39,99 đô la\nThuê: xe đẩy đồ nội thất có bánh = 6,99 đô la\nThuê: tấm đệm lót đồ nội thất (bộ 12 tấm) = 9,99 đô la\nQuãng đường: 1,05 đô la mỗi ki-lô-mét = 94,50 đô la (ước tính 90 ki-lô-mét)\nBảo hiểm hư hại xe = 19,99 đô la\nTổng cộng = 171,46 đô la\n\nXin lưu ý rằng tổng số tiền này chưa bao gồm thuế. Giá cuối cùng có thể thay đổi tùy theo quãng đường thực tế đã lái và sẽ được tính khi xe được trả lại tại địa điểm trả xe. Cho đến lúc đó, thẻ tín dụng đã lưu của cô sẽ chỉ bị trừ tiền cho phần thiết bị thuê.\n\nTrân trọng,\n\nAlistair Muhn\nCông ty Cho thuê Xe Your Move","qs":[{"n":191,"q":"When will a vehicle be rented?","qvi":"Khi nào chiếc xe sẽ được thuê?","opts":["On October 28","On October 29","On October 30","On October 31"],"ans":"D","xp":"Câu hỏi chi tiết. Phiếu đặt chỗ: \"Pickup Location: ... Date and Time: October 31, 10:00 A.M.\" và trả xe \"October 31, 6:30 P.M.\" → xe được thuê vào ngày 31 tháng 10 → (D).\n(B) 29/10 là ngày cô Osman gửi e-mail, (C) 30/10 là ngày công ty trả lời.\n(A) Vào ngày 28 tháng 10\n(B) Vào ngày 29 tháng 10\n(C) Vào ngày 30 tháng 10\n(D) Vào ngày 31 tháng 10"},{"n":192,"q":"What can be concluded about Ms. Osman?","qvi":"Có thể kết luận điều gì về cô Osman?","opts":["She has used the same rental company previously.","She has been planning a move for a long time.","She did not read the rental agreement carefully.","She was unable to change her reservation online."],"ans":"D","xp":"Câu hỏi suy luận (kết hợp 2 đoạn văn). Phiếu đặt chỗ: \"you can do so via your online account until three days before your scheduled pickup. After that point, contact customer support at reservations@yourmove.com.\" Ngày nhận xe là 31/10, nên hạn đổi trực tuyến là trước 28/10. Cô Osman viết e-mail vào ngày 29/10 (chỉ còn 2 ngày) → đã quá hạn nên không thể đổi trực tuyến, phải gửi e-mail cho bộ phận hỗ trợ → (D).\n(C) Cô chỉ điền nhầm địa điểm, không có thông tin cô không đọc kỹ hợp đồng. (A), (B) không được nhắc đến.\n(A) Cô ấy đã từng dùng công ty cho thuê này trước đây.\n(B) Cô ấy đã lên kế hoạch chuyển nhà từ lâu.\n(C) Cô ấy đã không đọc kỹ hợp đồng thuê.\n(D) Cô ấy không thể thay đổi đặt chỗ trực tuyến."},{"n":193,"q":"Who is Mr. Muhn?","qvi":"Ông Muhn là ai?","opts":["A furniture mover","A vehicle insurance agent","A reservation agent","A storage facility manager"],"ans":"C","xp":"Câu hỏi suy luận. E-mail thứ hai được gửi từ \"reservations@yourmove.com\" (địa chỉ bộ phận đặt chỗ), ký tên \"Alistair Muhn, Your Move Vehicle Rental Company\", và ông là người cập nhật đặt chỗ, báo giá mới cho cô Osman → ông là nhân viên phụ trách đặt chỗ → (C).\n(B) sai: bảo hiểm chỉ là một mục trong bảng giá.\n(A) Một người chuyển đồ nội thất\n(B) Một đại lý bảo hiểm xe\n(C) Một nhân viên đặt chỗ\n(D) Một quản lý kho chứa đồ"},{"n":194,"q":"What is indicated about a furniture cart?","qvi":"Điều gì được nói đến về xe đẩy đồ nội thất?","opts":["It costs $6.99 per day to rent.","It does not have to be returned.","It folds up for easy transport.","It is part of a set."],"ans":"A","xp":"Câu hỏi chi tiết. E-mail thứ hai: \"Rental: 5-meter moving van for 1 day = $39.99\" và \"Rental: wheeled furniture cart = $6.99\" → thời gian thuê là 1 ngày, giá thuê xe đẩy là 6,99 đô la → thuê xe đẩy tốn 6,99 đô la cho một ngày → (A).\n(B) sai vì đây là đồ \"Rental\" (đồ thuê) nên phải trả lại. (D) sai: \"set of 12\" là nói về furniture pads (tấm đệm), không phải xe đẩy. (C) không được nhắc đến.\n(A) Thuê nó tốn 6,99 đô la mỗi ngày.\n(B) Không cần phải trả lại nó.\n(C) Nó gập lại được để dễ vận chuyển.\n(D) Nó là một phần của một bộ."},{"n":195,"q":"What is true about the new cost estimate?","qvi":"Điều gì đúng về báo giá ước tính mới?","opts":["It is higher than the original estimate.","It must be paid in full immediately.","It includes the cost of fuel.","It expires in three days."],"ans":"A","xp":"Câu hỏi kết hợp 2 đoạn văn. E-mail của cô Osman: \"was given an estimated price of $150\" (báo giá ban đầu 150 đô la). E-mail trả lời: \"Total = $171.46\" → báo giá mới cao hơn báo giá ban đầu → (A).\n(B) sai vì \"Until that time, your credit card on file will be charged for the rental equipment only\" (hiện chỉ trừ tiền thiết bị thuê, giá cuối tính khi trả xe). (C) không có mục tiền nhiên liệu. (D) không được nhắc đến; \"three days\" là hạn đổi đặt chỗ trực tuyến.\n(A) Nó cao hơn báo giá ban đầu.\n(B) Phải thanh toán toàn bộ ngay lập tức.\n(C) Nó bao gồm chi phí nhiên liệu.\n(D) Nó hết hạn sau ba ngày."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mails and Web page.","passages":["<div class=\"hdr\"><p><b>To:</b> Soon-Yee Kim</p><p><b>From:</b> Frank Zubiri</p><p><b>Date:</b> February 12</p><p><b>Subject:</b> Welcome</p></div><p>Dear Ms. Kim,</p><p>Welcome to Jacobi Technologies' sales team! Your first day is Monday, February 28. Please arrive at the Green Building, 1 Jacobi Circle, Naperville, at 9 A.M. Your team supervisor, Sophia Holland, will lead you through your first day. Here is an outline of what to expect.</p><p>1. Sign your employment contract and receive an ID badge.</p><p>2. Visit your assigned cubicle on the fourth floor of the Yellow Building.</p><p>3. Attend a luncheon with members of your team in the Yellow Building conference room.</p><p>4. Join other new hires for a guided tour of the campus. Look for an e-mail about this within a few days.</p><p>Best regards,</p><p>Frank Zubiri<br>Senior Director, Human Resources</p>","<div class=\"hdr\"><p><b>To:</b> New Hires Distribution List</p><p><b>From:</b> Toru Hada</p><p><b>Date:</b> February 15</p><p><b>Subject:</b> Campus Tour Dates</p></div><p>The next tour dates are February 21 and 28 and March 7 and 14. To sign up, simply reply to this e-mail with your full name and the date corresponding to your start day. Tours begin at 3:00 P.M. and last about an hour. Please meet me in the Blue Building lobby a few minutes before 3:00 P.M. Note that the Blue Building is on Jacobi Circle between the Green and Yellow Buildings. The tour will include stops at the labs, our sustainable power plant, and all employee amenities.</p><p>Should you have any questions about your start day, the tour, or any of the employee onboarding materials, please do not hesitate to contact me.</p>","<p>https://www.jacobitechnologies.com/about</p><p>Jacobi Technologies develops, manufactures, and sells advanced microprocessors that power smart TVs, laptop computers, and other electronic devices. The company has more than 8,000 employees in Naperville, Illinois, and another 4,000 in Providence, Rhode Island.</p><p>Jacobi Technologies acquired its 900-acre Naperville property in 1950. Since then, the company has invested more than $3 billion in constructing ten Earth-friendly buildings and a sustainable infrastructure, including a waste-to-energy power plant. In addition to state-of-the-art research labs and production facilities, the campus boasts special amenities for workers, including two cafés, a gym, outdoor basketball and tennis courts, and a childcare center.</p>"],"vi":"Đến: Soon-Yee Kim\nTừ: Frank Zubiri\nNgày: 12 tháng 2\nTiêu đề: Chào mừng\n\nKính gửi cô Kim,\n\nChào mừng cô đến với đội ngũ bán hàng của Jacobi Technologies! Ngày làm việc đầu tiên của cô là thứ Hai, ngày 28 tháng 2. Vui lòng có mặt tại Tòa nhà Xanh lá (Green Building), số 1 Jacobi Circle, Naperville, lúc 9 giờ sáng. Trưởng nhóm của cô, Sophia Holland, sẽ hướng dẫn cô trong ngày đầu tiên. Dưới đây là sơ lược những việc cô sẽ làm.\n\n1. Ký hợp đồng lao động và nhận thẻ nhân viên.\n\n2. Đến xem khu làm việc (cubicle) được phân cho cô ở tầng bốn của Tòa nhà Vàng (Yellow Building).\n\n3. Dự bữa trưa cùng các thành viên trong nhóm tại phòng hội nghị của Tòa nhà Vàng.\n\n4. Cùng các nhân viên mới khác tham gia chuyến tham quan khuôn viên có hướng dẫn. Hãy chú ý một e-mail về việc này trong vài ngày tới.\n\nTrân trọng,\n\nFrank Zubiri\nGiám đốc cấp cao, Phòng Nhân sự\n\nĐến: Danh sách gửi thư Nhân viên mới\nTừ: Toru Hada\nNgày: 15 tháng 2\nTiêu đề: Ngày tham quan khuôn viên\n\nCác ngày tham quan sắp tới là 21 và 28 tháng 2, 7 và 14 tháng 3. Để đăng ký, bạn chỉ cần trả lời e-mail này kèm họ tên đầy đủ và ngày trùng với ngày bắt đầu làm việc của bạn. Các chuyến tham quan bắt đầu lúc 3:00 chiều và kéo dài khoảng một tiếng. Vui lòng gặp tôi tại sảnh Tòa nhà Xanh dương (Blue Building) vài phút trước 3:00 chiều. Lưu ý rằng Tòa nhà Xanh dương nằm trên đường Jacobi Circle, giữa Tòa nhà Xanh lá và Tòa nhà Vàng. Chuyến tham quan sẽ dừng ở các phòng thí nghiệm, nhà máy điện bền vững của chúng tôi và tất cả các tiện ích dành cho nhân viên.\n\nNếu bạn có bất kỳ câu hỏi nào về ngày bắt đầu làm việc, chuyến tham quan hoặc bất kỳ tài liệu hội nhập nhân viên mới nào, đừng ngần ngại liên hệ với tôi.\n\nhttps://www.jacobitechnologies.com/about\n\nJacobi Technologies phát triển, sản xuất và bán các bộ vi xử lý tiên tiến cung cấp năng lực cho TV thông minh, máy tính xách tay và các thiết bị điện tử khác. Công ty có hơn 8.000 nhân viên ở Naperville, Illinois, và thêm 4.000 nhân viên ở Providence, Rhode Island.\n\nJacobi Technologies mua khu đất rộng 900 mẫu Anh ở Naperville vào năm 1950. Kể từ đó, công ty đã đầu tư hơn 3 tỷ đô la để xây dựng mười tòa nhà thân thiện với môi trường và một hệ thống cơ sở hạ tầng bền vững, bao gồm một nhà máy điện chuyển hóa rác thải thành năng lượng. Ngoài các phòng thí nghiệm nghiên cứu và cơ sở sản xuất hiện đại bậc nhất, khuôn viên còn có những tiện ích đặc biệt cho nhân viên, gồm hai quán cà phê, một phòng tập thể dục, sân bóng rổ và sân quần vợt ngoài trời, và một trung tâm giữ trẻ.","qs":[{"n":196,"q":"According to the first e-mail, what is one thing that Ms. Kim will do on her first day at work?","qvi":"Theo e-mail thứ nhất, một việc cô Kim sẽ làm trong ngày làm việc đầu tiên là gì?","opts":["Learn to use some company software","Watch a video for new hires","Eat a meal with her team","Receive a laptop computer"],"ans":"C","xp":"Câu hỏi chi tiết. Mục 3 trong e-mail: \"Attend a luncheon with members of your team in the Yellow Building conference room.\" → dự bữa trưa (luncheon) với nhóm = ăn một bữa với nhóm → (C).\n(D) sai: cô nhận \"an ID badge\" (thẻ nhân viên), không phải máy tính xách tay. (A), (B) không được nhắc đến.\n(A) Học cách sử dụng một phần mềm của công ty\n(B) Xem một video dành cho nhân viên mới\n(C) Ăn một bữa với nhóm của cô ấy\n(D) Nhận một máy tính xách tay"},{"n":197,"q":"Who most likely is Mr. Hada?","qvi":"Ông Hada nhiều khả năng là ai?","opts":["A human resources staff member","A sales team leader","A technology expert","A café worker"],"ans":"A","xp":"Câu hỏi suy luận. Ông Hada gửi e-mail cho \"New Hires Distribution List\" (danh sách nhân viên mới), tổ chức chuyến tham quan cho nhân viên mới và viết: \"Should you have any questions about your start day, the tour, or any of the employee onboarding materials, please do not hesitate to contact me.\" → ông phụ trách việc hội nhập nhân viên mới (onboarding), đây là công việc của phòng nhân sự. E-mail thứ nhất cũng đến từ Giám đốc Nhân sự và nói sẽ có e-mail về chuyến tham quan → (A).\n(B) Trưởng nhóm bán hàng là Sophia Holland.\n(A) Một nhân viên phòng nhân sự\n(B) Một trưởng nhóm bán hàng\n(C) Một chuyên gia công nghệ\n(D) Một nhân viên quán cà phê"},{"n":198,"q":"Where will Ms. Kim most likely be at 3 P.M. on February 28?","qvi":"Lúc 3 giờ chiều ngày 28 tháng 2, cô Kim nhiều khả năng sẽ ở đâu?","opts":["In her cubicle in the Yellow Building","In the lobby of the Blue Building","In the Yellow Building conference room","In Ms. Holland's office"],"ans":"B","xp":"Câu hỏi kết hợp 2 đoạn văn. E-mail thứ nhất: ngày đầu tiên của cô Kim là \"Monday, February 28\", và một việc trong ngày đầu là \"Join other new hires for a guided tour of the campus\". E-mail thứ hai: có chuyến tham quan ngày 28/2 (\"February 21 and 28...\"), đăng ký theo \"the date corresponding to your start day\"; \"Tours begin at 3:00 P.M.... Please meet me in the Blue Building lobby a few minutes before 3:00 P.M.\" → lúc 3 giờ chiều ngày 28/2 cô Kim sẽ ở sảnh Tòa nhà Xanh dương → (B).\n(A), (C) là các hoạt động khác trong ngày, không phải lúc 3 giờ chiều.\n(A) Ở khu làm việc của cô trong Tòa nhà Vàng\n(B) Ở sảnh Tòa nhà Xanh dương\n(C) Ở phòng hội nghị Tòa nhà Vàng\n(D) Ở văn phòng của cô Holland"},{"n":199,"q":"What is suggested about guided tours at Jacobi Technologies?","qvi":"Điều gì được ngụ ý về các chuyến tham quan có hướng dẫn ở Jacobi Technologies?","opts":["They are open to both employees and nonemployees.","They stop at both indoor sites and outdoor sites.","They last approximately two hours.","They include a brief talk by a researcher."],"ans":"B","xp":"Câu hỏi suy luận (kết hợp 2 đoạn văn). E-mail thứ hai: \"The tour will include stops at the labs, our sustainable power plant, and all employee amenities.\" Trang web: tiện ích cho nhân viên gồm \"two cafés, a gym, outdoor basketball and tennis courts, and a childcare center\" → chuyến tham quan dừng ở cả nơi trong nhà (phòng thí nghiệm, quán cà phê, phòng gym) và ngoài trời (sân bóng rổ, quần vợt ngoài trời) → (B).\n(A) sai: tour dành cho nhân viên mới. (C) sai: \"last about an hour\" (khoảng một tiếng). (D) không được nhắc đến.\n(A) Chúng mở cửa cho cả nhân viên và người ngoài công ty.\n(B) Chúng dừng ở cả địa điểm trong nhà và ngoài trời.\n(C) Chúng kéo dài khoảng hai tiếng.\n(D) Chúng có phần nói chuyện ngắn của một nhà nghiên cứu."},{"n":200,"q":"According to the Web page, what is true about Jacobi Technologies?","qvi":"Theo trang web, điều gì đúng về Jacobi Technologies?","opts":["It will soon open a childcare facility.","It acquired the Naperville property ten years ago.","It charges employees a fee to use the company gym.","It operates more than one campus."],"ans":"D","xp":"Câu hỏi chi tiết. \"The company has more than 8,000 employees in Naperville, Illinois, and another 4,000 in Providence, Rhode Island.\" → công ty có cơ sở ở hai nơi (Naperville và Providence) → hoạt động ở hơn một khuôn viên → (D).\n(A) sai: trung tâm giữ trẻ đã có sẵn (\"the campus boasts... a childcare center\"). (B) sai: công ty mua khu đất năm 1950; \"ten\" là số tòa nhà. (C) không được nhắc đến.\n(A) Công ty sắp mở một cơ sở giữ trẻ.\n(B) Công ty mua khu đất Naperville cách đây mười năm.\n(C) Công ty thu phí nhân viên khi sử dụng phòng gym.\n(D) Công ty hoạt động ở hơn một khuôn viên."}]}]}};
